insert into public.exams (id, slug, name, description, is_active) values ('a1000000-0000-4000-8000-000000000001', 'plab1', 'PLAB 1', 'PLAB 1 single best answer study bank (PLABoratory).', true) on conflict (slug) do update set name = excluded.name, is_active = true;
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('49918cbb-97e6-5f3e-a32c-9f09c9314951', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 23 year old woman is unable to extend the fingers of her right hand at the metacarpophalangeal and interphalangeal joints after an accident. Which tendon is MOST likely to have been damaged?', 'Extensor digitorum (posterior interosseous branch of the radial nerve) extends the fingers at the MCP joints and, through the extensor expansion, helps extend the IP joints. The carpal extensors (ECRL/ECRB, ECU) extend and deviate the wrist, not the fingers. Extensor pollicis longus extends the thumb only. Flexor digitorum profundus flexes the distal interphalangeal joints.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
