  ('259c7d4f-469f-5678-9b93-2dc5b7fbfeda', '93a92741-afb8-5790-a53d-f067988ffaeb', 'A', 'Fracture of the neck of femur', true, 0),
  ('7dd4860a-5c2e-5308-80e8-7c9f5b13fa61', '93a92741-afb8-5790-a53d-f067988ffaeb', 'B', 'Posterior hip dislocation', false, 1),
  ('e4bcd3e0-c675-52fc-b563-8bcca38d253e', '93a92741-afb8-5790-a53d-f067988ffaeb', 'C', 'Fracture of the shaft of femur', false, 2),
  ('31230698-d2ea-5ea4-904f-1e240edb7258', '93a92741-afb8-5790-a53d-f067988ffaeb', 'D', 'Pelvic base fracture', false, 3),
