  ('abf64250-2d24-5515-8c4c-78104cc11f08', 'be02747e-1c6f-56de-a0e4-cd113ca4b6fc', 'B', 'Posterior capsulitis', false, 1),
  ('009c4510-7987-59e7-b318-853d82015452', 'be02747e-1c6f-56de-a0e4-cd113ca4b6fc', 'C', 'Ruptured supraspinatus tendon', false, 2),
  ('7bd78c70-8c9f-58d3-9e49-610149f70a1e', 'be02747e-1c6f-56de-a0e4-cd113ca4b6fc', 'D', 'Subacromial bursitis', false, 3),
  ('0a81b814-885f-5b00-afbe-43c0febdbd2f', 'be02747e-1c6f-56de-a0e4-cd113ca4b6fc', 'E', 'Adhesive capsulitis (frozen shoulder)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('14380c87-7789-5210-bc2c-ca922d4ae475', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 24 year old man presents with bizarre behaviour. Which SINGLE symptom would MOST strongly support a diagnosis of schizophrenia?', 'Thought insertion is a first-rank (Schneiderian) symptom of schizophrenia, along with thought withdrawal and broadcasting, third-person auditory hallucinations (running commentary, voices discussing the patient), passivity phenomena and delusional perception. Visual hallucinations suggest an organic cause (delirium, Lewy body dementia, drugs). Aggression and low mood are non-specific.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
