insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('97bd9221-c050-5984-b9ff-f3f5c23dd0f4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 2 year old girl is brought to the Emergency Department with bruises on her right anterior thigh and anterior leg. Her left ankle is swollen and she refuses to move it. She is crying inconsolably. The explanation given does not account for the injuries. What is the SINGLE most appropriate investigation?', 'Multiple injuries at different sites with an unexplained possible fracture in a young child should raise concern about non-accidental injury. A skeletal survey is the key investigation in children under 2 (and is considered in older children) to look for occult and old fractures (such as metaphyseal or rib fractures). FBC and a clotting screen are also done to exclude a bleeding disorder, but they are not the investigation of choice for suspected physical abuse. Follow local safeguarding procedures and involve a senior paediatrician.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
