  ('94d36ea8-3e38-5916-8ce0-ffbacb3b7715', '6486e664-9643-57e6-997f-eeeca23ba92a', 'E', 'Hypothyroidism', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b061b7c7-6b4d-55fa-acc0-f08fee67c7ba', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A patient has multiple painful ulcers on the buccal mucosa, with white lacy striae on the inside of the mouth and tongue. What is the SINGLE most likely diagnosis?', 'White lacy (Wickham''s) striae on the buccal mucosa, sometimes with painful erosive areas, are typical of oral lichen planus. Candida gives white plaques that can be wiped off to show red mucosa. Leukoplakia is a fixed white patch that cannot be rubbed off and is potentially premalignant. Erosive oral lichen planus carries a small risk of malignant change, so long-term review is advised. Ask about drug triggers (such as NSAIDs and beta-blockers).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
