  ('ac69bd80-d22c-542d-b22b-7b58743cb008', 'b061b7c7-6b4d-55fa-acc0-f08fee67c7ba', 'B', 'Oral squamous cell carcinoma', false, 1),
  ('be97a9e2-3490-59ac-afe0-6c8a598f9efb', 'b061b7c7-6b4d-55fa-acc0-f08fee67c7ba', 'C', 'Aphthous ulcers', false, 2),
  ('8cf93896-d044-57bb-bf5f-7a1660330887', 'b061b7c7-6b4d-55fa-acc0-f08fee67c7ba', 'D', 'Lichen planus', true, 3),
