insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4513da24-9839-5477-82ce-101e1f3eaa4a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A man is admitted with an open fracture of the femur after a road traffic accident. During induction of anaesthesia his BP drops to 60/40 mmHg and his HR is 130 bpm. What is the SINGLE most likely explanation?', 'A femoral shaft fracture can lose 1-1.5 L of blood, and more if open. Induction agents cause vasodilatation and blunt the sympathetic response that was compensating for hypovolaemia, so hypotension and tachycardia at induction are most likely due to unrecognised haemorrhage. Fat embolism typically appears 24-72 hours after the injury, with hypoxia, confusion and a petechial rash. Treat with blood products and haemorrhage control.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
