  ('06fa29ef-0b30-546a-a66e-1b4bf1093fa6', '5e5f3e66-0313-5da1-b2b0-e73b9effb3e1', 'E', 'X-linked dominant', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('abeef2dc-36c5-51c8-a0bd-7aaf98de1602', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A patient who came from India presents with cough, fever and an enlarged cervical lymph node. Biopsy of the lymph node shows caseating granulomas. What is the SINGLE most likely diagnosis?', 'Caseating granulomas are characteristic of tuberculosis. Cervical TB lymphadenitis (scrofula) is the most common form of extrapulmonary TB, especially in people from high-prevalence countries. Send tissue for mycobacterial culture and PCR, and treat with standard quadruple therapy (rifampicin, isoniazid, pyrazinamide and ethambutol) for 6 months. Sarcoidosis gives non-caseating granulomas.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
