  ('f5182df7-c4a9-5e93-9081-63c095353e33', 'abeef2dc-36c5-51c8-a0bd-7aaf98de1602', 'A', 'Lymphoma', false, 0),
  ('db10d3f3-22ad-5ff3-805f-e3471edfd250', 'abeef2dc-36c5-51c8-a0bd-7aaf98de1602', 'B', 'Tuberculous lymphadenitis', true, 1),
  ('2c99a7e5-15f9-5df3-a9c3-f4356b5bb467', 'abeef2dc-36c5-51c8-a0bd-7aaf98de1602', 'C', 'Thyroid carcinoma', false, 2),
