insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('70a147f7-a987-5f85-84b1-8cd590818004', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A patient has severe pain and vomiting after surgery. What is the SINGLE most appropriate analgesic to give?', 'Severe acute pain needs a strong opioid, and vomiting means oral drugs will not be reliably absorbed, so IV morphine (titrated, ideally as patient-controlled analgesia) is the most appropriate choice, with an antiemetic. Transdermal patches take 12-24 hours to reach steady state and are unsuitable for acute pain in opioid-naive patients. Use multimodal analgesia (regular paracetamol, NSAID if not contraindicated) alongside.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
