  ('9a3330a8-ffb3-59b7-a348-e8421b3d5bc4', '70a147f7-a987-5f85-84b1-8cd590818004', 'D', 'Transdermal fentanyl patch', false, 3),
  ('99318e61-1d0d-5c4b-8e6d-50cb15c65497', '70a147f7-a987-5f85-84b1-8cd590818004', 'E', 'Oral codeine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7f43737c-c03f-5a9f-bb80-5c96b2c42df7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 13 year old girl has a 2-day history of hoarseness with a dry cough. She feels feverish. On laryngoscopy her vocal cords are grossly oedematous. What is the SINGLE most appropriate investigation?', 'A short history of hoarseness with coryzal symptoms and oedematous vocal cords is acute viral laryngitis. It is self-limiting and needs no investigation: advise voice rest, fluids and analgesia. Hoarseness persisting for more than 3 weeks (especially in a smoker over 45) needs a suspected cancer referral to ENT.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
