  ('8bed42a9-068c-59b7-ac27-bf6e3c83eae4', '7f43737c-c03f-5a9f-bb80-5c96b2c42df7', 'A', 'No investigation required', true, 0),
  ('fe8ad549-c0b8-5f26-b32e-5fc8a6f1be20', '7f43737c-c03f-5a9f-bb80-5c96b2c42df7', 'B', 'Sputum for acid-fast bacilli', false, 1),
  ('203041c9-79ab-5f38-957f-bcfc836426d0', '7f43737c-c03f-5a9f-bb80-5c96b2c42df7', 'C', 'Repeat laryngoscopy', false, 2),
  ('2ad380ca-e299-58d9-b179-3a64bf499a28', '7f43737c-c03f-5a9f-bb80-5c96b2c42df7', 'D', 'Bronchoscopy', false, 3),
  ('8c98c8dd-bc9e-5617-9f0d-e38f31d0de74', '7f43737c-c03f-5a9f-bb80-5c96b2c42df7', 'E', 'Cervical spine X-ray', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('789d7068-ce1c-5655-a9ec-7dcad80a1b00', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 53 year old woman has a spleen palpable down to the umbilicus. Blood tests show Hb 87 g/L, WCC 100 x10^9/L and platelets 72 x10^9/L. What is the SINGLE most likely diagnosis?', 'Massive splenomegaly with a very high white cell count in a middle-aged adult suggests chronic myeloid leukaemia. The film shows granulocytes at all stages of maturation, often with basophilia. The Philadelphia chromosome t(9;22) (BCR-ABL1) confirms it, and first-line treatment is a tyrosine kinase inhibitor such as imatinib. CLL gives a lymphocytosis with smudge cells and only modest splenomegaly. Other causes of massive splenomegaly are myelofibrosis, visceral leishmaniasis and malaria.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
