  ('58215d88-b274-5875-8678-d66e2d731ef9', '789d7068-ce1c-5655-a9ec-7dcad80a1b00', 'A', 'Chronic myeloid leukaemia', true, 0),
  ('351b48b1-2221-5dd2-9551-cc1d22f300d6', '789d7068-ce1c-5655-a9ec-7dcad80a1b00', 'B', 'Chronic lymphocytic leukaemia', false, 1),
  ('03ae0583-36ed-56c4-ab7a-6946874e07f0', '789d7068-ce1c-5655-a9ec-7dcad80a1b00', 'C', 'Acute myeloid leukaemia', false, 2),
  ('ed52c469-481f-55d1-ab0a-f101ecade735', '789d7068-ce1c-5655-a9ec-7dcad80a1b00', 'D', 'Lymphoma', false, 3),
