insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bf06030a-375c-5771-9d52-f2f7a1fd3e83', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'For a patient with Parkinson''s disease, which ONE of the following drugs has traditionally been considered MOST useful for the management of tremor?', 'Antimuscarinics such as trihexyphenidyl (benzhexol) mainly reduce tremor rather than bradykinesia, which is why they are the classic exam answer. In practice they are now used sparingly, mainly in younger patients with tremor-dominant disease, because of confusion, urinary retention and cognitive side effects, especially in older people. Levodopa remains the most effective overall treatment. Amantadine is used mainly for dyskinesia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
