  ('5cd08770-b16d-55fc-8bb0-134383e8ca1b', 'bf06030a-375c-5771-9d52-f2f7a1fd3e83', 'B', 'Cabergoline', false, 1),
  ('1b181d2d-11f8-5d68-9112-c5f8ff4c9ac5', 'bf06030a-375c-5771-9d52-f2f7a1fd3e83', 'C', 'Selegiline', false, 2),
  ('012ab93d-e171-58bd-ae1e-2bb4fb9151c6', 'bf06030a-375c-5771-9d52-f2f7a1fd3e83', 'D', 'Amantadine', false, 3),
  ('2925e4a4-ea4a-5f41-b750-4caa121b75ca', 'bf06030a-375c-5771-9d52-f2f7a1fd3e83', 'E', 'Trihexyphenidyl (benzhexol)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('350299d4-7177-5722-8956-b9dd83fc0c3d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 53 year old man has had a 1 cm lesion on his arm for a long time. It has recently started bleeding when touched. What is the SINGLE most likely diagnosis?', 'A long-standing, slowly growing lesion that has started to bleed with minor trauma is typical of a basal cell carcinoma (a pearly nodule with telangiectasia that may ulcerate into a ''rodent ulcer''). SCC grows faster and is often tender and keratotic. Keratoacanthoma grows rapidly over weeks. Any change in a pigmented lesion (bleeding, change in size or colour) should prompt assessment for melanoma using the 7-point checklist.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
