  ('a77be7d9-504b-51a3-80f7-7da90d8e5253', '350299d4-7177-5722-8956-b9dd83fc0c3d', 'B', 'Kaposi''s sarcoma', false, 1),
  ('18e29bac-2a58-5af7-8260-f2694c485d17', '350299d4-7177-5722-8956-b9dd83fc0c3d', 'C', 'Malignant melanoma', false, 2),
  ('aa3c195c-02c1-5e04-bbb2-3146efe011c8', '350299d4-7177-5722-8956-b9dd83fc0c3d', 'D', 'Squamous cell carcinoma', false, 3),
  ('94d658f2-aa0d-55fe-98d3-b726641d06c6', '350299d4-7177-5722-8956-b9dd83fc0c3d', 'E', 'Keratoacanthoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('77eb2f34-a9e2-5a6b-b83a-580d471724f0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 19 year old man presents with a runny nose, cough and a generalised rash. Blood cultures grow coagulase-positive Gram-positive cocci in clusters. What is the SINGLE best antibiotic?', 'Coagulase-positive Gram-positive cocci in clusters are Staphylococcus aureus. For meticillin-sensitive S. aureus bacteraemia, the treatment of choice is IV flucloxacillin (vancomycin or teicoplanin if MRSA or penicillin allergy). S. aureus bacteraemia always needs a search for a source and echocardiography to exclude endocarditis. Amoxicillin is broken down by staphylococcal penicillinase.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
