insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e0757263-40ba-5fad-b32a-363fb9b167a9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 64 year old man believes that a female newsreader is communicating directly with him when she turns a page. What type of delusion is this?', 'A delusion of reference is the belief that neutral events, objects or other people''s actions (such as TV, radio or newspapers) carry a special personal meaning for the patient. Persecutory delusions are beliefs of being harmed or plotted against. Delusions of control (passivity) are beliefs that one''s actions or thoughts are controlled by an outside agency. Nihilistic delusions (Cotard''s) are beliefs that one is dead or rotting.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
