  ('b08ad580-429f-5f82-b946-3fadebf9b33d', 'e0757263-40ba-5fad-b32a-363fb9b167a9', 'A', 'Persecutory', false, 0),
  ('46d757c5-7e9d-5034-b8f0-be6b8faa012a', 'e0757263-40ba-5fad-b32a-363fb9b167a9', 'B', 'Delusion of control', false, 1),
  ('407be99f-45e4-56ae-8869-d2f782929e45', 'e0757263-40ba-5fad-b32a-363fb9b167a9', 'C', 'Grandiose', false, 2),
  ('d1116d4d-c2e2-583b-904a-27f0b166de20', 'e0757263-40ba-5fad-b32a-363fb9b167a9', 'D', 'Nihilistic', false, 3),
  ('10fc064b-57bd-50c3-a133-6ffbf3eae272', 'e0757263-40ba-5fad-b32a-363fb9b167a9', 'E', 'Delusion of reference', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6126aa36-55c4-53e2-a5e3-8975ab41df40', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A woman presents with an ectopic pregnancy. Which is the MOST important risk factor for this?', 'Tubal damage from previous pelvic inflammatory disease (most often due to Chlamydia trachomatis) is the most important risk factor for ectopic pregnancy. Others include previous ectopic pregnancy, tubal surgery or sterilisation, IVF, smoking, older maternal age and pregnancy with an IUD in place. Hormonal contraception reduces the absolute risk of any pregnancy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
