  ('02f2dacb-0dbe-534f-9b1c-43003b42bed8', '6126aa36-55c4-53e2-a5e3-8975ab41df40', 'A', 'Polycystic ovary syndrome', false, 0),
  ('449792e3-24a2-5262-a087-d4219ee1285a', '6126aa36-55c4-53e2-a5e3-8975ab41df40', 'B', 'Previous pelvic inflammatory disease due to chlamydia', true, 1),
  ('ac9387b6-554a-5c60-9572-49cff2bbaae8', '6126aa36-55c4-53e2-a5e3-8975ab41df40', 'C', 'Depot medroxyprogesterone (Depo-Provera) use', false, 2),
  ('ae8744c8-c9d3-5610-9553-a51b5b7ae338', '6126aa36-55c4-53e2-a5e3-8975ab41df40', 'D', 'Uterine instrumentation', false, 3),
  ('c4d176a7-62ca-5feb-8888-b38288f570ae', '6126aa36-55c4-53e2-a5e3-8975ab41df40', 'E', 'Combined oral contraceptive use', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5dd1820c-62cf-5479-8410-2f228e45aa2a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 6 week old breastfed baby has prolonged jaundice attributed to breast milk jaundice. He is feeding well, gaining weight and not dehydrated, with normal-coloured stools and urine. Which bilirubin profile (in µmol/L) would be MOST consistent with this?', 'Breast milk jaundice is a benign, unconjugated hyperbilirubinaemia in a well, thriving breastfed baby. The bilirubin is mildly raised and the conjugated fraction is low (under about 20%, and here under 5%). A high conjugated fraction (over 25 µmol/L or over 20% of total) is never normal: think biliary atresia (pale stools, dark urine) and refer urgently. Note: the original question said ''6 months''. Breast milk jaundice normally settles by about 12 weeks, so the age has been changed to 6 weeks, and the units are assumed to be µmol/L.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c596525f-dbe4-5085-91bf-ab08007a12fb', '5dd1820c-62cf-5479-8410-2f228e45aa2a', 'A', 'Total bilirubin 40, conjugated less than 5%', true, 0),
  ('4ac7a176-ac98-5a8a-9715-dbbf45255bd0', '5dd1820c-62cf-5479-8410-2f228e45aa2a', 'B', 'Total bilirubin 300, conjugated 85%', false, 1),
  ('eceed1b5-27af-5a47-92ec-60aec4bf46c5', '5dd1820c-62cf-5479-8410-2f228e45aa2a', 'C', 'Total bilirubin 500, conjugated more than 85%', false, 2),
  ('ee52e0d3-3764-5e89-8fcb-2982be8e8cfa', '5dd1820c-62cf-5479-8410-2f228e45aa2a', 'D', 'Total bilirubin 400, conjugated less than 85%', false, 3),
  ('8aadc1f8-d531-5b81-83cd-4db87b3f0af5', '5dd1820c-62cf-5479-8410-2f228e45aa2a', 'E', 'Total bilirubin 500, conjugated less than 70%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('68a95915-ba11-5d48-9b94-6e58da2cf21b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 56 year old man with atrial fibrillation is started on digoxin. Which side effect should you specifically warn him about as a sign of toxicity?', 'Visual disturbance (xanthopsia, blurred vision and haloes) is characteristic of digoxin toxicity. Gastrointestinal symptoms (nausea, vomiting, diarrhoea) are actually the most common early features, so this is a ''most specific'' rather than ''most common'' question. Toxicity is made worse by hypokalaemia, hypomagnesaemia, hypercalcaemia, renal impairment and interacting drugs (amiodarone, verapamil, clarithromycin). Treat severe toxicity with digoxin-specific antibody fragments (DigiFab). Gingival hyperplasia is seen with phenytoin, ciclosporin and calcium channel blockers.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8f9e1bf0-d1dd-5f75-89a0-dc6a091829a5', '68a95915-ba11-5d48-9b94-6e58da2cf21b', 'A', 'Visual disturbance such as yellow-green vision or haloes', true, 0),
  ('93dbb57c-a68b-5901-930f-40e9602099e4', '68a95915-ba11-5d48-9b94-6e58da2cf21b', 'B', 'Nausea', false, 1),
  ('df75c087-83c2-536a-8322-8c65774e4f22', '68a95915-ba11-5d48-9b94-6e58da2cf21b', 'C', 'Vomiting', false, 2),
  ('7216b9bc-293d-561a-97b8-9f5f2e42f39a', '68a95915-ba11-5d48-9b94-6e58da2cf21b', 'D', 'Diarrhoea', false, 3),
  ('6c1c1c93-d3fe-51d4-8bc7-b0cc5377f2f2', '68a95915-ba11-5d48-9b94-6e58da2cf21b', 'E', 'Gingival hyperplasia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('62f75fec-b900-504d-aef6-25a08bdab7a4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A patient presents 4 days after a myocardial infarction with pain on inspiration that makes it difficult to breathe comfortably. The pain is relieved by sitting forward. What is the SINGLE most likely diagnosis?', 'Pleuritic chest pain that is better sitting forward, 1-3 days after a transmural MI, is early post-infarction pericarditis (there may be a pericardial rub). Dressler''s syndrome is an autoimmune pericarditis that occurs weeks to months (typically 2-6 weeks) after an MI, with fever and a raised ESR. Echocardiography should exclude an effusion or a mechanical complication. Note: ''relieved by sitting forward'' has been added to the original stem to make it discriminating.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3edeb130-72ef-548f-84cc-90bac28fe872', '62f75fec-b900-504d-aef6-25a08bdab7a4', 'A', 'Acute pericarditis', true, 0),
  ('2e86987c-357c-50bd-96c4-215eb844b659', '62f75fec-b900-504d-aef6-25a08bdab7a4', 'B', 'Angina', false, 1),
  ('5c968003-8fff-5f05-8610-ecc8f1047bd2', '62f75fec-b900-504d-aef6-25a08bdab7a4', 'C', 'Pancreatitis', false, 2),
  ('78bf9138-a05c-50bc-9d26-d85b1d750653', '62f75fec-b900-504d-aef6-25a08bdab7a4', 'D', 'Cholecystitis', false, 3),
  ('063d84b1-b4fc-5a03-bf8d-87c2e3d70df2', '62f75fec-b900-504d-aef6-25a08bdab7a4', 'E', 'Dressler''s syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dbd5d4b9-a471-50f9-afa7-c5605118ef83', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 57 year old man who had a myocardial infarction a few months ago has been in low mood. A diagnosis of moderate depression has been made. Which medication is the SINGLE best treatment for him?', 'Sertraline is the antidepressant of choice after an MI or in coronary heart disease, as its cardiac safety has been studied (SADHART trial). Tricyclics are arrhythmogenic and cause postural hypotension. MAOIs carry a risk of hypertensive crisis and many interactions. Note that SSRIs increase bleeding risk with antiplatelets, so consider a PPI. Psychological therapy (such as CBT) should also be offered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8fd577d5-ed10-50d7-97d7-8f697aaeb543', 'dbd5d4b9-a471-50f9-afa7-c5605118ef83', 'A', 'A selective serotonin reuptake inhibitor (e.g. sertraline)', true, 0),
  ('6bb77034-f431-5905-b886-1575c898def3', 'dbd5d4b9-a471-50f9-afa7-c5605118ef83', 'B', 'A tricyclic antidepressant', false, 1),
  ('91e1f6cf-b536-533d-8948-c1cc97ac1d92', 'dbd5d4b9-a471-50f9-afa7-c5605118ef83', 'C', 'A monoamine oxidase inhibitor', false, 2),
  ('247acf81-0573-5bb0-b6bc-31b132cd48bd', 'dbd5d4b9-a471-50f9-afa7-c5605118ef83', 'D', 'A benzodiazepine', false, 3),
  ('7bd90a24-48be-5df2-82d0-7d230b537881', 'dbd5d4b9-a471-50f9-afa7-c5605118ef83', 'E', 'A mood stabiliser', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('67caaa76-eaf0-5194-a51f-860b55ff1464', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 32 year old woman has recurrent breast abscesses; the most recent was 6 weeks ago. There is an area of induration at the edge of the areola that is discharging pus through a small opening in the skin. She smokes. What is the SINGLE most likely diagnosis?', 'A recurrent periareolar abscess with a chronic discharging opening at the areolar margin is a mammary duct (periductal) fistula: a tract between a subareolar duct and the skin. It is a complication of periductal mastitis, which is strongly associated with smoking. Treatment is surgical excision of the fistula and the affected duct (total duct excision for recurrent disease), along with stopping smoking.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6f7b21d2-27a1-5e95-b841-681402f603ac', '67caaa76-eaf0-5194-a51f-860b55ff1464', 'A', 'Mastitis', false, 0),
  ('1085fe4b-7872-5a91-8f1f-d5e86f560810', '67caaa76-eaf0-5194-a51f-860b55ff1464', 'B', 'Breast abscess', false, 1),
  ('622a5f6f-7b92-5ab5-b87e-bf2195299b39', '67caaa76-eaf0-5194-a51f-860b55ff1464', 'C', 'Duct ectasia', false, 2),
  ('bf7dfce6-56c9-507d-a97c-16cc6714cf25', '67caaa76-eaf0-5194-a51f-860b55ff1464', 'D', 'Mammary duct fistula', true, 3),
  ('d752cc88-933c-5291-914d-b0e15a3680f1', '67caaa76-eaf0-5194-a51f-860b55ff1464', 'E', 'Intraductal papilloma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ac0e3b12-5a35-5071-b2ae-d1cc6cb9af05', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'An 18 year old student, previously well, is in his first year at university. He has been brought to the Emergency Department agitated, deluded and disoriented. What is the SINGLE most likely cause?', 'In a previously well young person, an acute confusional state with agitation and delusions is most often caused by recreational drug intoxication (such as stimulants, cannabinoids or hallucinogens). Delirium tremens needs prolonged heavy alcohol dependence. Still check glucose, take a collateral history, examine for head injury and signs of infection (meningitis/encephalitis), and do a urine drug screen.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d8667d65-a5c6-57ef-a81e-2810a2db4497', 'ac0e3b12-5a35-5071-b2ae-d1cc6cb9af05', 'A', 'Drug toxicity', true, 0),
  ('3c98eb5f-d41a-57b1-8e42-d17908a56d9c', 'ac0e3b12-5a35-5071-b2ae-d1cc6cb9af05', 'B', 'Delirium tremens', false, 1),
  ('6b9ddd66-765b-556d-b0ba-d676d2976b98', 'ac0e3b12-5a35-5071-b2ae-d1cc6cb9af05', 'C', 'Infection-related delirium', false, 2),
  ('38309420-24d4-5622-8296-d861444481e8', 'ac0e3b12-5a35-5071-b2ae-d1cc6cb9af05', 'D', 'Electrolyte imbalance', false, 3),
  ('ff6f2071-8342-50c4-8f82-b351cd686d73', 'ac0e3b12-5a35-5071-b2ae-d1cc6cb9af05', 'E', 'Head injury', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('05b1175d-5ac6-5d96-9fa0-f8d7f859e67f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 50 year old man lost his job because he was unreliable and is now homeless. Police bring him to the Emergency Department in a very agitated state; they found him wandering and muttering about a plot to kill him. He is confused, tremulous, unkempt and smells of stale sweat. What is the SINGLE most important initial management?', 'The picture (likely alcohol dependence, social decline, acute confusion, agitation, paranoia and tremor) suggests alcohol withdrawal delirium (delirium tremens), a medical emergency. Benzodiazepines are first-line (oral chlordiazepoxide or lorazepam, or parenteral if oral not possible). Give IV thiamine (Pabrinex) for Wernicke''s prophylaxis, check capillary glucose straight away, and correct electrolytes (magnesium, potassium, phosphate). Antipsychotics lower the seizure threshold and are not first-line.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2d0c5566-a5c8-5a27-a42c-2298c131127b', '05b1175d-5ac6-5d96-9fa0-f8d7f859e67f', 'A', 'IV antipsychotics', false, 0),
  ('5627a508-12f5-589a-9fdb-5901731f0ecf', '05b1175d-5ac6-5d96-9fa0-f8d7f859e67f', 'B', 'IV benzodiazepines', true, 1),
  ('001d64d1-f3ce-5cdf-955a-81600c73959e', '05b1175d-5ac6-5d96-9fa0-f8d7f859e67f', 'C', 'IV glucose', false, 2),
  ('2d550b87-356e-5ba3-8a91-0207dfec87da', '05b1175d-5ac6-5d96-9fa0-f8d7f859e67f', 'D', 'IV antibiotics', false, 3),
  ('b5c0316c-0ca9-57e5-86ef-7069e3d42650', '05b1175d-5ac6-5d96-9fa0-f8d7f859e67f', 'E', 'Oral lithium', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('956d9ff6-b3b6-5e4e-a429-8e30eb27849d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 65 year old woman had a colonic tumour excised 3 years ago. She is now losing weight and feels lethargic. She is pale but has no abdominal findings. Which tumour marker is MOST appropriate to check?', 'CEA is used in colorectal cancer follow-up to detect recurrence (with CT of the chest, abdomen and pelvis). It is not used for screening or diagnosis because it lacks sensitivity and specificity. CA 125 is used for ovarian cancer, CA 15-3 for breast cancer, CA 19-9 for pancreatic and biliary cancer, and AFP for hepatocellular carcinoma and germ cell tumours.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('81dbab74-4deb-5e0a-91de-96323641c375', '956d9ff6-b3b6-5e4e-a429-8e30eb27849d', 'A', 'CA 125', false, 0),
  ('b1ce8ed4-fb6c-571f-a82b-9e43312c1b28', '956d9ff6-b3b6-5e4e-a429-8e30eb27849d', 'B', 'CA 15-3', false, 1),
  ('6c0b8d7f-b554-57cd-bf58-599280e28a52', '956d9ff6-b3b6-5e4e-a429-8e30eb27849d', 'C', 'CA 19-9', false, 2),
  ('17d0ecc9-f52f-5b51-ad2f-7f7b94360fe8', '956d9ff6-b3b6-5e4e-a429-8e30eb27849d', 'D', 'Carcinoembryonic antigen (CEA)', true, 3),
  ('d0b26a92-c9c6-5a29-9def-277a72e36088', '956d9ff6-b3b6-5e4e-a429-8e30eb27849d', 'E', 'Alpha-fetoprotein', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('56e7038f-7e45-5c93-b4eb-295b4ccf52d7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 34 year old man has a white patch on the lateral margin of the middle third of his tongue. Which lymph nodes would this area drain to FIRST?', 'Lymph from the lateral margins of the anterior two-thirds of the tongue drains first to the submandibular nodes and then to the deep cervical nodes. The tip drains to the submental nodes, the central part can drain bilaterally, and the posterior third drains directly to the deep cervical (jugulo-omohyoid/jugulodigastric) nodes. A persistent white patch (leukoplakia) over 3 weeks needs referral to exclude oral cancer. Note: the original 8 options have been reduced to 5.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a724196c-d599-5eae-973f-2f354c8533f6', '56e7038f-7e45-5c93-b4eb-295b4ccf52d7', 'A', 'Submental lymph nodes', false, 0),
  ('3e9baa5a-a94e-596d-bfb8-fd15c89684c6', '56e7038f-7e45-5c93-b4eb-295b4ccf52d7', 'B', 'Submandibular lymph nodes', true, 1),
  ('d06217f3-c815-5e7a-a3d4-29835aee528f', '56e7038f-7e45-5c93-b4eb-295b4ccf52d7', 'C', 'Deep cervical lymph nodes', false, 2),
  ('0d8c247f-04c8-5200-a8fa-99f20a2580a2', '56e7038f-7e45-5c93-b4eb-295b4ccf52d7', 'D', 'Inguinal lymph nodes', false, 3),
  ('93169f10-4140-53e6-ab9e-6f29f6601757', '56e7038f-7e45-5c93-b4eb-295b4ccf52d7', 'E', 'External iliac lymph nodes', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b69a81e7-7b63-514d-b98e-4db2f377c0c3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 45 year old man presents to the Emergency Department with a sudden-onset severe headache and vomiting. He also has a stiff neck. He has hypertension and takes an ACE inhibitor. His BP is 180/110 mmHg, HR 88 bpm, RR 18/min and SpO2 98% on air. Neurological examination shows no focal deficit. What is the SINGLE most appropriate initial step?', 'A thunderclap headache with vomiting and meningism suggests subarachnoid haemorrhage. The first investigation is an urgent non-contrast CT head, which is most sensitive within 6 hours of onset. If CT is normal more than 6 hours after onset, do a lumbar puncture at least 12 hours after onset to look for xanthochromia. Thrombolysis is contraindicated until haemorrhage has been excluded.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5a3a5479-e7f5-5664-9388-a4671927d4d2', 'b69a81e7-7b63-514d-b98e-4db2f377c0c3', 'A', 'Lumbar puncture', false, 0),
  ('5012c734-dcad-5462-862a-edc86f837aab', 'b69a81e7-7b63-514d-b98e-4db2f377c0c3', 'B', 'MRI brain', false, 1),
  ('815bd0b3-1566-5f9b-b104-d2b9b00cd910', 'b69a81e7-7b63-514d-b98e-4db2f377c0c3', 'C', 'CT head without contrast', true, 2),
  ('e29aaf7e-fcfd-5acd-97b7-805166ab291c', 'b69a81e7-7b63-514d-b98e-4db2f377c0c3', 'D', 'CT head with contrast', false, 3),
  ('c15bb663-acc4-5a9f-b1dc-50f1ce46adda', 'b69a81e7-7b63-514d-b98e-4db2f377c0c3', 'E', 'IV thrombolysis with alteplase', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('003f306c-325a-567c-8b98-167a257d5a24', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 45 year old woman with terminal cancer asks for medication to end her life. The terminal nature of her condition has been confirmed by several doctors. She has no history of mental illness and has never expressed suicidal ideation before. She has been assessed as having full capacity. What is the SINGLE most appropriate response?', 'In England, Wales and Northern Ireland, encouraging or assisting suicide is a criminal offence (Suicide Act 1961), and euthanasia is murder (legislation on assisted dying is under debate, so check current law). GMC guidance is to listen, explore the reasons behind the request (pain, fear, loss of control, depression, feeling a burden), and offer palliative care and psychological support, without giving information that would help her end her life. Asking about suicide is not a crime, so there is no need to involve the police.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('14729e38-3403-541f-892b-3273f6fceb4c', '003f306c-325a-567c-8b98-167a257d5a24', 'A', 'Respect her request and refer her to assisted suicide services', false, 0),
  ('a0445190-9eb7-54c4-8409-74af6fca7aaf', '003f306c-325a-567c-8b98-167a257d5a24', 'B', 'Refer her to the mental health team', false, 1),
  ('d60114dc-12d9-55f7-8362-c0620147bd7d', '003f306c-325a-567c-8b98-167a257d5a24', 'C', 'Report her request to the police', false, 2),
  ('79986b51-fe9b-593c-a142-b0793e2493e1', '003f306c-325a-567c-8b98-167a257d5a24', 'D', 'Explore her concerns and encourage engagement with palliative care', true, 3),
  ('3e77e3e9-7f6c-5c2a-833e-880146832e29', '003f306c-325a-567c-8b98-167a257d5a24', 'E', 'Discuss her request with the MDT', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dae874f3-2963-5e77-be0d-dee49fc14488', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 75 year old man has a 3-day history of productive cough, right-sided chest pain and crepitations on auscultation. He has atrial fibrillation and takes rivaroxaban. Temperature 38.4°C, SpO2 95% on air, HR 95 bpm, BP 118/76 mmHg, RR 24/min. Bloods: Na 136 mmol/L, K 4.3 mmol/L, creatinine 72 µmol/L, urea 14.9 mmol/L, WCC 18.7 x10^9/L, Hb 123 g/L, CRP 104 mg/L. What is the SINGLE most likely diagnosis?', 'Productive cough, fever, focal crepitations, pleuritic pain, neutrophilia and a high CRP point to community-acquired pneumonia. NICE advises a chest X-ray to confirm it. His CURB-65 is 2 (urea over 7, age 65 or over), so it is moderate severity: consider hospital assessment, and give amoxicillin with or without a macrolide for 5 days. A PE is less likely as he is anticoagulated, and it would not explain the purulent sputum and very high inflammatory markers.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4cb098a1-a6b0-5927-ae4f-b561d8253e45', 'dae874f3-2963-5e77-be0d-dee49fc14488', 'A', 'Community-acquired pneumonia', true, 0),
  ('bd5e0dd6-ad3a-528c-83c5-7984c07b01a1', 'dae874f3-2963-5e77-be0d-dee49fc14488', 'B', 'Acute bronchitis', false, 1),
  ('c5759b47-95fa-5b19-8dc0-a5245175c12f', 'dae874f3-2963-5e77-be0d-dee49fc14488', 'C', 'Pleural effusion', false, 2),
  ('a309a2c8-a2d5-5140-bb7b-6855850139a6', 'dae874f3-2963-5e77-be0d-dee49fc14488', 'D', 'Pulmonary embolism', false, 3),
  ('5e202bbc-0262-518d-b4d5-9ca7b761880b', 'dae874f3-2963-5e77-be0d-dee49fc14488', 'E', 'Asthma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0398cf6f-1c34-52f8-b0ce-615f13b1040a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 55 year old woman has progressive fatigue, chest discomfort and increasing breathlessness. She has prominent peripheral oedema, and her ECG shows T-wave inversion in V1-V4. Based on NICE guidance, what is the SINGLE most appropriate next investigation to establish the underlying condition?', 'The picture suggests heart failure (possibly right ventricular strain or structural heart disease). NICE pathways use NT-proBNP to triage suspected chronic heart failure, but transthoracic echocardiography is the investigation that establishes the underlying structural or functional cause (ejection fraction, valve disease, RV function). If the chest discomfort is acute, troponin would be needed to exclude ACS.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ca87b3d1-cd1c-54ba-bb97-af12fd8ee471', '0398cf6f-1c34-52f8-b0ce-615f13b1040a', 'A', 'Full blood count', false, 0),
  ('f4f342c4-6fe0-554b-bfa8-3f0617388be5', '0398cf6f-1c34-52f8-b0ce-615f13b1040a', 'B', 'High-sensitivity troponin', false, 1),
  ('d9bd579c-19df-503a-b943-990d0d1e4b5b', '0398cf6f-1c34-52f8-b0ce-615f13b1040a', 'C', 'Chest X-ray', false, 2),
  ('44b62aae-f925-5250-9655-13ef35f910ff', '0398cf6f-1c34-52f8-b0ce-615f13b1040a', 'D', 'Echocardiogram', true, 3),
  ('511984bc-11f9-552f-9835-c5953b6c0e87', '0398cf6f-1c34-52f8-b0ce-615f13b1040a', 'E', 'Spirometry', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('92c41391-7c27-5051-8055-6a48f24dd81c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 35 year old male construction worker comes to occupational health with a painful, red, swollen index finger on his dominant hand. It started about 24 hours ago and is getting worse. The finger is warm and tender, with redness and swelling over the proximal interphalangeal joint. Neurovascular examination is normal. According to the source, what is the SINGLE most suitable initial step to give immediate relief and minimise complications?', 'The source keys cold compress and elevation as initial symptomatic relief for a presumed soft-tissue injury or inflammation. CAUTION: in real practice, a hot, red, swollen, tender joint must be treated as septic arthritis (or flexor sheath infection, in which case check Kanavel''s signs) until proven otherwise. That needs urgent assessment, aspiration or orthopaedic/hand surgery referral and antibiotics. Cold compress alone would be unsafe. Answer with care if this scenario appears with more detail.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bd7e7004-003f-5e59-8398-746b599ff38a', '92c41391-7c27-5051-8055-6a48f24dd81c', 'A', 'Oral antibiotics', false, 0),
  ('f428cf97-aefd-5195-9da7-ef2c1a98350f', '92c41391-7c27-5051-8055-6a48f24dd81c', 'B', 'Cold compress and elevation of the hand', true, 1),
  ('76fc9ec7-f160-5032-8164-d9df756d8b70', '92c41391-7c27-5051-8055-6a48f24dd81c', 'C', 'NSAIDs', false, 2),
  ('d3293ce1-d740-5c96-8cab-d8086d10cce9', '92c41391-7c27-5051-8055-6a48f24dd81c', 'D', 'Referral for urgent surgical drainage', false, 3),
  ('370e3ecc-cc2c-5701-bda4-7b7e5e066d51', '92c41391-7c27-5051-8055-6a48f24dd81c', 'E', 'Splint the finger and review in 2 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c041bb4e-f19c-53e5-ba07-66d58f1829b6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 25 year old woman is brought to the Emergency Department after being found unconscious in a park. She has a history of heroin use. She has pinpoint pupils and a low respiratory rate. Her breath smells of alcohol and empty beer bottles were found near her, but her blood alcohol concentration is within normal limits. Naloxone is given and her symptoms improve. What is the SINGLE most appropriate next step?', 'Naloxone has a shorter half-life (about 60-90 minutes) than most opioids, so respiratory depression can recur once it wears off. This is especially true with long-acting opioids (methadone) or heavy heroin use. She should be observed (often 4-6 hours or more, longer for methadone), and may need repeated doses or a naloxone infusion. Before discharge, offer take-home naloxone and referral to substance misuse services.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d7b2294e-8eea-5933-9bed-b490bb47b9d1', 'c041bb4e-f19c-53e5-ba07-66d58f1829b6', 'A', 'Discharge with a referral to a substance misuse clinic', false, 0),
  ('0556c570-a761-5711-8994-f36fbb0ae7d8', 'c041bb4e-f19c-53e5-ba07-66d58f1829b6', 'B', 'Admit for further observation and monitoring', true, 1),
  ('52245493-4d8c-5f1f-b086-670a6a3dae0e', 'c041bb4e-f19c-53e5-ba07-66d58f1829b6', 'C', 'Discharge with a prescription for take-home naloxone', false, 2),
  ('00de7e6d-03a1-53c2-bb14-a97038c6463a', 'c041bb4e-f19c-53e5-ba07-66d58f1829b6', 'D', 'Order a urine drug screen and discharge if negative', false, 3),
  ('9acab664-871d-5d08-8b52-97172ac8a4b0', 'c041bb4e-f19c-53e5-ba07-66d58f1829b6', 'E', 'Give education about drug use and discharge', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('94cde185-0dcf-5b19-bb98-d5f8fcbb14d7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 25 year old man with a history of anxiety and depression comes to the Emergency Department after an overdose of prescription medication. He is now medically fit for discharge. According to the source, what is the SINGLE most appropriate next step?', 'The source keys early outpatient follow-up. NOTE: NICE NG225 (self-harm, 2022) says everyone who self-harms should have a psychosocial assessment by a mental health professional (usually liaison psychiatry) BEFORE discharge from the Emergency Department, covering risk, needs and safety planning. Follow-up within a few days is then arranged based on that assessment. In the UK exam, ''liaison psychiatry assessment before discharge'' would be the safest answer if it is offered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7214ff02-e1db-5d0d-9e6a-32aa62a22dc8', '94cde185-0dcf-5b19-bb98-d5f8fcbb14d7', 'A', 'Arrange immediate inpatient psychiatric admission', false, 0),
  ('46601fe5-3699-5bd3-bf55-2a4c798a4f7a', '94cde185-0dcf-5b19-bb98-d5f8fcbb14d7', 'B', 'Schedule outpatient psychiatric follow-up within 24 hours', true, 1),
  ('68645ff6-0a33-5522-8427-93767f6ddd37', '94cde185-0dcf-5b19-bb98-d5f8fcbb14d7', 'C', 'Discharge to the care of his GP for further assessment', false, 2),
  ('740080e3-efe2-5307-8a72-bb6e689242ea', '94cde185-0dcf-5b19-bb98-d5f8fcbb14d7', 'D', 'Give a referral to a mental health support group', false, 3),
  ('3f340722-dca1-5bf3-a4c9-9839a1ea129a', '94cde185-0dcf-5b19-bb98-d5f8fcbb14d7', 'E', 'Offer referral to a crisis centre', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f784347f-8c82-599d-8735-73c41cb558a1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 28 year old man is brought to the Emergency Department after collapsing at a party where he had been taking recreational drugs all night. He is agitated, tachycardic, hypertensive and sweaty, with dilated pupils. There is no ocular clonus, hyperreflexia or rigidity, and no focal neurology. He has not taken anything for over an hour. What is the SINGLE most appropriate initial management?', 'This is a sympathomimetic toxidrome (such as cocaine, amphetamines or MDMA). Benzodiazepines are first-line: they reduce agitation, tachycardia, hypertension and the risk of seizures and hyperthermia. Avoid beta-blockers in cocaine toxicity. Check temperature, glucose, ECG (QRS/QT), CK and electrolytes (hyponatraemia with MDMA). The absence of clonus and hyperreflexia makes serotonin syndrome less likely.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('eea9eb81-74a3-52bf-88f7-7a09120332f1', 'f784347f-8c82-599d-8735-73c41cb558a1', 'A', 'Arrange psychiatric evaluation', false, 0),
  ('78760458-15da-53c3-9c7b-317b5d64b19b', 'f784347f-8c82-599d-8735-73c41cb558a1', 'B', 'Give IV benzodiazepines', true, 1),
  ('d1d22f3b-1706-5854-b5dd-a85aab4bcba1', 'f784347f-8c82-599d-8735-73c41cb558a1', 'C', 'Request laboratory tests for methamphetamine', false, 2),
  ('85aac2f3-0048-57a9-ab6d-53552fcba9ae', 'f784347f-8c82-599d-8735-73c41cb558a1', 'D', 'Refer to a substance misuse treatment centre', false, 3),
  ('364af8d5-8ecf-57e9-84d9-52a487ccba65', 'f784347f-8c82-599d-8735-73c41cb558a1', 'E', 'Discharge with advice to see his GP', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('099f1fe9-50bf-5283-9aa7-d526752bac35', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 45 year old man has fatigue, weight loss, a diffuse rash, lymphadenopathy and hepatosplenomegaly. Tests show anaemia, leukocytosis, thrombocytopenia, and raised LDH, calcium and creatinine. Bone marrow biopsy shows no Reed-Sternberg cells. What is the SINGLE most likely diagnosis?', 'Widespread lymphadenopathy, hepatosplenomegaly, skin involvement, high LDH and hypercalcaemia with marrow infiltration suggest an aggressive non-Hodgkin lymphoma (for example, adult T-cell leukaemia/lymphoma classically causes rash and hypercalcaemia). The absence of Reed-Sternberg cells argues against Hodgkin''s. Myeloma does not usually cause lymphadenopathy or splenomegaly. Diagnosis needs an excision lymph node biopsy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('80f48cc7-8beb-576c-9c27-f3d2c7cccb49', '099f1fe9-50bf-5283-9aa7-d526752bac35', 'A', 'Multiple myeloma', false, 0),
  ('036a314e-963d-5451-94b5-0d1236f337bb', '099f1fe9-50bf-5283-9aa7-d526752bac35', 'B', 'Hodgkin''s lymphoma', false, 1),
  ('83b94324-95e4-533d-a4a7-e3ac2d2a0d17', '099f1fe9-50bf-5283-9aa7-d526752bac35', 'C', 'Non-Hodgkin''s lymphoma', true, 2),
  ('76b5b362-5a9f-5ae9-865f-5b8bb9faeffb', '099f1fe9-50bf-5283-9aa7-d526752bac35', 'D', 'Leukaemia', false, 3),
  ('02b87ede-6c52-542f-9ba3-c4770e01dae0', '099f1fe9-50bf-5283-9aa7-d526752bac35', 'E', 'Myelodysplastic syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('73ff590c-444a-5d7f-b091-938f807492b4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 48 year old woman has had a sudden-onset severe headache and blurred vision for 2 hours, and it is getting worse. She has new drooping of the right eyelid. She has a history of migraine but says this headache is different. She has hypertension and had an anterolateral MI 3 years ago. She is afebrile with stable vital signs and no focal deficit apart from the right ptosis. What is the SINGLE most appropriate investigation?', 'A thunderclap headache with a new third nerve palsy (ptosis, with or without a dilated pupil) suggests an expanding or ruptured posterior communicating artery aneurysm causing subarachnoid haemorrhage. Urgent non-contrast CT head comes first, followed by CT angiography to identify the aneurysm. LP is done only if CT is negative and more than 6 hours have passed since onset. Do not dismiss it as migraine, because the headache is different from her usual ones.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ad108a30-ff19-53f0-afc3-af68a407c780', '73ff590c-444a-5d7f-b091-938f807492b4', 'A', 'CT scan of the head', true, 0),
  ('6cc59fc8-4d85-5992-89ac-d84b05d232a3', '73ff590c-444a-5d7f-b091-938f807492b4', 'B', 'Lumbar puncture', false, 1),
  ('8b956464-4bfa-533c-9486-d3e5dddb2acc', '73ff590c-444a-5d7f-b091-938f807492b4', 'C', 'MRI brain', false, 2),
  ('4139b870-8221-5ad1-b1c1-30eb6cc5bb7c', '73ff590c-444a-5d7f-b091-938f807492b4', 'D', 'Observation and reassessment', false, 3),
  ('a6720895-3d3f-5b42-9b48-d38fa3d7bc02', '73ff590c-444a-5d7f-b091-938f807492b4', 'E', 'Ophthalmological examination', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('86b143e5-0342-5d64-bb1b-6887298c05c5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 74 year old man has had palpitations and mild breathlessness for 2 days. He is haemodynamically stable. His 12-lead ECG is shown in the image. What is the SINGLE most likely diagnosis?', 'The ECG shows an irregularly irregular narrow-complex rhythm with no discernible P waves and a chaotic fibrillatory baseline: atrial fibrillation. Atrial flutter gives regular sawtooth flutter waves. Multifocal atrial tachycardia has at least 3 different P-wave shapes. Next steps: rate control (beta-blocker or rate-limiting calcium channel blocker) and assessing stroke risk with CHA2DS2-VASc (or CHA2DS2-VA in newer UK guidance) to decide on anticoagulation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/ECG_Atrial_Fibrillation_90_bpm.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('55fdf2f1-083f-5031-82c0-9dcfc2b2afe1', '86b143e5-0342-5d64-bb1b-6887298c05c5', 'A', 'Atrial flutter with variable block', false, 0),
  ('cdd39da8-749f-5988-b8cc-3dd2cffbe328', '86b143e5-0342-5d64-bb1b-6887298c05c5', 'B', 'Frequent ventricular ectopics', false, 1),
  ('ac45b10e-7cdb-5454-9b42-464050231883', '86b143e5-0342-5d64-bb1b-6887298c05c5', 'C', 'Atrial fibrillation', true, 2),
  ('c61158b3-0bbe-5f61-b0d0-d64bffe839ca', '86b143e5-0342-5d64-bb1b-6887298c05c5', 'D', 'Multifocal atrial tachycardia', false, 3),
  ('d9a0465f-ac7d-516d-9d8f-e056cdcdd6f7', '86b143e5-0342-5d64-bb1b-6887298c05c5', 'E', 'Sinus arrhythmia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('32a7dd40-cdad-57e7-afe9-57558759965d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 63 year old man has had central crushing chest pain for 1 hour, with sweating and nausea. His BP is 96/60 mmHg and HR 52 bpm. His ECG is shown in the image. Which coronary artery is MOST likely to be occluded?', 'The ECG shows ST elevation in the inferior leads (II, III and aVF): an inferior STEMI. Inferior MI is usually caused by right coronary artery occlusion (in about 80% of people, who are right-dominant). The RCA also supplies the SA and AV nodes, which explains the bradycardia. Get right-sided leads (V4R) to look for right ventricular infarction, and avoid nitrates if the RV is involved. Arrange primary PCI.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/ECG_001.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9ea3d6e6-0984-518a-b964-82787157f202', '32a7dd40-cdad-57e7-afe9-57558759965d', 'A', 'Left circumflex artery', false, 0),
  ('d51c213c-8186-5f96-95c9-f3022fee0392', '32a7dd40-cdad-57e7-afe9-57558759965d', 'B', 'Left main stem', false, 1),
  ('e3a184e9-1872-50b3-9053-dcce4303fe0c', '32a7dd40-cdad-57e7-afe9-57558759965d', 'C', 'Right coronary artery', true, 2),
  ('1d2fa4b9-2717-5b2d-8a59-f605962c06ed', '32a7dd40-cdad-57e7-afe9-57558759965d', 'D', 'Posterior descending branch of the left circumflex', false, 3),
  ('b35c973d-9063-540b-9971-5b86c9a68c09', '32a7dd40-cdad-57e7-afe9-57558759965d', 'E', 'Left anterior descending artery', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0dfde2e8-8fda-532c-b47b-91740bd54195', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 58 year old smoker has had severe central chest pain for 90 minutes. His ECG is shown in the image. A primary PCI centre is 30 minutes away. Which coronary artery is MOST likely to be occluded?', 'The image shows ST elevation across the precordial (chest) leads, consistent with an anterior STEMI, which points to an occluded left anterior descending (LAD) artery. Lateral changes (I, aVL, V5-V6) suggest the circumflex and inferior changes suggest the RCA. Since PCI can be delivered within 120 minutes, he should have primary PCI after aspirin and antithrombotic therapy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/ST_elevation_myocardial_infarction_ECG.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c6f58edf-a972-559c-839a-d0cc0ea21344', '0dfde2e8-8fda-532c-b47b-91740bd54195', 'A', 'Left circumflex artery', false, 0),
  ('98b4b1bc-86ac-5141-9722-497a640e306c', '0dfde2e8-8fda-532c-b47b-91740bd54195', 'B', 'Posterior descending artery', false, 1),
  ('9ab7c984-960a-5add-8618-410c66c67bd3', '0dfde2e8-8fda-532c-b47b-91740bd54195', 'C', 'Right coronary artery', false, 2),
  ('8f6e99a5-c9a3-5339-8b3b-30705bfe2197', '0dfde2e8-8fda-532c-b47b-91740bd54195', 'D', 'Left anterior descending artery', true, 3),
  ('726dfd32-1213-5003-b4af-3b6f9102dc94', '0dfde2e8-8fda-532c-b47b-91740bd54195', 'E', 'Marginal branch of the right coronary artery', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e7b7e41d-e9b8-5a8d-bbbe-7d02dabc7b9d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 79 year old woman has had several episodes of dizziness and one blackout over the last week. Her pulse is 34 bpm and regular. She takes no rate-limiting drugs. Her rhythm strip is shown in the image. What is the SINGLE most appropriate definitive management?', 'The image shows complete (third-degree) heart block: P waves and QRS complexes are completely dissociated, and a slow escape rhythm takes over. Symptomatic complete heart block (syncope, dizziness) needs a permanent pacemaker. In an emergency with haemodynamic compromise, IV atropine is tried first, then an isoprenaline or adrenaline infusion or transcutaneous pacing as a bridge. Rate-limiting drugs would make it worse.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/CompleteHeartBlock.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e1a3748c-11c0-5c31-86aa-f9a0983915ad', 'e7b7e41d-e9b8-5a8d-bbbe-7d02dabc7b9d', 'A', 'Permanent pacemaker insertion', true, 0),
  ('d1a50dc3-382a-547a-ab6a-90d40154e205', 'e7b7e41d-e9b8-5a8d-bbbe-7d02dabc7b9d', 'B', 'Oral bisoprolol', false, 1),
  ('e8bfa0b9-482a-5ad6-98d6-48f31ee62d17', 'e7b7e41d-e9b8-5a8d-bbbe-7d02dabc7b9d', 'C', 'Oral digoxin', false, 2),
  ('3cf8872f-221b-5525-80ba-ad8d3e732fda', 'e7b7e41d-e9b8-5a8d-bbbe-7d02dabc7b9d', 'D', 'Implantable cardioverter-defibrillator only', false, 3),
  ('f6a29448-82c5-53ba-b9f1-78c4deaf064a', 'e7b7e41d-e9b8-5a8d-bbbe-7d02dabc7b9d', 'E', 'Observation and repeat ECG in 6 months', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('449716c9-a4a9-5900-9f92-930ea19186f8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 22 year old tall, thin man had sudden-onset right-sided pleuritic chest pain and breathlessness while sitting at his desk. His oxygen saturation is 97% on air and he is haemodynamically stable. His chest X-ray is shown in the image. What is the SINGLE most likely diagnosis?', 'The X-ray shows a visible visceral pleural line with no lung markings beyond it on the right: a pneumothorax. In a young, tall, thin man with no lung disease this is a primary spontaneous pneumothorax. BTS guidance (2023) bases management on symptoms and stability rather than size alone: minimally symptomatic patients can be managed conservatively; otherwise needle aspiration or an ambulatory device is used. He should not fly until it has resolved, and should never dive unless he has had definitive surgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/09-01-Pneumothorax.png')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b1925008-5cab-5f11-87b3-ae8155e0343d', '449716c9-a4a9-5900-9f92-930ea19186f8', 'A', 'Pulmonary embolism', false, 0),
  ('5772a521-3fd6-5770-ba4b-4feff60377c1', '449716c9-a4a9-5900-9f92-930ea19186f8', 'B', 'Large right pleural effusion', false, 1),
  ('65df0f20-420c-58bf-a4b5-646b7399eafd', '449716c9-a4a9-5900-9f92-930ea19186f8', 'C', 'Right lower lobe pneumonia', false, 2),
  ('cec3f5ad-095c-5dff-abfe-07e9779bec5f', '449716c9-a4a9-5900-9f92-930ea19186f8', 'D', 'Primary spontaneous pneumothorax', true, 3),
  ('2ca8ee85-e060-5bfd-80ad-454b2905f917', '449716c9-a4a9-5900-9f92-930ea19186f8', 'E', 'Right upper lobe collapse', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8cbb5bfb-effe-502d-8bb8-f2669f9ea221', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 30 year old man was stabbed in the left chest. He is increasingly short of breath, his SpO2 is 84% on high-flow oxygen, his BP is 78/40 mmHg and his trachea is deviated to the right. A portable chest X-ray was taken before he deteriorated and is shown in the image. What is the SINGLE most appropriate immediate management?', 'The X-ray shows a large left pneumothorax with mediastinal and tracheal shift to the opposite side. With hypoxia and hypotension, this is a tension pneumothorax, which is a clinical diagnosis and should be decompressed immediately without waiting for imaging. ATLS advises needle decompression at the 4th/5th intercostal space just anterior to the mid-axillary line in adults (2nd intercostal space mid-clavicular line is an alternative), or finger thoracostomy, followed by a chest drain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pneumothorax_CXR.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0bf7350a-1107-5bd2-b0c9-4cb071f81242', '8cbb5bfb-effe-502d-8bb8-f2669f9ea221', 'A', 'Insert a right-sided chest drain', false, 0),
  ('f661d039-7f40-5852-86eb-bef71d797297', '8cbb5bfb-effe-502d-8bb8-f2669f9ea221', 'B', 'Wait for a CT chest', false, 1),
  ('efe69dcf-0208-5b55-bcc2-fea1b1a3192d', '8cbb5bfb-effe-502d-8bb8-f2669f9ea221', 'C', 'Immediate needle (or finger) decompression of the left chest', true, 2),
  ('1c5cb8b5-e8dc-5027-9bc5-b76b3253db41', '8cbb5bfb-effe-502d-8bb8-f2669f9ea221', 'D', 'Pericardiocentesis', false, 3),
  ('8100ba1c-0063-5836-b395-d5af6518af8d', '8cbb5bfb-effe-502d-8bb8-f2669f9ea221', 'E', 'Intubate and ventilate before any chest procedure', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a2ae557c-6116-5a5c-8dd6-1064664649dd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 68 year old man has had progressive breathlessness on exertion for 2 months. On examination there is stony dullness to percussion and absent breath sounds over the lower half of the left chest. His chest X-ray is shown in the image. What is the SINGLE most appropriate next investigation?', 'The X-ray shows a large left pleural effusion (homogeneous opacity with a meniscus, obliterating the costophrenic angle). In a unilateral effusion without an obvious cause such as heart failure, the next step is ultrasound-guided diagnostic pleural aspiration. Send fluid for protein, LDH, pH, glucose, microscopy and culture, and cytology. Light''s criteria separate exudates from transudates. A large symptomatic effusion can also be drained for relief.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Effusionhalf.PNG')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8eee696c-b320-52ae-8c65-5783e72116b1', 'a2ae557c-6116-5a5c-8dd6-1064664649dd', 'A', 'Spirometry', false, 0),
  ('fbe9f35d-652a-5ab5-aa38-d34e7b6d01fd', 'a2ae557c-6116-5a5c-8dd6-1064664649dd', 'B', 'Bronchoscopy', false, 1),
  ('95dbfa4f-3f70-5fe1-a0a3-ce763bbcaa4e', 'a2ae557c-6116-5a5c-8dd6-1064664649dd', 'C', 'Ultrasound-guided diagnostic pleural aspiration', true, 2),
  ('6ec9fee5-06f3-5426-9039-17412eeefc00', 'a2ae557c-6116-5a5c-8dd6-1064664649dd', 'D', 'Ventilation-perfusion (V/Q) scan', false, 3),
  ('4fd22ac0-8acf-5323-90c5-d2d3248d71fe', 'a2ae557c-6116-5a5c-8dd6-1064664649dd', 'E', 'Blind chest drain insertion', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6b8c4ac5-c2e4-52e4-9fb2-d9ebe72b5c06', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 71 year old retired joiner has had a dry cough and progressive breathlessness for 18 months. On examination there are fine end-inspiratory crackles at both lung bases. His hands are shown in the image. What is the SINGLE most likely diagnosis?', 'The image shows finger clubbing (loss of the angle between nail and nail fold, with increased curvature). Clubbing, fine "velcro" basal crackles, dry cough and progressive breathlessness in an older person suggest idiopathic pulmonary fibrosis. High-resolution CT shows a usual interstitial pneumonia pattern (basal, subpleural honeycombing). COPD does not cause clubbing. If a patient with COPD has clubbing, look for lung cancer. Antifibrotics (pirfenidone or nintedanib) can slow decline.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Clubbing_of_fingers_in_IPF.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4532aa6b-a63a-537e-80c8-a5487d3a0909', '6b8c4ac5-c2e4-52e4-9fb2-d9ebe72b5c06', 'A', 'Sarcoidosis', false, 0),
  ('272faf97-3ac2-5540-abf5-9d0330cdf5cb', '6b8c4ac5-c2e4-52e4-9fb2-d9ebe72b5c06', 'B', 'Bronchiectasis', false, 1),
  ('baaf1d68-4b80-5521-bc74-7ebd71d53de9', '6b8c4ac5-c2e4-52e4-9fb2-d9ebe72b5c06', 'C', 'Idiopathic pulmonary fibrosis', true, 2),
  ('2ca840e4-26eb-5b9c-90a4-292a8144c313', '6b8c4ac5-c2e4-52e4-9fb2-d9ebe72b5c06', 'D', 'Chronic obstructive pulmonary disease', false, 3),
  ('ebdb59d4-db1d-51a5-ada9-78d7623e0280', '6b8c4ac5-c2e4-52e4-9fb2-d9ebe72b5c06', 'E', 'Asthma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c95313c8-9c61-5ce3-89e6-d31915160c4f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 66 year old man has had fever, rigors and a productive cough with rusty sputum for 3 days. His temperature is 39.1°C, RR 24/min, BP 118/72 mmHg, urea 6.1 mmol/L, and he is alert. His chest X-ray is shown in the image. What is the SINGLE most likely causative organism?', 'The X-ray shows consolidation in the right upper lobe, consistent with lobar pneumonia. Streptococcus pneumoniae is the most common cause of community-acquired pneumonia and classically gives sudden fever, rigors, rusty sputum and lobar consolidation. His CURB-65 is 1 (age 65 or over only), so it is low severity: NICE suggests oral amoxicillin for 5 days. Mycoplasma usually affects younger people and gives patchy changes. Pneumocystis gives diffuse interstitial shadowing in the immunosuppressed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pneumonia_x_ray.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('559aaa6d-209a-58fd-94c3-9cfca3887fc8', 'c95313c8-9c61-5ce3-89e6-d31915160c4f', 'A', 'Mycoplasma pneumoniae', false, 0),
  ('a011e91e-85d4-5dff-af92-e9117a9b5705', 'c95313c8-9c61-5ce3-89e6-d31915160c4f', 'B', 'Legionella pneumophila', false, 1),
  ('ecd5a881-51c3-5aec-8b13-80a6661c366e', 'c95313c8-9c61-5ce3-89e6-d31915160c4f', 'C', 'Pneumocystis jirovecii', false, 2),
  ('40deb5af-96b0-555f-9917-ac886fd44075', 'c95313c8-9c61-5ce3-89e6-d31915160c4f', 'D', 'Streptococcus pneumoniae', true, 3),
  ('864bb511-47fc-59d9-b0de-a74bbb2f92ad', 'c95313c8-9c61-5ce3-89e6-d31915160c4f', 'E', 'Pseudomonas aeruginosa', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3be601ac-8418-5d9c-86fd-035eb7a65fbc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'An 84 year old care home resident with Parkinson''s disease and chronic constipation has had abdominal distension, pain and no flatus for 2 days. She has no signs of peritonitis. Her abdominal X-ray is shown in the image. What is the SINGLE most appropriate initial management?', 'The X-ray shows a hugely dilated loop of large bowel arising from the pelvis with a "coffee bean" appearance: sigmoid volvulus. Elderly, constipated, immobile or institutionalised patients and those with neurological disease are at risk. Without peritonitis or ischaemia, first-line treatment is endoscopic decompression with flatus tube insertion. Recurrence is common, so elective sigmoid colectomy is considered. Peritonitis or gangrene needs emergency surgery (Hartmann''s procedure).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sigmoidvolvulus.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('205ec790-dbe8-5dd8-964c-355da409adc7', '3be601ac-8418-5d9c-86fd-035eb7a65fbc', 'A', 'Endoscopic decompression with flexible sigmoidoscopy and flatus tube insertion', true, 0),
  ('6ed1a002-5b7e-5969-8b5e-2dae6ddde2a0', '3be601ac-8418-5d9c-86fd-035eb7a65fbc', 'B', 'Emergency laparotomy and right hemicolectomy', false, 1),
  ('1fd498ee-fcb8-5740-aff5-4eddacb7e98f', '3be601ac-8418-5d9c-86fd-035eb7a65fbc', 'C', 'Barium enema', false, 2),
  ('2aed7f19-e194-5ac2-92d4-95abae154c8e', '3be601ac-8418-5d9c-86fd-035eb7a65fbc', 'D', 'Oral macrogol laxatives and review in 48 hours', false, 3),
  ('a98b3a45-7379-5973-912e-463d155ec901', '3be601ac-8418-5d9c-86fd-035eb7a65fbc', 'E', 'Gastrografin small bowel follow-through', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e9c2019a-422e-597c-8a5f-fefea0e2a04b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 30 year old woman has had colicky central abdominal pain, abdominal distension and repeated bilious vomiting for 24 hours. She had an open appendicectomy 8 years ago. She has no hernias. Her abdominal X-ray is shown in the image. What is the SINGLE most likely cause of her condition?', 'The image shows dilated small bowel loops (central position, valvulae conniventes crossing the full width of the bowel), consistent with small bowel obstruction. In a patient with previous abdominal surgery and no hernia, adhesions are by far the most common cause. Initial management is "drip and suck": IV fluids, nasogastric decompression and analgesia, with water-soluble contrast (Gastrografin) to help predict resolution. Signs of strangulation or a closed loop need surgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Intestinal_Obstruction.JPG')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
