insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5cd95c76-2568-573f-984d-3a9be186d6ab', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 68 year old woman tripped and fell onto her outstretched hand. Her wrist is swollen with a "dinner fork" deformity. Her wrist X-ray is shown in the image. What is the SINGLE most likely diagnosis?', 'The X-ray shows a distal radius fracture with dorsal displacement and angulation of the distal fragment: a Colles'' fracture. A Smith''s fracture has volar (palmar) displacement. A Barton''s fracture is intra-articular with carpal subluxation. Galeazzi is a radial shaft fracture with distal radio-ulnar joint dislocation. A low-trauma fracture in an older woman is a fragility fracture, so she should be assessed for osteoporosis (FRAX and DEXA), as well as having fracture management.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Colles_fracture.JPG')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b1b75692-1869-5469-8142-5888724a7f04', '5cd95c76-2568-573f-984d-3a9be186d6ab', 'A', 'Galeazzi fracture-dislocation', false, 0),
  ('b9b51650-6833-5839-88b6-d6d6dc873c7c', '5cd95c76-2568-573f-984d-3a9be186d6ab', 'B', 'Colles'' fracture', true, 1),
  ('84f1fe98-d0d2-5d5f-ba2d-834d3f69c06f', '5cd95c76-2568-573f-984d-3a9be186d6ab', 'C', 'Smith''s fracture', false, 2),
  ('7acefa53-2ed3-5788-ab2d-fc2c3371dd36', '5cd95c76-2568-573f-984d-3a9be186d6ab', 'D', 'Scaphoid fracture', false, 3),
  ('e01c5261-a62c-55ab-83bf-5aa1e4efb6a0', '5cd95c76-2568-573f-984d-3a9be186d6ab', 'E', 'Barton''s fracture', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9d456b38-81f6-56fd-ae50-cdac441ea103', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'An 82 year old woman fell at home and cannot stand. Her right leg is shortened and externally rotated. Her hip X-ray is shown in the image. Which is the SINGLE most appropriate operative management?', 'The X-ray shows a trochanteric (intertrochanteric) fracture, which is extracapsular, so the blood supply to the femoral head is preserved. NICE recommends a sliding hip screw for trochanteric fractures above and including the lesser trochanter (an intramedullary nail for subtrochanteric or reverse-oblique fractures). Displaced intracapsular fractures need replacement (hemiarthroplasty or total hip replacement). Surgery should be on the day of admission or the next day.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/X-ray_of_a_comminuted_hip_fracture.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9e33c12a-cbb8-5fa4-975f-5db140a8d67e', '9d456b38-81f6-56fd-ae50-cdac441ea103', 'A', 'Total hip replacement', false, 0),
  ('3897806c-6e34-558f-9b58-e175718a55ce', '9d456b38-81f6-56fd-ae50-cdac441ea103', 'B', 'Dynamic hip screw (sliding hip screw)', true, 1),
  ('ef888968-0e29-5389-877a-b602d3438ea7', '9d456b38-81f6-56fd-ae50-cdac441ea103', 'C', 'Conservative bed rest for 6 weeks', false, 2),
  ('9a38d7f9-103b-537a-880a-6efbb565662c', '9d456b38-81f6-56fd-ae50-cdac441ea103', 'D', 'Closed reduction and hip spica', false, 3),
  ('812ea2ae-3f92-5c35-a328-8e5284abfa92', '9d456b38-81f6-56fd-ae50-cdac441ea103', 'E', 'Hemiarthroplasty', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('45260dca-11cb-5b24-a69c-32451177734f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 34 year old roofer fell about 4 metres and landed on his heels. He has severe pain and swelling of the right heel and cannot bear weight. His foot X-ray is shown in the image. Which other injury MUST be actively looked for?', 'The X-ray shows a calcaneal fracture. Calcaneal fractures from axial loading (a fall from height onto the heels) are linked to compression fractures of the thoracolumbar spine (in about 10% of cases), fractures of the other calcaneus, and tibial plateau fractures. Examine and image the spine. Watch for compartment syndrome of the foot.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Calcaneus_Fracture.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
