  ('957ffb83-5461-5df1-a13f-1c67e01c248f', '6ae589ae-c5d1-5654-8c0a-b62362487e6c', 'A', 'Median nerve', true, 0),
  ('f2c47f2f-550c-50bb-967d-d8d18ce32f0e', '6ae589ae-c5d1-5654-8c0a-b62362487e6c', 'B', 'Anterior interosseous nerve', false, 1),
  ('8851f2db-5eee-5ec2-8a3a-998554d0234b', '6ae589ae-c5d1-5654-8c0a-b62362487e6c', 'C', 'Posterior interosseous nerve', false, 2),
  ('7cf355f5-3d02-5fae-aecf-795a7190e106', '6ae589ae-c5d1-5654-8c0a-b62362487e6c', 'D', 'Radial nerve', false, 3),
  ('09ac8f17-dea6-5543-afe4-175902d1aeae', '6ae589ae-c5d1-5654-8c0a-b62362487e6c', 'E', 'Ulnar nerve', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dad6131d-bab1-5db8-8d0b-16c5799629a2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 25 year old man is stabbed in the back just lateral to the spine. He has weakness of the right leg with loss of proprioception and vibration sense on the right, and loss of pain and temperature sensation on the left below the level of the injury. What is the SINGLE most likely diagnosis?', 'Hemisection of the cord gives ipsilateral weakness (corticospinal tract) and ipsilateral loss of proprioception and vibration (dorsal columns, which cross in the medulla), with contralateral loss of pain and temperature (spinothalamic tract, which crosses within 1-2 segments of entry). Anterior cord syndrome spares the dorsal columns. Central cord syndrome affects the arms more than the legs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
