  ('820fda4b-fbfd-5145-90fc-9e1957bc603d', 'dad6131d-bab1-5db8-8d0b-16c5799629a2', 'A', 'Central cord syndrome', false, 0),
  ('cd0b0e4a-66d9-5dd6-acea-6ea5d772c444', 'dad6131d-bab1-5db8-8d0b-16c5799629a2', 'B', 'Posterior cord syndrome', false, 1),
  ('f74f44e2-c803-5abb-a93a-bb22fa727a62', 'dad6131d-bab1-5db8-8d0b-16c5799629a2', 'C', 'Brown-Séquard syndrome (hemisection of the spinal cord)', true, 2),
  ('b81ce742-9751-5826-996b-91765d08d260', 'dad6131d-bab1-5db8-8d0b-16c5799629a2', 'D', 'Cauda equina syndrome', false, 3),
  ('3f865478-4825-5711-9a74-d81a994f9bdf', 'dad6131d-bab1-5db8-8d0b-16c5799629a2', 'E', 'Anterior cord syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3e114500-aae0-59f8-b4bb-fd9c10c15590', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'Which cell type in the gastric mucosa secretes intrinsic factor?', 'Parietal (oxyntic) cells in the body and fundus secrete hydrochloric acid and intrinsic factor, which is needed to absorb vitamin B12 in the terminal ileum. In pernicious anaemia, autoantibodies against parietal cells and intrinsic factor cause B12 deficiency. Chief cells secrete pepsinogen, G cells in the antrum secrete gastrin, and ECL cells release histamine.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
