  ('55738d61-8d4e-5c6b-a2fb-c4e98e54c299', '338e3a40-ba11-540e-b5fc-f2a7287330f8', 'A', 'Lactic acidosis from sepsis', false, 0),
  ('0900a274-516c-54e8-92d3-dae1b6d7db65', '338e3a40-ba11-540e-b5fc-f2a7287330f8', 'B', 'Salicylate overdose', false, 1),
  ('f26843a1-58e9-548c-a57b-931bb7a1daa5', '338e3a40-ba11-540e-b5fc-f2a7287330f8', 'C', 'Methanol poisoning', false, 2),
  ('fd7a7357-bc14-5ca8-b9c2-519213d5e344', '338e3a40-ba11-540e-b5fc-f2a7287330f8', 'D', 'Diabetic ketoacidosis', false, 3),
  ('b061739d-b2eb-549b-96d7-290bbf64f8c9', '338e3a40-ba11-540e-b5fc-f2a7287330f8', 'E', 'Severe diarrhoea', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('451cb745-01dc-5bf5-b723-e61e6f5e1306', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 21 year old woman has recurrent episodes of facial and lip swelling without urticaria or itch. Her mother had similar episodes. Which investigation is MOST useful for screening?', 'Recurrent angioedema without urticaria and with a family history suggests hereditary angioedema (autosomal dominant C1 esterase inhibitor deficiency). It is bradykinin-mediated, so it does not respond to antihistamines, steroids or adrenaline. C4 is low even between attacks and is the best screening test, followed by measuring C1-INH level and function. Acute attacks are treated with C1-INH concentrate or icatibant.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
