insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7ff66287-0cc9-5b0c-b5ac-7d8d88b3373c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 35 year old man has a scalp laceration that bleeds heavily. Which layer of the scalp contains the blood vessels that tend to stay open when cut?', 'The scalp layers are Skin, Connective tissue (dense), Aponeurosis, Loose areolar tissue and Pericranium (SCALP). The vessels lie in the dense connective tissue layer, whose fibres hold the cut vessel walls open, so scalp wounds bleed heavily. The loose areolar layer is the ''danger area'', where infection can spread to the intracranial venous sinuses through emissary veins.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
