  ('ca8e5ca7-8309-51b1-8a6a-b9f7a9b73d96', 'dba788d3-72be-5207-a196-a8eef4405077', 'A', 'Elevated left hemidiaphragm', false, 0),
  ('51981a25-f689-57e1-b306-c91fd60dfa2c', 'dba788d3-72be-5207-a196-a8eef4405077', 'B', 'Dilated small bowel loops', false, 1),
  ('7f84939f-8636-5fd4-8de4-ea9a281caf5b', 'dba788d3-72be-5207-a196-a8eef4405077', 'C', 'Air under the diaphragm (pneumoperitoneum)', true, 2),
  ('d99296ca-c877-5988-8921-c5efb9479c8d', 'dba788d3-72be-5207-a196-a8eef4405077', 'D', 'Calcified aortic wall', false, 3),
  ('24e29741-a088-5295-9451-457ac9123174', 'dba788d3-72be-5207-a196-a8eef4405077', 'E', 'Blunting of the costophrenic angles', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e5051b08-a54d-5fb5-b26c-d410d4008b39', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 64 year old man on the ward has a respiratory rate of 26/min, SpO2 91% on air, BP 92/60 mmHg, HR 118 bpm, he is newly confused, and his temperature is 38.6°C. What is his NEWS2 score?', 'NEWS2 scoring here: RR 25 or more = 3; SpO2 91% (scale 1) = 2; on air = 0; systolic BP 91-100 = 2; HR 111-130 = 2; new confusion = 3; temperature 38.1-39.0 = 1. Total = 13. A score of 7 or more needs an emergency response from a team with critical care skills, and continuous monitoring. Suspect sepsis and start the Sepsis Six.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
