insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f16c9b17-37dc-5155-b47a-c6f1ef29cf7d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A boy has learning difficulties, a long face, large ears, macro-orchidism after puberty and features of autism. Which genetic mechanism is MOST likely responsible?', 'These are features of fragile X syndrome, the most common inherited cause of learning disability. It is caused by CGG repeat expansion (over 200 repeats) in the 5'' untranslated region of FMR1, which silences the gene by methylation. It shows anticipation through maternal transmission. Female premutation carriers are at risk of premature ovarian insufficiency, and male carriers of the tremor-ataxia syndrome (FXTAS).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('753d750a-8986-50c2-a56c-9f212f2fa26b', 'f16c9b17-37dc-5155-b47a-c6f1ef29cf7d', 'A', 'CGG trinucleotide repeat expansion in the FMR1 gene on the X chromosome', true, 0),
  ('93d4cb15-bc99-57e5-a1df-94b3fdf7004b', 'f16c9b17-37dc-5155-b47a-c6f1ef29cf7d', 'B', 'Deletion on paternal chromosome 15q11-13', false, 1),
  ('c77175b7-e395-55cd-a05e-cf1c6c16ae98', 'f16c9b17-37dc-5155-b47a-c6f1ef29cf7d', 'C', 'Trisomy 21', false, 2),
  ('c8c68f19-ff4f-5fe1-bee7-8a2ec59418a3', 'f16c9b17-37dc-5155-b47a-c6f1ef29cf7d', 'D', 'Microdeletion of 22q11.2', false, 3),
  ('290cc2cd-2847-5981-b554-b00991c2cc18', 'f16c9b17-37dc-5155-b47a-c6f1ef29cf7d', 'E', 'Mutation in the NF1 gene', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8cd3625e-edf9-571c-8078-5d22b9e80278', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A neonate has hypocalcaemic seizures, a heart murmur from interrupted aortic arch, recurrent infections and a cleft palate. Which test will MOST likely confirm the diagnosis?', 'DiGeorge syndrome (22q11.2 deletion): CATCH-22 — Cardiac defects (conotruncal: interrupted aortic arch, truncus arteriosus, tetralogy), Abnormal facies, Thymic hypoplasia (T-cell deficiency), Cleft palate, Hypocalcaemia (parathyroid hypoplasia). It is usually de novo and can be inherited in an autosomal dominant way. Patients also have a high risk of psychiatric illness (such as schizophrenia) later in life.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('46a101ae-50fc-562d-a6b0-2858b6c1684b', '8cd3625e-edf9-571c-8078-5d22b9e80278', 'A', 'Haemoglobin electrophoresis', false, 0),
  ('aaaba320-6ed9-520f-bfed-e01242895ca1', '8cd3625e-edf9-571c-8078-5d22b9e80278', 'B', 'Newborn blood spot for phenylketonuria', false, 1),
  ('1e7e8fe5-601f-5402-999a-4c32b1146981', '8cd3625e-edf9-571c-8078-5d22b9e80278', 'C', 'Chromosomal microarray or FISH for 22q11.2 deletion', true, 2),
  ('293cf8b5-58e8-5c0f-97e9-338c46794bc3', '8cd3625e-edf9-571c-8078-5d22b9e80278', 'D', 'Sweat chloride test', false, 3),
  ('c08bca57-a3e7-56e0-aab3-2f3bac8d3657', '8cd3625e-edf9-571c-8078-5d22b9e80278', 'E', 'Karyotype for trisomy 18', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7abc91f6-68d4-56ad-bdea-12c979efa381', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 30 year old woman''s father has Huntington''s disease, diagnosed at 45. She is asymptomatic and planning a family. She asks about predictive testing. Which is the MOST appropriate response?', 'Huntington''s is autosomal dominant (CAG repeat in HTT), so each child of an affected parent has a 50% risk. Predictive testing must be done through clinical genetics, with structured counselling about the implications for insurance, employment and psychological wellbeing. Predictive testing of asymptomatic children is generally not done, to respect their future autonomy. Options for having children include prenatal diagnosis and pre-implantation genetic testing.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('985a9557-f2a0-5d7d-8fd4-7e97c418fc6b', '7abc91f6-68d4-56ad-bdea-12c979efa381', 'A', 'Tell her that her risk is 25%', false, 0),
  ('4efd6079-f403-5f96-ac1c-097ef76e90fa', '7abc91f6-68d4-56ad-bdea-12c979efa381', 'B', 'Tell her that testing is illegal in the UK', false, 1),
  ('b9e0cebf-0573-5540-acd0-b931630bd7aa', '7abc91f6-68d4-56ad-bdea-12c979efa381', 'C', 'Refer to clinical genetics for pre-test counselling before predictive testing, as she has a 50% risk', true, 2),
  ('0a65d03d-5312-5bfd-8b3e-58033cc10dc2', '7abc91f6-68d4-56ad-bdea-12c979efa381', 'D', 'Test her immediately in primary care and give the result by phone', false, 3),
  ('8549bce1-b754-5dc8-82b7-81952e83f6d3', '7abc91f6-68d4-56ad-bdea-12c979efa381', 'E', 'Advise testing her children in childhood', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('61020235-cc9d-58a4-8047-6883804534f5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 34 year old man has bilateral flank masses, haematuria and hypertension. His father died of a subarachnoid haemorrhage at 50. Which gene is MOST likely to be mutated?', 'Autosomal dominant polycystic kidney disease is caused by mutations in PKD1 (chromosome 16, about 85% of cases, more severe) or PKD2 (chromosome 4, milder). Extra-renal features include liver cysts, intracranial berry aneurysms, mitral valve prolapse and diverticular disease. Tolvaptan may slow progression in rapidly progressive disease. COL4A5 is Alport syndrome. VHL causes renal cell carcinoma, haemangioblastomas and phaeochromocytoma.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('11ab099c-f8eb-55cb-b8b0-3190c2544cb7', '61020235-cc9d-58a4-8047-6883804534f5', 'A', 'COL4A5', false, 0),
  ('35df1793-18c1-5bed-985c-2a0690af97f7', '61020235-cc9d-58a4-8047-6883804534f5', 'B', 'VHL', false, 1),
  ('5062a0e3-e5ff-56b6-bfea-0c458797434a', '61020235-cc9d-58a4-8047-6883804534f5', 'C', 'PKD2', false, 2),
  ('f7852840-1910-54a5-aa74-0d1801a63d54', '61020235-cc9d-58a4-8047-6883804534f5', 'D', 'CFTR', false, 3),
  ('72efe5c6-a274-502d-93a3-06bd3d088840', '61020235-cc9d-58a4-8047-6883804534f5', 'E', 'PKD1', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ff12b0c4-a612-583f-9a9c-2165d7bdb979', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 86 year old woman with moderate Alzheimer''s dementia in a care home has become increasingly agitated and calls out at night. She has no pain, infection or constipation, and non-drug measures have been tried. She is not at risk of harm to herself or others. What is the MOST appropriate next step?', 'NICE NG97 advises a structured assessment of possible causes (pain, delirium, unmet needs, environment) and person-centred non-drug interventions as first-line treatment for distress in dementia. Antipsychotics increase the risk of stroke and death in dementia. Use them only when there is a risk of harm or severe distress, at the lowest dose, for the shortest time, with review at least every 6 weeks.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('80ca59ff-708c-563a-b321-5345eb9c9205', 'ff12b0c4-a612-583f-9a9c-2165d7bdb979', 'A', 'Continue and individualise non-drug interventions, and review for unmet needs; avoid antipsychotics unless she is at risk of harm or severely distressed', true, 0),
  ('47279e9c-fb24-5325-bd10-d39ea48097b4', 'ff12b0c4-a612-583f-9a9c-2165d7bdb979', 'B', 'Start long-term lorazepam', false, 1),
  ('a668a103-9069-5dbc-97f9-d18e071c6f39', 'ff12b0c4-a612-583f-9a9c-2165d7bdb979', 'C', 'Start regular haloperidol', false, 2),
  ('833a24a8-f0c3-5099-a66e-7b33e1fe230c', 'ff12b0c4-a612-583f-9a9c-2165d7bdb979', 'D', 'Physically restrain her at night', false, 3),
  ('e902c7bc-7391-5c8e-94e1-185c0ca14164', 'ff12b0c4-a612-583f-9a9c-2165d7bdb979', 'E', 'Start risperidone at a high dose', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('203c83bf-9c4d-5eda-94da-1f9526b4a614', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 84 year old man is admitted with pneumonia. He has hypertension and takes amlodipine, bendroflumethiazide, ramipril, aspirin, atorvastatin, oxybutynin and amitriptyline 25 mg at night. He has fallen twice recently and is now confused. Which drug MOST contributes to his anticholinergic burden?', 'Oxybutynin (an antimuscarinic) and amitriptyline both have strong anticholinergic effects. In older people, anticholinergic burden is linked to confusion, delirium, falls, constipation, urinary retention and long-term cognitive decline. Use a scale such as ACB to assess it. Consider deprescribing oxybutynin and amitriptyline, and use mirabegron for overactive bladder if a drug is needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6779a453-efd5-55a8-8087-3cb75d53dd07', '203c83bf-9c4d-5eda-94da-1f9526b4a614', 'A', 'Aspirin', false, 0),
  ('74c1d482-7ba0-588d-8340-4c87e9305e34', '203c83bf-9c4d-5eda-94da-1f9526b4a614', 'B', 'Amlodipine', false, 1),
  ('c3e046fd-e227-5c7e-a85e-14422e549e21', '203c83bf-9c4d-5eda-94da-1f9526b4a614', 'C', 'Ramipril', false, 2),
  ('785989ce-ff19-5ad3-b777-1b69ff19dac6', '203c83bf-9c4d-5eda-94da-1f9526b4a614', 'D', 'Oxybutynin', true, 3),
  ('e03bf04a-3c0b-5aa3-bdf0-6f9e44b8f2fb', '203c83bf-9c4d-5eda-94da-1f9526b4a614', 'E', 'Atorvastatin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('06bc4b26-09d7-50e2-9a99-429d3307b071', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'An 80 year old woman fell and fractured her hip. After surgery, which treatment is MOST appropriate to reduce her risk of a future fracture?', 'After a fragility hip fracture, NICE and NOGG recommend treatment to prevent further fractures, often without the need for a DEXA scan in people aged 75 and over. Correct vitamin D first. Zoledronic acid is often given in hospital (at least 2 weeks after surgery). Fracture liaison services coordinate care. Falls prevention is also essential.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d1c57016-0259-5a9c-b3a7-8a147fd34b7c', '06bc4b26-09d7-50e2-9a99-429d3307b071', 'A', 'Teriparatide first-line for all', false, 0),
  ('4cf9d25c-080b-583e-8b6b-5eddc2a78528', '06bc4b26-09d7-50e2-9a99-429d3307b071', 'B', 'Assess bone health, then start a bisphosphonate (such as IV zoledronic acid or oral alendronic acid) with vitamin D and calcium if needed', true, 1),
  ('7d4ebd84-9d01-5081-a127-fa80d0538250', '06bc4b26-09d7-50e2-9a99-429d3307b071', 'C', 'Calcitonin nasal spray', false, 2),
  ('ae44cbcb-161d-55b1-a07a-cd78146f3563', '06bc4b26-09d7-50e2-9a99-429d3307b071', 'D', 'HRT', false, 3),
  ('b98d8146-6437-5685-aa20-ea7ee95b4790', '06bc4b26-09d7-50e2-9a99-429d3307b071', 'E', 'No treatment is needed as she is over 75', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cea3d497-520e-5013-b23a-820306a3c755', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'A 78 year old man has gradual memory problems for 18 months, getting lost in familiar places and repeating questions. His MoCA is 18/30. Bloods (B12, folate, TFTs, calcium, glucose, FBC, U&E, LFTs) are normal. CT head shows generalised atrophy with prominent hippocampal atrophy. Which is the SINGLE most appropriate first-line drug treatment once the diagnosis is confirmed by a specialist?', 'The picture fits Alzheimer''s disease. NICE NG97 recommends an acetylcholinesterase inhibitor (donepezil, galantamine or rivastigmine) for mild to moderate Alzheimer''s, and memantine for moderate disease if AChEIs are not tolerated, or for severe disease. Check for bradycardia and heart block before starting AChEIs, as they can cause bradycardia and syncope.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f9e3c412-2138-5c68-af4b-e15d1fa04a16', 'cea3d497-520e-5013-b23a-820306a3c755', 'A', 'An acetylcholinesterase inhibitor such as donepezil', true, 0),
  ('490b3c9a-9c20-5e20-a026-f63700fb9317', 'cea3d497-520e-5013-b23a-820306a3c755', 'B', 'Ginkgo biloba', false, 1),
  ('6f6feecc-a6e1-5306-b718-e7b831379bf6', 'cea3d497-520e-5013-b23a-820306a3c755', 'C', 'Aspirin', false, 2),
  ('8f695137-7157-5243-85dc-64cd2ad2aedf', 'cea3d497-520e-5013-b23a-820306a3c755', 'D', 'Haloperidol', false, 3),
  ('ce6dd919-ac07-52a8-ae6a-e2b14c3fbb5a', 'cea3d497-520e-5013-b23a-820306a3c755', 'E', 'Memantine as first-line monotherapy for mild disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('333ec245-ac56-5784-a60c-40059a10e2ca', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'A 90 year old woman is admitted after a long lie on the floor. She has a pressure ulcer on her sacrum with full-thickness skin loss, visible subcutaneous fat but no bone, tendon or muscle. What is the category (stage) of this pressure ulcer?', 'Category 1: non-blanching erythema of intact skin. Category 2: partial-thickness skin loss (shallow ulcer or blister). Category 3: full-thickness skin loss, fat may be visible, but not bone, tendon or muscle. Category 4: full-thickness tissue loss with exposed bone, tendon or muscle. Unstageable: the base is covered by slough or eschar. Use pressure redistribution, repositioning, nutrition and wound care.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a7d826b9-d18a-5153-8afe-1fcb0f99b134', '333ec245-ac56-5784-a60c-40059a10e2ca', 'A', 'Category 1', false, 0),
  ('03f69fb7-30e4-56b9-bf1c-e74c3c719825', '333ec245-ac56-5784-a60c-40059a10e2ca', 'B', 'Unstageable', false, 1),
  ('31046949-629a-5c5f-9ce5-b4ab9d36eb56', '333ec245-ac56-5784-a60c-40059a10e2ca', 'C', 'Category 2', false, 2),
  ('c8879e5b-cff5-5b0b-87c8-a52e9fe006f7', '333ec245-ac56-5784-a60c-40059a10e2ca', 'D', 'Category 3', true, 3),
  ('7ee7dda2-60cf-5f85-a6ba-7978abcaa304', '333ec245-ac56-5784-a60c-40059a10e2ca', 'E', 'Category 4', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2a27e56b-1edf-519d-898e-ec10aba6be28', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000029', 'sba', 'A 76 year old man has dizziness and nearly falls each morning on getting out of bed. His lying BP is 146/84 mmHg, and after 3 minutes standing it is 118/72 mmHg, with symptoms. He takes doxazosin and tamsulosin. What is the MOST appropriate first step?', 'A systolic drop of 20 mmHg or more (or diastolic of 10 or more) within 3 minutes of standing confirms orthostatic hypotension. Medication is the commonest reversible cause. He is on two alpha-blockers (doxazosin and tamsulosin), which is a duplication, so one should be stopped. Advise slow positional change, good fluid intake and compression stockings. Fludrocortisone and midodrine are used only if non-drug measures fail.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9772f9eb-d5ec-5da2-aa9a-6f4a275fc646', '2a27e56b-1edf-519d-898e-ec10aba6be28', 'A', 'Start fludrocortisone', false, 0),
  ('7028284e-190f-5a47-ab2d-639cc1579491', '2a27e56b-1edf-519d-898e-ec10aba6be28', 'B', 'Start bisoprolol', false, 1),
  ('28732f01-2511-511d-9c07-c485ba1ff8f4', '2a27e56b-1edf-519d-898e-ec10aba6be28', 'C', 'Start midodrine', false, 2),
  ('d97dca8e-860b-58f3-aecd-045be3eeab1c', '2a27e56b-1edf-519d-898e-ec10aba6be28', 'D', 'Review and stop one of the alpha-blockers (they duplicate each other)', true, 3),
  ('4fb2889c-b8a0-5ce6-a561-0abadb654eef', '2a27e56b-1edf-519d-898e-ec10aba6be28', 'E', 'Advise him to stand up quickly', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e95e5521-8b42-5b18-be15-4b19c0d27aa0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 52 year old man has a QRISK3 score of 14%. He does not smoke and has no diabetes. After a discussion he would like to start medication. Which is the MOST appropriate statin and dose?', 'NICE (NG238, 2023) recommends offering atorvastatin 20 mg for primary prevention when the 10-year QRISK3 risk is 10% or more (and not ruling out lower risk if the person prefers). For secondary prevention, use atorvastatin 80 mg. Check lipids, LFTs and HbA1c at baseline. Aim for a reduction in non-HDL cholesterol of more than 40% at 3 months.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('97dce659-205d-5c97-a700-baf7da94abb3', 'e95e5521-8b42-5b18-be15-4b19c0d27aa0', 'A', 'Simvastatin 10 mg daily', false, 0),
  ('4a70dec3-b96b-556b-be91-081af8fffb16', 'e95e5521-8b42-5b18-be15-4b19c0d27aa0', 'B', 'Pravastatin 10 mg daily', false, 1),
  ('6b0050b5-13c0-5d2b-a213-fcd43efb3935', 'e95e5521-8b42-5b18-be15-4b19c0d27aa0', 'C', 'Rosuvastatin 40 mg daily', false, 2),
  ('68107179-c346-5f87-8802-57f3b5ad27bd', 'e95e5521-8b42-5b18-be15-4b19c0d27aa0', 'D', 'Atorvastatin 20 mg daily', true, 3),
  ('b392fa2f-ad7c-505d-bf94-9b7ba4a71f62', 'e95e5521-8b42-5b18-be15-4b19c0d27aa0', 'E', 'Atorvastatin 80 mg daily', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('74de6795-a689-5a8d-8055-c0e745f9c0ee', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 45 year old woman has had pain at the front of her knee when going downstairs and after prolonged sitting for 3 months. There is no effusion and examination is otherwise normal. She is a keen runner. What is the SINGLE most likely diagnosis?', 'Patellofemoral pain causes anterior knee pain made worse by stairs, squatting, running and prolonged sitting (''theatre sign''), and is common in active people. Management is exercise therapy (quadriceps and hip strengthening), activity modification and short-term analgesia. Osgood-Schlatter disease affects adolescents, with pain and swelling over the tibial tuberosity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8c6f01af-701f-583b-bde2-9fad78b6c240', '74de6795-a689-5a8d-8055-c0e745f9c0ee', 'A', 'Osgood-Schlatter disease', false, 0),
  ('24aa11cc-be54-56f5-8ab6-b7e22f12f693', '74de6795-a689-5a8d-8055-c0e745f9c0ee', 'B', 'Medial meniscal tear', false, 1),
  ('b9d3f77d-b7b7-537a-b73e-48a39855fac6', '74de6795-a689-5a8d-8055-c0e745f9c0ee', 'C', 'Patellofemoral pain syndrome', true, 2),
  ('8074c857-3428-5045-b5d1-e6d97f52dbe0', '74de6795-a689-5a8d-8055-c0e745f9c0ee', 'D', 'Prepatellar bursitis', false, 3),
  ('558be8a0-ec38-5211-a8a5-1c388ff72039', '74de6795-a689-5a8d-8055-c0e745f9c0ee', 'E', 'Septic arthritis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0ba8a193-8e1b-5b8d-9b6f-b73cc160b5a4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 34 year old woman has fatigue, low mood and loss of interest for 3 weeks after a bereavement. Which screening questions are BEST to identify depression in primary care?', 'The two Whooley questions are recommended by NICE as a brief screen for depression. A ''yes'' to either should lead to a fuller assessment (such as with PHQ-9) and an assessment of risk. CAGE and AUDIT-C screen for alcohol misuse. Note that a normal grief reaction can share many features with depression.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('91835034-e8bc-5ac3-b130-b8d1880a187b', '0ba8a193-8e1b-5b8d-9b6f-b73cc160b5a4', 'A', 'The AUDIT-C questionnaire', false, 0),
  ('d15e802b-0358-5de1-a483-69381719b9ab', '0ba8a193-8e1b-5b8d-9b6f-b73cc160b5a4', 'B', 'Ask about her appetite only', false, 1),
  ('04e99d46-2cfb-5541-87cd-c35b4c57812e', '0ba8a193-8e1b-5b8d-9b6f-b73cc160b5a4', 'C', '''During the last month, have you often been bothered by feeling down, depressed or hopeless?'' and ''...by having little interest or pleasure in doing things?''', true, 2),
  ('7772aa86-2c28-56b1-bdf7-ac022755411b', '0ba8a193-8e1b-5b8d-9b6f-b73cc160b5a4', 'D', 'Ask about her sleep only', false, 3),
  ('7298f7a9-0f7a-5c83-b311-771e95737758', '0ba8a193-8e1b-5b8d-9b6f-b73cc160b5a4', 'E', 'The CAGE questionnaire', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1e027e5c-fd15-5467-bfe1-a4de73798e2f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 72 year old man has had urinary frequency, nocturia, hesitancy and a poor stream for a year. Digital rectal examination shows a smooth, enlarged, non-tender prostate. His IPSS score is 12 (moderate). PSA is normal for his age. What is the SINGLE most appropriate first-line drug treatment?', 'NICE (CG97) offers an alpha-blocker (tamsulosin, alfuzosin, doxazosin) for moderate to severe lower urinary tract symptoms. A 5-alpha reductase inhibitor (finasteride) is added for an estimated prostate volume over 30 g or PSA over 1.4 ng/mL with high risk of progression, but takes about 6 months to work. Warn about postural hypotension and floppy iris syndrome during cataract surgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f936e83d-6d0c-5232-97a2-2418614b6c37', '1e027e5c-fd15-5467-bfe1-a4de73798e2f', 'A', 'An alpha-blocker such as tamsulosin', true, 0),
  ('e22d1e8d-af11-5e4e-aaee-6ddc7be3104f', '1e027e5c-fd15-5467-bfe1-a4de73798e2f', 'B', 'Desmopressin', false, 1),
  ('44fa95f8-b3ab-50c0-ab19-420e9dce4dd6', '1e027e5c-fd15-5467-bfe1-a4de73798e2f', 'C', 'Oxybutynin alone', false, 2),
  ('5914f1bc-8fa2-5056-bca0-0b86f42e6e4d', '1e027e5c-fd15-5467-bfe1-a4de73798e2f', 'D', 'Finasteride for all men regardless of prostate size', false, 3),
  ('7974ba83-15f2-548a-8abd-12a9636f6d80', '1e027e5c-fd15-5467-bfe1-a4de73798e2f', 'E', 'Testosterone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('797b7ae0-062f-51b4-806d-dd7e0ff9b087', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 60 year old woman has had pain in her right heel for 2 months. It is worst with the first steps in the morning and eases with walking. There is tenderness at the medial calcaneal tubercle. What is the SINGLE most likely diagnosis?', 'Plantar heel pain that is worst on first steps in the morning, with tenderness at the medial plantar heel, is plantar fasciitis. It is common in people who are obese, stand for long periods or run. Management is rest, stretching (calf and plantar fascia), supportive footwear or insoles, analgesia and weight loss. Most cases resolve within 12 months. Steroid injection is reserved for persistent symptoms.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1ea9ecc4-3456-5362-939e-9ebf6d3dc35c', '797b7ae0-062f-51b4-806d-dd7e0ff9b087', 'A', 'Tarsal tunnel syndrome', false, 0),
  ('538baa0d-92b8-501d-82ae-d6ace5482f28', '797b7ae0-062f-51b4-806d-dd7e0ff9b087', 'B', 'Gout', false, 1),
  ('3aeda42e-d31c-51c0-a414-b8726d87d8e4', '797b7ae0-062f-51b4-806d-dd7e0ff9b087', 'C', 'Achilles tendon rupture', false, 2),
  ('63d7ebd9-6215-58ce-8616-bef6161143ea', '797b7ae0-062f-51b4-806d-dd7e0ff9b087', 'D', 'Calcaneal stress fracture', false, 3),
  ('e4511281-7d15-592e-acb6-749c4525be2e', '797b7ae0-062f-51b4-806d-dd7e0ff9b087', 'E', 'Plantar fasciitis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a73ef753-8860-518a-af62-d6e1aad9880c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 26 year old woman wants to know about the HPV vaccine. Which statement about the UK HPV programme is CORRECT?', 'Since September 2023 the UK routine schedule is one dose of HPV vaccine (Gardasil 9) for girls and boys in school Year 8. Men who have sex with men up to age 45 are offered it through sexual health clinics. Vaccinated women still need cervical screening, because the vaccine does not cover all oncogenic HPV types.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('968395e0-e852-53ad-b15c-bf02a2f448ba', 'a73ef753-8860-518a-af62-d6e1aad9880c', 'A', 'A single dose of the HPV vaccine is offered routinely to girls and boys aged 12-13 (school Year 8)', true, 0),
  ('2f2c15c1-8550-50e3-8019-f667e9ee5385', 'a73ef753-8860-518a-af62-d6e1aad9880c', 'B', 'Three doses are routinely given to all 12-year-olds', false, 1),
  ('ee4c6460-1611-5aac-9c12-dec8c5bf5479', 'a73ef753-8860-518a-af62-d6e1aad9880c', 'C', 'It protects against all types of HPV', false, 2),
  ('f9711af1-3435-5957-9a8e-49950c4876aa', 'a73ef753-8860-518a-af62-d6e1aad9880c', 'D', 'It is only offered to girls', false, 3),
  ('ee2aa6c7-3f71-5baa-bfc4-00cd1b41869a', 'a73ef753-8860-518a-af62-d6e1aad9880c', 'E', 'Vaccinated women no longer need cervical screening', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cc92262a-3c25-51ee-b1c1-f0c3ce15b32a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 30 year old man had a viral illness 2 weeks ago. He now has a petechial rash and gum bleeding. His platelet count is 12 x10^9/L, Hb and WCC are normal, and the blood film is otherwise normal apart from large platelets. What is the SINGLE most appropriate first-line treatment?', 'Isolated thrombocytopenia with a normal film (except large platelets) in an otherwise well adult suggests immune thrombocytopenia (ITP), a diagnosis of exclusion (check HIV and hepatitis C). Treat if there is bleeding or the count is below 20-30 x10^9/L: first-line corticosteroids, with IVIg for severe bleeding or before procedures. Platelet transfusion is used only for life-threatening bleeding, as the transfused platelets are rapidly destroyed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b39c8e63-efe0-54db-a621-285f2eb75fea', 'cc92262a-3c25-51ee-b1c1-f0c3ce15b32a', 'A', 'Splenectomy', false, 0),
  ('64f36603-270f-5a0e-ad94-e9bcd8327f16', 'cc92262a-3c25-51ee-b1c1-f0c3ce15b32a', 'B', 'Observation only, because he is bleeding', false, 1),
  ('9ae08f4f-4a7f-5130-b8be-71298d9f3a6c', 'cc92262a-3c25-51ee-b1c1-f0c3ce15b32a', 'C', 'Platelet transfusion as first-line', false, 2),
  ('8d3d319e-8849-576d-a5ef-849ab8bd4236', 'cc92262a-3c25-51ee-b1c1-f0c3ce15b32a', 'D', 'Warfarin', false, 3),
  ('c435692a-e1f7-5609-a856-4ab381677e99', 'cc92262a-3c25-51ee-b1c1-f0c3ce15b32a', 'E', 'Oral prednisolone (or dexamethasone), with IVIg if a rapid rise is needed', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d011f863-8d86-539f-9161-49a22c612115', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 65 year old man has a haemoglobin of 98 g/L, MCV 112 fL, and a blood film showing oval macrocytes and hypersegmented neutrophils. Serum B12 is low. He has numbness in his feet. What is the SINGLE most appropriate treatment?', 'Megaloblastic anaemia with neurological involvement due to B12 deficiency: give IM hydroxocobalamin 1 mg on alternate days until no further improvement (BNF for neurological involvement), then every 2 months. Never give folic acid alone in B12 deficiency, because it can bring on or worsen subacute combined degeneration of the cord. Check anti-intrinsic factor antibodies for pernicious anaemia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('38583d58-b8e4-5c14-9714-31b29925dba6', 'd011f863-8d86-539f-9161-49a22c612115', 'A', 'Oral iron', false, 0),
  ('dfe47330-fa5f-5893-b444-d8bb2d878274', 'd011f863-8d86-539f-9161-49a22c612115', 'B', 'Oral folic acid alone', false, 1),
  ('cbb70c10-7fc5-5f68-9b08-42bb78bc1fe6', 'd011f863-8d86-539f-9161-49a22c612115', 'C', 'IM hydroxocobalamin every 3 months only, with no loading', false, 2),
  ('0281abc1-70d0-51b4-9ec9-21c38580dee8', 'd011f863-8d86-539f-9161-49a22c612115', 'D', 'Blood transfusion', false, 3),
  ('27dd8ce8-6add-5d47-a888-335e1a9d7e94', 'd011f863-8d86-539f-9161-49a22c612115', 'E', 'IM hydroxocobalamin loading doses (on alternate days) before considering folic acid', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c7d93694-d015-5a8f-9133-b052c72a685f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 72 year old man is found to have a lymphocyte count of 18 x10^9/L on a routine blood test. He is well with no lymphadenopathy, splenomegaly or cytopenias. The blood film shows smudge (smear) cells. Immunophenotyping confirms the diagnosis. What is the SINGLE most appropriate management?', 'This is early-stage chronic lymphocytic leukaemia (Binet stage A). Treatment does not improve survival in asymptomatic early-stage disease, so watchful waiting is appropriate. Treat when there are B symptoms, progressive marrow failure, massive or progressive lymphadenopathy or splenomegaly, or a lymphocyte doubling time under 6 months. Patients are at risk of infection, autoimmune haemolytic anaemia and Richter''s transformation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9155369a-9eac-5624-9336-7b3b902449f0', 'c7d93694-d015-5a8f-9133-b052c72a685f', 'A', 'Allogeneic stem cell transplant', false, 0),
  ('b632fb6e-18b5-5481-8bb5-53473a6be7c5', 'c7d93694-d015-5a8f-9133-b052c72a685f', 'B', 'Splenectomy', false, 1),
  ('761a12d2-1950-54b1-8f74-92bbb843787a', 'c7d93694-d015-5a8f-9133-b052c72a685f', 'C', 'Start a tyrosine kinase inhibitor immediately', false, 2),
  ('08530f42-d897-5e60-8e8f-19a67bdce9cf', 'c7d93694-d015-5a8f-9133-b052c72a685f', 'D', 'Watch and wait with regular monitoring', true, 3),
  ('1b5188e0-f935-53e2-9c69-735034c75e79', 'c7d93694-d015-5a8f-9133-b052c72a685f', 'E', 'Immediate chemotherapy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4c442a8f-cdf5-5db1-b568-d83c8afc2f54', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 60 year old man has a haemoglobin of 190 g/L, haematocrit 0.58, pruritus after hot baths and a palpable spleen. Which test is MOST likely to confirm the diagnosis?', 'Polycythaemia vera is a myeloproliferative neoplasm with a JAK2 mutation in about 95% of cases (V617F or exon 12). Serum EPO is low. Features include aquagenic pruritus, plethora, splenomegaly, thrombosis and gout. Treatment is venesection to a haematocrit under 0.45, low-dose aspirin, and cytoreduction (hydroxycarbamide) for high-risk patients. Secondary polycythaemia (hypoxia, EPO-secreting tumours) has a high EPO.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('06513444-3f14-5014-b103-4f5d582a64f5', '4c442a8f-cdf5-5db1-b568-d83c8afc2f54', 'A', 'Bone marrow iron stain', false, 0),
  ('28633f9f-2a78-592b-b103-7004a09930a9', '4c442a8f-cdf5-5db1-b568-d83c8afc2f54', 'B', 'BCR-ABL1 fusion gene', false, 1),
  ('7bfe8ad4-4fc5-5be6-8db8-e965dbe2207f', '4c442a8f-cdf5-5db1-b568-d83c8afc2f54', 'C', 'JAK2 V617F mutation testing', true, 2),
  ('31fcc178-ac0b-53e6-bc14-98f1098ebbbd', '4c442a8f-cdf5-5db1-b568-d83c8afc2f54', 'D', 'Haemoglobin electrophoresis', false, 3),
  ('2cfac47e-36bf-575c-aa13-f089a3f17e12', '4c442a8f-cdf5-5db1-b568-d83c8afc2f54', 'E', 'Serum erythropoietin is high', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('98597fba-7594-5a9b-8de8-e8d8a39f210c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 42 year old woman has a sudden swollen, painful left calf after a long-haul flight. Ultrasound confirms a proximal DVT. She has no cancer, renal impairment or bleeding risk. What is the SINGLE most appropriate treatment?', 'NICE NG158 recommends apixaban or rivaroxaban as first-line for confirmed DVT or PE. Treat for at least 3 months for a provoked VTE (the flight is a transient risk factor). For unprovoked VTE, consider continuing beyond 3 months, depending on bleeding risk. Compression stockings do not prevent post-thrombotic syndrome. An IVC filter is used only if anticoagulation is contraindicated.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cf75d5a2-8a15-58ca-8bb4-b964b3e964aa', '98597fba-7594-5a9b-8de8-e8d8a39f210c', 'A', 'Graduated compression stockings only', false, 0),
  ('a5a7b0ee-c73a-5532-bd5b-1ba60fb2e1ae', '98597fba-7594-5a9b-8de8-e8d8a39f210c', 'B', 'A DOAC (apixaban or rivaroxaban) for at least 3 months', true, 1),
  ('7e30ba4f-ed83-56b1-a676-5a92316a04a1', '98597fba-7594-5a9b-8de8-e8d8a39f210c', 'C', 'IVC filter', false, 2),
  ('0b2af90b-1db5-5771-a4fa-283286f40f67', '98597fba-7594-5a9b-8de8-e8d8a39f210c', 'D', 'Aspirin 75 mg', false, 3),
  ('942d84c2-d2d1-55c6-866b-9405adceb9b4', '98597fba-7594-5a9b-8de8-e8d8a39f210c', 'E', 'LMWH for 6 weeks then stop', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e4a98300-ac41-5b4e-8efe-8c458a5c20c9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 35 year old man returned from rural Kenya 10 days ago. He has fever, rigors and headache. He did not take malaria prophylaxis. What is the SINGLE most appropriate first investigation?', 'Malaria must be excluded in any febrile traveller returning from an endemic area. Falciparum malaria usually presents within 3 months. Thick films detect parasites and thin films identify the species and parasitaemia. A rapid diagnostic test is used alongside them. Severe falciparum malaria (parasitaemia over 2%, or complications) needs IV artesunate. Repeat films if the first is negative and suspicion remains.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1398f391-6233-5a4e-9de9-d710386e6c81', 'e4a98300-ac41-5b4e-8efe-8c458a5c20c9', 'A', 'Thick and thin blood films (three sets over 72 hours if negative) and/or a malaria rapid antigen test', true, 0),
  ('57d32d89-289f-52e0-9f53-4871c8cb9653', 'e4a98300-ac41-5b4e-8efe-8c458a5c20c9', 'B', 'Stool microscopy', false, 1),
  ('b7c53be2-eb15-5ff2-8748-27c161b8fa77', 'e4a98300-ac41-5b4e-8efe-8c458a5c20c9', 'C', 'Dengue serology only', false, 2),
  ('f950030c-373f-54c2-94a2-d52eb3191190', 'e4a98300-ac41-5b4e-8efe-8c458a5c20c9', 'D', 'Lumbar puncture', false, 3),
  ('1d92b2a7-619a-5ab3-b32c-782419ae6ff3', 'e4a98300-ac41-5b4e-8efe-8c458a5c20c9', 'E', 'Blood cultures only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2e8b3622-80cc-5de1-8dc0-59e916df1e12', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 24 year old woman has fever, headache, neck stiffness and photophobia. She has a non-blanching petechial rash on her legs. She is in a GP surgery. What is the SINGLE most appropriate action before transfer to hospital?', 'Suspected meningococcal disease (meningitis with a non-blanching rash) is a medical emergency. NICE NG240 recommends giving parenteral benzylpenicillin in the community if it does not delay transfer. In hospital, give IV ceftriaxone. Close contacts need chemoprophylaxis (ciprofloxacin single dose). Notify UKHSA, as it is a notifiable disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b05c1ed4-2bc2-5458-a9e4-f5b573e0398b', '2e8b3622-80cc-5de1-8dc0-59e916df1e12', 'A', 'Wait for blood cultures before any antibiotic', false, 0),
  ('b24fa66f-81fd-5df5-b50c-77fdc1b72211', '2e8b3622-80cc-5de1-8dc0-59e916df1e12', 'B', 'Arrange a lumbar puncture in the surgery', false, 1),
  ('39a3731e-a0ae-5541-abd8-ac58fe31577e', '2e8b3622-80cc-5de1-8dc0-59e916df1e12', 'C', 'Give oral amoxicillin', false, 2),
  ('73ccfd38-13bd-585b-b230-30c313ad21ab', '2e8b3622-80cc-5de1-8dc0-59e916df1e12', 'D', 'Give IM or IV benzylpenicillin straight away (unless there is a history of anaphylaxis) and arrange emergency transfer', true, 3),
  ('d03c9c92-5bd3-58f8-b986-15ef4b2467f2', '2e8b3622-80cc-5de1-8dc0-59e916df1e12', 'E', 'Refer for routine outpatient review', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b12344c5-175e-5658-861d-13411bed82d2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 30 year old man with HIV (CD4 count 80 cells/µL) is not on treatment. He has had a dry cough, increasing breathlessness on exertion and fever for 2 weeks. He desaturates on walking. His chest X-ray shows bilateral perihilar interstitial shadowing. What is the SINGLE most likely diagnosis?', 'PCP occurs with a CD4 count under 200. It causes a subacute dry cough, exertional breathlessness and desaturation on exercise, often with a near-normal chest X-ray or bilateral perihilar ground-glass shadowing. It is diagnosed by PCR or immunofluorescence on induced sputum or BAL. Treatment is high-dose co-trimoxazole, plus prednisolone if PaO2 is under 9.3 kPa. Prophylaxis is co-trimoxazole when CD4 is under 200.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b78e536c-d8a0-5c7e-90c9-39c48ca98b42', 'b12344c5-175e-5658-861d-13411bed82d2', 'A', 'Streptococcus pneumoniae pneumonia', false, 0),
  ('1d9d9d90-013f-59ba-a830-bb02eb64800b', 'b12344c5-175e-5658-861d-13411bed82d2', 'B', 'Kaposi''s sarcoma', false, 1),
  ('d023ac36-2924-5c84-b87d-d14f7b536e4f', 'b12344c5-175e-5658-861d-13411bed82d2', 'C', 'Pneumocystis jirovecii pneumonia', true, 2),
  ('6abd8532-0373-54d3-8d52-783c7b881165', 'b12344c5-175e-5658-861d-13411bed82d2', 'D', 'Lung abscess', false, 3),
  ('a83e109e-34a6-5195-9ec6-a292edb40da3', 'b12344c5-175e-5658-861d-13411bed82d2', 'E', 'Pulmonary tuberculosis with cavitation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('71e2b681-e972-59a0-834b-4f204f2096be', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 6 year old child has had diarrhoea for 3 days after a farm visit. He now has pallor, bruising, reduced urine output and blood in his stool. Bloods show Hb 72 g/L, platelets 40 x10^9/L, fragmented red cells on the film and a rising creatinine. Which organism is MOST likely?', 'Haemolytic uraemic syndrome is a triad of microangiopathic haemolytic anaemia, thrombocytopenia and AKI after bloody diarrhoea, usually from Shiga toxin-producing E. coli O157:H7 (from farm animals and undercooked beef). Management is supportive (fluids, dialysis if needed). Antibiotics and antimotility drugs should be avoided as they may increase toxin release. It is a notifiable disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('878e61fb-da32-5135-84e7-e21134c0a177', '71e2b681-e972-59a0-834b-4f204f2096be', 'A', 'Giardia lamblia', false, 0),
  ('5ba44387-9950-5e05-abfa-11bdf97d4c05', '71e2b681-e972-59a0-834b-4f204f2096be', 'B', 'Salmonella enteritidis', false, 1),
  ('bef38490-33dd-5f0f-b2c9-4a4690f1320c', '71e2b681-e972-59a0-834b-4f204f2096be', 'C', 'Escherichia coli O157 (Shiga toxin-producing)', true, 2),
  ('08e00775-d3ed-5516-9924-ccdf26a92de5', '71e2b681-e972-59a0-834b-4f204f2096be', 'D', 'Rotavirus', false, 3),
  ('54865a84-693d-52b5-8f14-a96be7fc3fbc', '71e2b681-e972-59a0-834b-4f204f2096be', 'E', 'Clostridioides difficile', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8a2a853e-0107-5025-a719-565b670fb058', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 55 year old man who keeps pigeons has had fever, headache, a dry cough and myalgia for 1 week. His chest X-ray shows patchy consolidation. Which organism is MOST likely?', 'Psittacosis (Chlamydia psittaci) comes from birds (parrots, budgerigars, pigeons). It causes atypical pneumonia with headache, fever and sometimes splenomegaly, and is treated with doxycycline. Q fever (Coxiella) is linked to farm animals and abattoirs. Legionella is linked to air conditioning or water systems and causes hyponatraemia and deranged LFTs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a3b65c5d-3d1b-51e4-ab36-ff0084444d1e', '8a2a853e-0107-5025-a719-565b670fb058', 'A', 'Klebsiella pneumoniae', false, 0),
  ('ff5ecbd9-22d9-585f-9610-8194dff0084f', '8a2a853e-0107-5025-a719-565b670fb058', 'B', 'Legionella pneumophila', false, 1),
  ('62437f41-3bdf-5b39-95ff-2f5242080507', '8a2a853e-0107-5025-a719-565b670fb058', 'C', 'Coxiella burnetii', false, 2),
  ('1c27615a-540a-5a62-b085-6d48c2193bf4', '8a2a853e-0107-5025-a719-565b670fb058', 'D', 'Mycoplasma pneumoniae', false, 3),
  ('66aa2a8c-901c-5dd6-beac-e63480bfc5c6', '8a2a853e-0107-5025-a719-565b670fb058', 'E', 'Chlamydia psittaci', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('92d21027-40b1-5569-9589-abdec75267fe', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 25 year old woman has frothy, yellow-green, offensive vaginal discharge with vulval itch and dysuria. On speculum examination there is a ''strawberry'' cervix. What is the SINGLE most likely cause?', 'Trichomoniasis is a sexually transmitted protozoal infection that causes a frothy yellow-green discharge, itch, dysuria and a strawberry cervix (punctate haemorrhages), with pH over 4.5. It is diagnosed by NAAT on a vaginal swab. Treatment is oral metronidazole 400-500 mg twice daily for 7 days, for the patient and current partners at the same time. Screen for other STIs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('855e5ae7-650b-54c8-bff6-d1b21fc3ba04', '92d21027-40b1-5569-9589-abdec75267fe', 'A', 'Trichomonas vaginalis', true, 0),
  ('5e7e958b-771b-5ab0-9654-09cbe3b3a69b', '92d21027-40b1-5569-9589-abdec75267fe', 'B', 'Neisseria gonorrhoeae', false, 1),
  ('bc40cc7d-8e49-5f85-abcf-bfab1145b6cb', '92d21027-40b1-5569-9589-abdec75267fe', 'C', 'Candida albicans', false, 2),
  ('ce582a43-2722-5cc1-9aff-1de9b5ffd61e', '92d21027-40b1-5569-9589-abdec75267fe', 'D', 'Bacterial vaginosis', false, 3),
  ('206d77e2-3a72-5aa7-aced-bf1d4e5ecf9a', '92d21027-40b1-5569-9589-abdec75267fe', 'E', 'Chlamydia trachomatis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0fbaabba-57d2-5bb3-8f58-b662ddd7977d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 27 year old woman is diagnosed with uncomplicated urogenital chlamydia. Which statement about partner notification is CORRECT?', 'BASHH guidance: for asymptomatic chlamydia, notify partners from the previous 6 months (or the most recent partner if longer ago). Partners should be offered testing and epidemiological treatment even before results. She should abstain from sex until she and her partners have completed treatment (7 days after doxycycline starts). Partner notification can be done by the patient or the clinic, preserving anonymity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('15eb832b-25ae-5b47-b6cf-5c966fa86217', '0fbaabba-57d2-5bb3-8f58-b662ddd7977d', 'A', 'Current partners and those within the look-back period (usually the previous 6 months) should be notified, tested and treated', true, 0),
  ('1c270ca8-6494-5ca5-940b-a2a164b34543', '0fbaabba-57d2-5bb3-8f58-b662ddd7977d', 'B', 'Only her current partner needs to be informed', false, 1),
  ('e596723e-c1cd-5efe-bd3f-a7f2316dc2de', '0fbaabba-57d2-5bb3-8f58-b662ddd7977d', 'C', 'Partners only need treatment if they have symptoms', false, 2),
  ('ca22fa2f-80d2-5287-8c0b-f02d4001770f', '0fbaabba-57d2-5bb3-8f58-b662ddd7977d', 'D', 'Partner notification requires her consent to be breached by police', false, 3),
  ('8b534fe2-9602-540e-ab83-d124e94a7c33', '0fbaabba-57d2-5bb3-8f58-b662ddd7977d', 'E', 'No partner notification is needed for chlamydia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2e166829-a92d-5aa1-a5f2-f6c5c1e3b400', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A new screening test for colorectal cancer is studied in 1,000 people. 50 have cancer; the test is positive in 45 of them. Of the 950 without cancer, the test is negative in 855. What is the sensitivity of the test?', 'Sensitivity = true positives / (true positives + false negatives) = 45/50 = 90%. Specificity = true negatives / (true negatives + false positives) = 855/950 = 90%. PPV = TP/(TP + FP) = 45/(45 + 95) = 32%. Sensitivity and specificity do not change with prevalence. PPV falls when prevalence is lower.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('17546a8a-11a0-5f79-82c5-c1cedd73a633', '2e166829-a92d-5aa1-a5f2-f6c5c1e3b400', 'A', '32%', false, 0),
  ('5e277f5b-40cb-51b2-bc98-6a07b3132973', '2e166829-a92d-5aa1-a5f2-f6c5c1e3b400', 'B', '85%', false, 1),
  ('532e35c0-ec31-5c7f-8391-a9c43654db31', '2e166829-a92d-5aa1-a5f2-f6c5c1e3b400', 'C', '90%', true, 2),
  ('854ea791-b214-5e49-89c2-26e7e81faa2d', '2e166829-a92d-5aa1-a5f2-f6c5c1e3b400', 'D', '95%', false, 3),
  ('2aed2fe4-ebfb-5436-b4ee-7d160f36ce16', '2e166829-a92d-5aa1-a5f2-f6c5c1e3b400', 'E', '99%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2a5c646d-e45d-5fa9-aefe-b18aa96ee6e5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'In a randomised controlled trial, 20% of patients in the placebo group and 15% in the treatment group had a stroke over 5 years. What is the number needed to treat (NNT) to prevent one stroke over 5 years?', 'Absolute risk reduction (ARR) = 20% - 15% = 5% (0.05). NNT = 1/ARR = 1/0.05 = 20. Relative risk = 15/20 = 0.75, so the relative risk reduction is 25%. The NNT should always be quoted with its timeframe.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2720b8c2-5b03-528f-8ca0-2b92d67dbdf8', '2a5c646d-e45d-5fa9-aefe-b18aa96ee6e5', 'A', '5', false, 0),
  ('63a1ba13-4c17-5e33-a365-3a3884934ac0', '2a5c646d-e45d-5fa9-aefe-b18aa96ee6e5', 'B', '15', false, 1),
  ('2afc1233-b440-53e2-b534-11a28e678cbc', '2a5c646d-e45d-5fa9-aefe-b18aa96ee6e5', 'C', '20', true, 2),
  ('5358eeac-48b5-574b-8974-379fda2ea1e6', '2a5c646d-e45d-5fa9-aefe-b18aa96ee6e5', 'D', '25', false, 3),
