insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('abfbb3c8-b1e3-545a-8a1e-115d62f66956', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A researcher compares 200 women with ovarian cancer with 400 women without it, and asks both groups about previous use of fertility drugs. What type of study is this, and which measure of association is calculated?', 'A case-control study selects participants by outcome (disease versus no disease) and looks back at exposures. It is good for rare diseases. It gives an odds ratio, which approximates the relative risk when the disease is rare. It is prone to recall and selection bias. Cohort studies follow exposed and unexposed groups forward and calculate relative risk and incidence.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('69122b80-215b-5207-966e-eb0252766fa9', 'abfbb3c8-b1e3-545a-8a1e-115d62f66956', 'A', 'Cohort study; relative risk', false, 0),
  ('067903be-c0ac-5e63-97ac-d77fd2f84d85', 'abfbb3c8-b1e3-545a-8a1e-115d62f66956', 'B', 'Ecological study; correlation coefficient', false, 1),
  ('81e636f0-888a-5e78-b0ab-b6c8fd2cad2d', 'abfbb3c8-b1e3-545a-8a1e-115d62f66956', 'C', 'Randomised controlled trial; number needed to treat', false, 2),
  ('04c82afb-08cf-518d-9773-bd1180438f74', 'abfbb3c8-b1e3-545a-8a1e-115d62f66956', 'D', 'Case-control study; odds ratio', true, 3),
  ('7cd344a4-31c6-5e1f-aa6c-eaa5d5a5f0d4', 'abfbb3c8-b1e3-545a-8a1e-115d62f66956', 'E', 'Cross-sectional study; incidence', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('de6cfe2f-5732-5055-944b-31fb577328a3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A test for a condition has sensitivity 99% and specificity 99%. It is used in a population where the prevalence is 0.1%. Which statement is CORRECT?', 'In 100,000 people, 100 have the disease: 99 true positives. Of the 99,900 without it, 1% (999) are false positives. PPV = 99/(99 + 999) = about 9%. So with low prevalence, even a highly specific test produces mostly false positives. This is why population screening needs careful evaluation and confirmatory tests.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8a992070-49e2-55a5-8704-35e830952e12', 'de6cfe2f-5732-5055-944b-31fb577328a3', 'A', 'Sensitivity will fall because prevalence is low', false, 0),
  ('ff98698a-6efa-5d81-8edd-31a15fbd0304', 'de6cfe2f-5732-5055-944b-31fb577328a3', 'B', 'Specificity will fall because prevalence is low', false, 1),
  ('66dc6600-b9df-55e8-97a6-c44108e6ecdb', 'de6cfe2f-5732-5055-944b-31fb577328a3', 'C', 'The PPV will be 99%', false, 2),
  ('4e1fcbaa-befa-5b62-bea2-f1ae7a0358de', 'de6cfe2f-5732-5055-944b-31fb577328a3', 'D', 'Most positive results will be false positives (the PPV is low)', true, 3),
  ('50890369-301e-5e33-9af2-1694d51f97ce', 'de6cfe2f-5732-5055-944b-31fb577328a3', 'E', 'The NPV will be low', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('023ef042-8c99-5b94-a182-ab58b2fbb368', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'Which of the following is an example of PRIMARY prevention?', 'Primary prevention stops disease from occurring (such as vaccination, smoking cessation, seatbelts). Secondary prevention detects disease early, before symptoms, to change its course (screening programmes such as mammography and cervical screening). Tertiary prevention reduces complications and disability from established disease (rehabilitation, secondary prevention drugs after MI). Some classify statins after MI as secondary prevention of further events.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('540d2027-b318-58c6-9922-52356af8d44e', '023ef042-8c99-5b94-a182-ab58b2fbb368', 'A', 'Mammography screening for breast cancer', false, 0),
  ('28f95507-0d6d-5be8-8129-0a74978d486a', '023ef042-8c99-5b94-a182-ab58b2fbb368', 'B', 'Statin therapy after a myocardial infarction', false, 1),
  ('b9b16fc1-bead-5b89-b73d-709f55c2a136', '023ef042-8c99-5b94-a182-ab58b2fbb368', 'C', 'Cervical screening', false, 2),
  ('afabd4cb-3bd5-573e-be6b-49da19691e25', '023ef042-8c99-5b94-a182-ab58b2fbb368', 'D', 'Cardiac rehabilitation after a heart attack', false, 3),
  ('cc72096b-d160-5a21-8a1d-95df3b1e7e2e', '023ef042-8c99-5b94-a182-ab58b2fbb368', 'E', 'Childhood MMR vaccination', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('488b4731-5e95-5bca-a176-b822e7de30d1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A cohort study finds that people who carry lighters have a much higher rate of lung cancer than those who do not. What is the MOST likely explanation?', 'A confounder is associated with both the exposure and the outcome but is not on the causal pathway. Smoking is associated with carrying lighters and causes lung cancer, so it creates a spurious association. Confounding can be dealt with by randomisation (in trials), restriction, matching, stratification or multivariable adjustment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bc089ebf-539a-5234-a5f4-aca5635339de', '488b4731-5e95-5bca-a176-b822e7de30d1', 'A', 'Confounding by smoking', true, 0),
  ('5ebbc479-c088-502c-abec-43bbfa918c89', '488b4731-5e95-5bca-a176-b822e7de30d1', 'B', 'Lead-time bias', false, 1),
  ('24440588-2f5a-5a1d-bd4e-00ecc78da354', '488b4731-5e95-5bca-a176-b822e7de30d1', 'C', 'Observer bias in a blinded RCT', false, 2),
  ('007efed2-ad73-5c12-b4e0-1cca24efda7d', '488b4731-5e95-5bca-a176-b822e7de30d1', 'D', 'Selection bias from randomisation', false, 3),
  ('e3e86fa1-6a4b-57f2-911b-fb4ea3cf2a09', '488b4731-5e95-5bca-a176-b822e7de30d1', 'E', 'Reverse causation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1a6c2b82-f00f-5514-8d02-3ab15b7f52cf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'Which is a notifiable disease that a registered medical practitioner in England must report to the local health protection team on clinical suspicion?', 'Under the Health Protection (Notification) Regulations 2010, doctors in England must notify suspected cases of listed diseases (including measles, mumps, rubella, meningococcal disease, TB, food poisoning, whooping cough, scarlet fever, Legionnaires'' disease, malaria and acute infectious hepatitis) to the UKHSA health protection team, without waiting for laboratory confirmation. Chlamydia, herpes and HIV are not clinically notifiable (HIV is reported by labs and surveillance systems).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5bf07f11-a699-5322-993f-0ae0fe8c64fb', '1a6c2b82-f00f-5514-8d02-3ab15b7f52cf', 'A', 'Measles', true, 0),
  ('343d4aa2-7ce9-5818-8c26-deafe32747d6', '1a6c2b82-f00f-5514-8d02-3ab15b7f52cf', 'B', 'Influenza in a healthy adult', false, 1),
  ('72658a78-173b-5fc2-976f-244fe341d8d5', '1a6c2b82-f00f-5514-8d02-3ab15b7f52cf', 'C', 'Chlamydia', false, 2),
  ('9ec7e121-b3d2-5bca-9b3b-396303ff29c0', '1a6c2b82-f00f-5514-8d02-3ab15b7f52cf', 'D', 'Genital herpes', false, 3),
  ('f0f7dbfb-8d71-58a7-9020-8f41cde12963', '1a6c2b82-f00f-5514-8d02-3ab15b7f52cf', 'E', 'HIV infection', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('74cbbe3b-16da-530c-b4d6-d870c3bc2b86', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 28 year old woman has a malar rash, painful small-joint arthritis, mouth ulcers, and proteinuria of 1.2 g/24h. Her ANA is strongly positive. Which test is MOST useful to monitor disease activity?', 'In SLE, anti-dsDNA titres rise and complement (C3, C4) falls during active disease, especially lupus nephritis. Anti-Smith is highly specific but does not track activity. Proteinuria over 0.5 g/day needs a renal biopsy to classify lupus nephritis. All patients should take hydroxychloroquine unless contraindicated, with annual eye screening.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8b51d3df-f99d-556e-9aea-fa547ec81963', '74cbbe3b-16da-530c-b4d6-d870c3bc2b86', 'A', 'Anti-Jo-1 antibodies', false, 0),
  ('3d76e796-9345-5503-bfea-727815357479', '74cbbe3b-16da-530c-b4d6-d870c3bc2b86', 'B', 'HLA-B27', false, 1),
  ('5237f404-21ae-5e82-906c-e9e272405e4b', '74cbbe3b-16da-530c-b4d6-d870c3bc2b86', 'C', 'Anti-centromere antibodies', false, 2),
  ('00986981-eb7c-530c-bb66-82924b43a270', '74cbbe3b-16da-530c-b4d6-d870c3bc2b86', 'D', 'Rheumatoid factor', false, 3),
  ('d4afc7a7-cbe5-58ff-a26d-e637df95809c', '74cbbe3b-16da-530c-b4d6-d870c3bc2b86', 'E', 'Anti-dsDNA antibody titre and complement (C3/C4) levels', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c1143670-c249-5a4b-aaba-dbb89275706a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 45 year old woman with Raynaud''s phenomenon has skin tightening of her fingers and face, telangiectasia, calcinosis and difficulty swallowing. Which antibody is MOST likely to be positive?', 'Limited cutaneous systemic sclerosis (CREST: Calcinosis, Raynaud''s, oEsophageal dysmotility, Sclerodactyly, Telangiectasia) is associated with anti-centromere antibodies and a late risk of pulmonary arterial hypertension, so screen with an annual echo and lung function. Diffuse systemic sclerosis is associated with anti-Scl-70 and anti-RNA polymerase III, with earlier interstitial lung disease and scleroderma renal crisis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8e619c20-3027-520b-bdab-2ea42aed2162', 'c1143670-c249-5a4b-aaba-dbb89275706a', 'A', 'Anti-Ro', false, 0),
  ('2a39c3a8-5553-5f64-8835-820c155559d4', 'c1143670-c249-5a4b-aaba-dbb89275706a', 'B', 'Anti-CCP', false, 1),
  ('de52b727-a32e-5492-b638-af7402ad117c', 'c1143670-c249-5a4b-aaba-dbb89275706a', 'C', 'Anti-centromere antibody', true, 2),
  ('6dda2832-0668-5e95-962f-46657bba7606', 'c1143670-c249-5a4b-aaba-dbb89275706a', 'D', 'Anti-histone', false, 3),
  ('bf3fcf2f-26fb-5b48-8218-d38ec0f7c1aa', 'c1143670-c249-5a4b-aaba-dbb89275706a', 'E', 'Anti-Scl-70 (topoisomerase I)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('37f446cd-2763-505f-bf84-4e8597e85e6f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 30 year old woman has dry eyes and dry mouth for 1 year, with bilateral parotid swelling. Schirmer''s test is abnormal. Which antibodies are MOST characteristic?', 'Primary Sjögren''s syndrome is associated with anti-Ro and anti-La antibodies and a high rheumatoid factor. Complications include a markedly increased risk of non-Hodgkin (MALT) lymphoma. In pregnancy, anti-Ro can cross the placenta and cause congenital heart block and neonatal lupus. Treatment includes artificial tears, saliva substitutes and pilocarpine.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
