  ('f9cba381-5cb0-5034-bcde-15d3feeba2c5', '37f446cd-2763-505f-bf84-4e8597e85e6f', 'A', 'Anti-mitochondrial', false, 0),
  ('46cd076f-3f75-51bd-9d01-3a11ab909d9e', '37f446cd-2763-505f-bf84-4e8597e85e6f', 'B', 'Anti-Ro (SSA) and anti-La (SSB)', true, 1),
  ('d1620320-a98f-54ca-9e85-c295c0beeb71', '37f446cd-2763-505f-bf84-4e8597e85e6f', 'C', 'c-ANCA', false, 2),
  ('3857a4c2-86c8-5d46-9941-b7d1d43b9c51', '37f446cd-2763-505f-bf84-4e8597e85e6f', 'D', 'Anti-dsDNA', false, 3),
  ('6f25ed5a-416d-5f9f-8b94-241328e24cd6', '37f446cd-2763-505f-bf84-4e8597e85e6f', 'E', 'Anti-centromere', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a62ccc6b-d418-5ead-93af-c30aeb1b3e6d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 68 year old man has a creatinine of 245 µmol/L (baseline 98 µmol/L three weeks ago) and urine output of 0.4 mL/kg/hour for 14 hours. What is his KDIGO AKI stage?', 'KDIGO staging: Stage 1 = creatinine 1.5-1.9 x baseline, or urine under 0.5 mL/kg/h for 6-12 hours. Stage 2 = 2.0-2.9 x baseline, or under 0.5 mL/kg/h for 12 hours or more. Stage 3 = 3 x baseline or more, creatinine 354 µmol/L or more, renal replacement therapy, or under 0.3 mL/kg/h for 24 hours or more / anuria for 12 hours or more. Here 245/98 = 2.5 x baseline and oliguria for over 12 hours = Stage 2.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9f3387d8-906d-50f6-b4c7-706f59ca634c', 'a62ccc6b-d418-5ead-93af-c30aeb1b3e6d', 'A', 'Stage 2', true, 0),
  ('9dba09b7-8098-58a2-b1aa-c270670290e2', 'a62ccc6b-d418-5ead-93af-c30aeb1b3e6d', 'B', 'Chronic kidney disease stage 4', false, 1),
  ('806f2864-c913-5e41-9b30-a24e7a380c93', 'a62ccc6b-d418-5ead-93af-c30aeb1b3e6d', 'C', 'Stage 1', false, 2),
  ('86f7808c-b79b-57de-a94e-279a542e626e', 'a62ccc6b-d418-5ead-93af-c30aeb1b3e6d', 'D', 'No AKI', false, 3),
  ('f64c7dd3-431c-5af8-8670-978aa31b3457', 'a62ccc6b-d418-5ead-93af-c30aeb1b3e6d', 'E', 'Stage 3', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('02d5a0d9-996c-5b46-916a-6d6ceebb54f2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 32 year old woman has her third urinary tract infection in 6 months. Each was confirmed by culture and treated successfully. She has no structural abnormality on ultrasound and is not pregnant. Behavioural measures have not helped. Infections seem related to sexual intercourse. What is the SINGLE most appropriate option?', 'NICE NG112: for recurrent UTI (2 or more in 6 months, or 3 or more in 12 months) in non-pregnant women, first give behavioural advice. If infections are related to intercourse, consider single-dose post-coital antibiotic prophylaxis. Otherwise consider daily low-dose prophylaxis, reviewed at 6 months. Vaginal oestrogen is considered for postmenopausal women. D-mannose can be mentioned (limited evidence).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a88225ae-ed1d-505b-9d6e-0b763d8408ba', '02d5a0d9-996c-5b46-916a-6d6ceebb54f2', 'A', 'No further management', false, 0),
  ('37ccd62c-49be-552d-a1ab-e99b4c591181', '02d5a0d9-996c-5b46-916a-6d6ceebb54f2', 'B', 'Vaginal oestrogen', false, 1),
  ('19c31307-43e0-5a99-a4b4-8711c729c012', '02d5a0d9-996c-5b46-916a-6d6ceebb54f2', 'C', 'Urgent cystoscopy', false, 2),
  ('974f22d2-2d3b-58a3-a87f-752289bb4ebf', '02d5a0d9-996c-5b46-916a-6d6ceebb54f2', 'D', 'Long-term ciprofloxacin', false, 3),
  ('7934ee22-cc54-5ac2-be48-376c7a588271', '02d5a0d9-996c-5b46-916a-6d6ceebb54f2', 'E', 'Single-dose antibiotic prophylaxis to take after sexual intercourse (e.g. nitrofurantoin or trimethoprim)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4cabf244-29f1-548e-857c-60d0876d512e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 55 year old man with type 2 diabetes and CKD has an eGFR of 48 and a urine albumin:creatinine ratio of 45 mg/mmol. His BP is 138/84 mmHg on no treatment. What is the SINGLE most appropriate treatment to slow progression of his kidney disease?', 'In CKD with diabetes and an ACR over 3 mg/mmol, NICE recommends an ACE inhibitor or ARB. NICE TA775 recommends dapagliflozin (an SGLT2 inhibitor) as an add-on in CKD with eGFR 25-75 and type 2 diabetes or ACR 22.6 mg/mmol or more. Check potassium and creatinine 1-2 weeks after starting an ACE inhibitor (accept a creatinine rise of up to 30%). The BP target in CKD with ACR 70 or more is below 130/80.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('21a42723-0218-5151-8ac6-c7e3fd0ad6e0', '4cabf244-29f1-548e-857c-60d0876d512e', 'A', 'Spironolactone only', false, 0),
  ('ff559443-6455-54c4-b493-d4e08b966a9e', '4cabf244-29f1-548e-857c-60d0876d512e', 'B', 'An ACE inhibitor (or ARB), titrated to the maximum tolerated dose, plus an SGLT2 inhibitor', true, 1),
  ('9c956daf-0874-5660-898e-0222fd8c7d13', '4cabf244-29f1-548e-857c-60d0876d512e', 'C', 'Amlodipine only', false, 2),
  ('b846c1d8-754d-5fc8-8291-26e5687980e7', '4cabf244-29f1-548e-857c-60d0876d512e', 'D', 'No treatment, as BP is acceptable', false, 3),
  ('bf641751-606b-5700-98d6-bdbc0b53da86', '4cabf244-29f1-548e-857c-60d0876d512e', 'E', 'Bendroflumethiazide only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('edea8085-f5f8-5ecf-ba74-529fcf934157', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 45 year old man with a history of alcohol excess has severe epigastric pain radiating to the back and vomiting. His serum amylase is 1,800 U/L. Which scoring system is used in the UK to assess the severity of acute pancreatitis within 48 hours?', 'The modified Glasgow (Imrie) criteria (PANCREAS: PaO2 under 8 kPa, Age over 55, Neutrophils (WCC over 15), Calcium under 2, Renal (urea over 16), Enzymes (LDH over 600, AST over 200), Albumin under 32, Sugar (glucose over 10)) predict severe pancreatitis if 3 or more are present within 48 hours. Management is supportive: aggressive IV fluids, analgesia, early enteral nutrition. Antibiotics are not given routinely. CRP over 150 at 48 hours also predicts severity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('592e4a64-29a8-52da-98c3-6e949300cbab', 'edea8085-f5f8-5ecf-ba74-529fcf934157', 'A', 'Modified Glasgow (Imrie) score', true, 0),
  ('46f04764-a334-5ea5-96c4-2a8198046cef', 'edea8085-f5f8-5ecf-ba74-529fcf934157', 'B', 'Child-Pugh score', false, 1),
  ('3177d01d-7ca6-5c9d-b4a9-e88987009a18', 'edea8085-f5f8-5ecf-ba74-529fcf934157', 'C', 'Wells score', false, 2),
  ('90521a9f-4136-5931-afc2-7cfac0865049', 'edea8085-f5f8-5ecf-ba74-529fcf934157', 'D', 'Rockall score', false, 3),
  ('d904228a-72c0-56c3-8bad-6f906c28873e', 'edea8085-f5f8-5ecf-ba74-529fcf934157', 'E', 'CURB-65', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6fe9e179-573b-5105-bcaa-11a94d85d67d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 58 year old man with cirrhosis has gradual abdominal distension. Ultrasound confirms moderate ascites. His serum-ascites albumin gradient (SAAG) is 15 g/L and ascitic neutrophils are 80 cells/mm³. What is the SINGLE most appropriate first-line management?', 'A SAAG of 11 g/L or more means portal hypertension (as in cirrhosis). The neutrophil count under 250 excludes spontaneous bacterial peritonitis. First-line management is a no-added-salt diet and an aldosterone antagonist (spironolactone), with furosemide added if needed. Large-volume paracentesis is used for tense ascites, with IV human albumin infusion (8 g/L of ascites drained, if more than 5 L). Consider antibiotic prophylaxis if ascitic protein is 15 g/L or less.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4f6e2dca-ef33-594b-ae3b-6bbb6165a33c', '6fe9e179-573b-5105-bcaa-11a94d85d67d', 'A', 'Total paracentesis with no albumin', false, 0),
  ('2bb47333-ac7b-5fde-ae9a-3737e8c3a9bb', '6fe9e179-573b-5105-bcaa-11a94d85d67d', 'B', 'Restrict dietary salt and start spironolactone', true, 1),
  ('04b441af-f853-5c95-b251-06584104062e', '6fe9e179-573b-5105-bcaa-11a94d85d67d', 'C', 'TIPS as first-line', false, 2),
  ('64ad815a-0b3d-54af-8f51-cc28fceb6af4', '6fe9e179-573b-5105-bcaa-11a94d85d67d', 'D', 'High-dose furosemide alone', false, 3),
  ('126840ba-669f-56a8-bfdb-5576d06dab1b', '6fe9e179-573b-5105-bcaa-11a94d85d67d', 'E', 'IV antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6efe5102-4ac0-57b4-959f-1036d38ae82a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 34 year old woman has had alternating diarrhoea and constipation with bloating for 8 months, relieved by defecation. She has no weight loss, rectal bleeding or family history of bowel cancer. FBC, CRP, coeliac serology and faecal calprotectin are normal. What is the SINGLE most appropriate first-line management?', 'These features meet the criteria for irritable bowel syndrome, and red flags have been excluded. NICE CG61 recommends diet and lifestyle advice, antispasmodics (such as mebeverine), laxatives (avoiding lactulose) or loperamide depending on symptoms, and low-dose tricyclics second-line. Dietitian input for a low FODMAP diet is an option. Psychological therapy can help if symptoms persist beyond 12 months.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f3979681-b2da-5382-a484-b803323582df', '6efe5102-4ac0-57b4-959f-1036d38ae82a', 'A', 'Long-term ciprofloxacin', false, 0),
  ('1964e4c6-bb62-54aa-9bb5-519550c63d6b', '6efe5102-4ac0-57b4-959f-1036d38ae82a', 'B', 'CT abdomen', false, 1),
  ('ce9fc4bd-1450-58b7-9288-c3f7ad54acd8', '6efe5102-4ac0-57b4-959f-1036d38ae82a', 'C', 'Dietary and lifestyle advice (regular meals, fibre adjustment), with antispasmodics if needed', true, 2),
  ('05e057af-2032-5ff0-a046-e62d18b7bd48', '6efe5102-4ac0-57b4-959f-1036d38ae82a', 'D', 'Colonoscopy', false, 3),
  ('a570ec15-b6bd-5b4b-85fc-c146549c6fcd', '6efe5102-4ac0-57b4-959f-1036d38ae82a', 'E', 'Oral steroids', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('48047921-13da-5cfa-b7ac-11e338c59c30', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 32 year old woman has had episodes of visual blurring in one eye with painful eye movements, and tingling in her legs, each lasting weeks, over 2 years. MRI shows periventricular white matter lesions. CSF shows oligoclonal bands not present in serum. What is the SINGLE most likely diagnosis?', 'Episodes separated in time and space (optic neuritis, sensory symptoms), periventricular demyelinating lesions and CSF-specific oligoclonal bands meet the McDonald criteria for MS. Relapses are treated with high-dose methylprednisolone (oral or IV) if disabling. Disease-modifying therapies (such as ocrelizumab, natalizumab, dimethyl fumarate) reduce relapse rate. Neuromyelitis optica is associated with aquaporin-4 antibodies.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('520de997-e2e8-540e-baa8-9d65458d6ee5', '48047921-13da-5cfa-b7ac-11e338c59c30', 'A', 'Neuromyelitis optica', false, 0),
  ('c8f7d7e1-1bcd-515b-8316-5979d441d2f7', '48047921-13da-5cfa-b7ac-11e338c59c30', 'B', 'Migraine with aura', false, 1),
  ('7474514f-c7d0-54a9-9ef6-44833e782118', '48047921-13da-5cfa-b7ac-11e338c59c30', 'C', 'Guillain-Barré syndrome', false, 2),
  ('97d792f4-7127-5dce-b354-8b555645e5da', '48047921-13da-5cfa-b7ac-11e338c59c30', 'D', 'Relapsing-remitting multiple sclerosis', true, 3),
  ('de767720-401b-5a7c-b15c-8e5e2cb7c054', '48047921-13da-5cfa-b7ac-11e338c59c30', 'E', 'Motor neurone disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ff7ba2dc-4d70-506b-892a-08fa0ac7c83b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 35 year old woman has had fatigable ptosis and double vision that are worse in the evening. She has difficulty climbing stairs at the end of the day. Acetylcholine receptor antibodies are positive. Which investigation should be done next?', 'Myasthenia gravis is an autoimmune disorder with antibodies against the acetylcholine receptor (or MuSK). It causes fatigable weakness affecting ocular, bulbar and proximal muscles. About 10-15% of patients have a thymoma, so do CT or MRI of the chest. Thymectomy benefits many generalised AChR-positive patients under 65. Symptomatic treatment is pyridostigmine. Avoid drugs that worsen MG, such as aminoglycosides, beta-blockers and magnesium.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6061d8c1-0b55-5336-b1e2-b22ffcd6860d', 'ff7ba2dc-4d70-506b-892a-08fa0ac7c83b', 'A', 'Nerve conduction studies only', false, 0),
  ('1143efea-052c-580a-8887-dfbe1a44d789', 'ff7ba2dc-4d70-506b-892a-08fa0ac7c83b', 'B', 'Muscle biopsy', false, 1),
  ('effbe245-bbbe-5332-bd1d-18a2c9552393', 'ff7ba2dc-4d70-506b-892a-08fa0ac7c83b', 'C', 'CT of the chest to look for a thymoma', true, 2),
  ('6e202711-f8e9-594f-8757-37eebb87de46', 'ff7ba2dc-4d70-506b-892a-08fa0ac7c83b', 'D', 'Lumbar puncture', false, 3),
  ('5c82b14d-776c-5916-a52d-f33791465c0e', 'ff7ba2dc-4d70-506b-892a-08fa0ac7c83b', 'E', 'MRI of the lumbar spine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('901458e0-ed61-5287-aa11-7ed3ba4cc6fe', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 25 year old woman has had a unilateral throbbing headache with nausea and photophobia, lasting 12 hours, about 5 times a month despite treating the acute attacks. She uses the combined pill and has migraine with aura. Which change is MOST important?', 'Migraine with aura increases the risk of ischaemic stroke, and combined hormonal contraception adds to it. UKMEC rates CHC as 4 (unacceptable risk) in migraine with aura. Switch to a progestogen-only method, an IUD or the implant. For prevention, consider propranolol, topiramate (avoid in pregnancy; needs highly effective contraception) or amitriptyline. Avoid using acute medication more than 10-15 days a month, to prevent medication overuse headache.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e8ccb643-b571-5e15-a564-026b8238589f', '901458e0-ed61-5287-aa11-7ed3ba4cc6fe', 'A', 'Switch to a higher-dose combined pill', false, 0),
  ('d4eaf815-f946-569e-88a9-ba975c3ac918', '901458e0-ed61-5287-aa11-7ed3ba4cc6fe', 'B', 'No change is needed', false, 1),
  ('2d1d05c4-a0ec-5bc3-ab65-4c71ba11cb69', '901458e0-ed61-5287-aa11-7ed3ba4cc6fe', 'C', 'Stop the combined oral contraceptive, because migraine with aura is a contraindication (UKMEC 4)', true, 2),
  ('60264898-7bfc-55f7-a54a-e922c8b6e2f0', '901458e0-ed61-5287-aa11-7ed3ba4cc6fe', 'D', 'Increase the oestrogen dose', false, 3),
  ('b483a43e-bca1-5b79-ba16-0adb0ea57d1c', '901458e0-ed61-5287-aa11-7ed3ba4cc6fe', 'E', 'Add a triptan daily as prevention', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('67079a6d-6193-53cd-a4c9-457b5ea860bd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 68 year old man has had a resting tremor of his right hand, slowness of movement and rigidity for 1 year. His symptoms affect his quality of life. What is the SINGLE most appropriate first-line drug treatment?', 'NICE NG71 recommends levodopa as first-line for people with early Parkinson''s disease whose motor symptoms affect their quality of life. If motor symptoms do not affect quality of life, a choice of dopamine agonist, levodopa or MAO-B inhibitor can be offered. Long-term levodopa causes motor fluctuations and dyskinesias. Dopamine agonists can cause impulse control disorders, so warn patients about this.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ab8d3a9a-67c2-59bb-8ac1-9603ebb7d498', '67079a6d-6193-53cd-a4c9-457b5ea860bd', 'A', 'Donepezil', false, 0),
  ('afe75516-a7cd-52d0-9f42-3beb48ff0237', '67079a6d-6193-53cd-a4c9-457b5ea860bd', 'B', 'Amantadine', false, 1),
  ('fd485550-9954-5a3f-bbc7-5089ccd614e7', '67079a6d-6193-53cd-a4c9-457b5ea860bd', 'C', 'Haloperidol', false, 2),
  ('c02daa71-8467-5a98-86e5-a3a0d64855b8', '67079a6d-6193-53cd-a4c9-457b5ea860bd', 'D', 'Levodopa (co-careldopa or co-beneldopa)', true, 3),
  ('ea986714-03ff-54aa-b1e4-2ee317c3f9e0', '67079a6d-6193-53cd-a4c9-457b5ea860bd', 'E', 'Propranolol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('56d071b1-08db-5c0c-861d-4909cb8346b2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 19 year old woman with asthma is in the Emergency Department. She cannot complete sentences, her PEF is 40% of best, RR 28/min, HR 118 bpm and SpO2 94% on air. After nebulised salbutamol and ipratropium and oral prednisolone 40 mg she has not improved. What is the SINGLE most appropriate next drug?', 'This is acute severe asthma (PEF 33-50%, inability to complete sentences, RR 25 or more, HR 110 or more). BTS/SIGN advise a single dose of IV magnesium sulfate if there is no good initial response to bronchodilators. Get senior and ICU input early. Features of life-threatening asthma include PEF under 33%, SpO2 under 92%, a normal or raised PaCO2, a silent chest, cyanosis, exhaustion and hypotension.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9d387c1d-5bac-5d11-80a9-6e9aee99d05c', '56d071b1-08db-5c0c-861d-4909cb8346b2', 'A', 'IV aminophylline as first-line', false, 0),
  ('8cef4fea-3f09-5618-8b65-2997cdbf14d9', '56d071b1-08db-5c0c-861d-4909cb8346b2', 'B', 'Oral montelukast', false, 1),
  ('7e73b22f-e460-50e5-b376-a03533f1d98e', '56d071b1-08db-5c0c-861d-4909cb8346b2', 'C', 'IV magnesium sulfate 1.2-2 g over 20 minutes', true, 2),
  ('9295353c-8319-5ef0-9a23-0a81b7373910', '56d071b1-08db-5c0c-861d-4909cb8346b2', 'D', 'IV hydrocortisone only, then discharge', false, 3),
  ('3d31322b-08e6-5a0c-a17d-c6644ddad815', '56d071b1-08db-5c0c-861d-4909cb8346b2', 'E', 'Nebulised budesonide alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d54a1e14-7def-54ac-adf5-3ed1fc487692', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 66 year old man with COPD has an FEV1 of 45% predicted. He is breathless with an mMRC grade of 3 despite a LAMA and LABA. He has had no exacerbations in the past year. He still smokes. Which intervention would MOST improve his breathlessness and exercise tolerance?', 'Pulmonary rehabilitation (a 6-12 week programme of exercise and education) improves breathlessness, exercise capacity and quality of life in people with COPD who are functionally limited (mMRC 3 or more, or 2 or more in newer guidance). Smoking cessation is the only intervention shown to slow FEV1 decline. ICS is added for asthmatic features or exacerbations. Long-term oral steroids are avoided.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2da269c1-641d-5a44-b471-b56a7b875e2d', 'd54a1e14-7def-54ac-adf5-3ed1fc487692', 'A', 'Long-term oral prednisolone', false, 0),
  ('80a34299-788b-5c5c-bae7-9f39522f7236', 'd54a1e14-7def-54ac-adf5-3ed1fc487692', 'B', 'Lung transplant referral', false, 1),
  ('47e0b862-fd83-5d53-8403-a9447521e8e9', 'd54a1e14-7def-54ac-adf5-3ed1fc487692', 'C', 'Pulmonary rehabilitation (and smoking cessation support)', true, 2),
  ('803aee40-e190-5a85-8c30-5abd45829c71', 'd54a1e14-7def-54ac-adf5-3ed1fc487692', 'D', 'Theophylline as first choice', false, 3),
  ('dbfe969e-8065-5cc0-b02c-de0aeaec0a04', 'd54a1e14-7def-54ac-adf5-3ed1fc487692', 'E', 'Long-term azithromycin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b808c810-6c42-50af-a1b3-2aeafe88d838', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 48 year old man has a sudden-onset of pleuritic chest pain and haemoptysis 10 days after a long flight. He has no previous VTE. His CTPA confirms a segmental PE. He is haemodynamically stable with no right heart strain. What is the SINGLE most appropriate management?', 'Haemodynamically stable PE is treated with anticoagulation. NICE recommends apixaban or rivaroxaban, and outpatient management for low-risk patients (such as a low PESI or sPESI score, with no RV strain). Thrombolysis is for massive PE with haemodynamic compromise (systolic under 90 mmHg). This PE is provoked by travel, so 3 months of treatment is usually enough.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c2346f2a-1131-5d56-abcc-28ac05830a52', 'b808c810-6c42-50af-a1b3-2aeafe88d838', 'A', 'Surgical embolectomy', false, 0),
  ('73791555-12e4-5f1a-9823-ce22dc79d25b', 'b808c810-6c42-50af-a1b3-2aeafe88d838', 'B', 'Aspirin only', false, 1),
  ('5a8448f8-bbac-5f11-834e-d2f30bfa007d', 'b808c810-6c42-50af-a1b3-2aeafe88d838', 'C', 'Start a DOAC (apixaban or rivaroxaban) and consider outpatient management', true, 2),
  ('0f56fb84-f69d-55cf-8297-a9793beb0103', 'b808c810-6c42-50af-a1b3-2aeafe88d838', 'D', 'Thrombolysis with alteplase', false, 3),
  ('620b97b5-de15-58f4-b66a-7db3b2ecb24e', 'b808c810-6c42-50af-a1b3-2aeafe88d838', 'E', 'IVC filter', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bc7d1ca7-3e5b-5a50-af20-72e23c8d93be', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 60 year old man with known bronchiectasis has an exacerbation with increased purulent sputum and breathlessness. His previous sputum culture grew Pseudomonas aeruginosa. Which antibiotic is MOST appropriate?', 'Send a sputum sample and start antibiotics based on previous culture results. For Pseudomonas, oral ciprofloxacin is the oral option, usually for 14 days in bronchiectasis. Severe exacerbations need IV antipseudomonal drugs. Airway clearance techniques (physiotherapy) are key in long-term management. For frequent exacerbations, long-term macrolides or inhaled antibiotics are considered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('44f0e6b6-1da6-5acc-a7cf-6ebd9825bf49', 'bc7d1ca7-3e5b-5a50-af20-72e23c8d93be', 'A', 'Oral flucloxacillin', false, 0),
  ('8d53f80a-4aa8-5647-9aad-2b69a7821934', 'bc7d1ca7-3e5b-5a50-af20-72e23c8d93be', 'B', 'Oral amoxicillin', false, 1),
  ('335277a6-771f-5515-af00-c2a62171be2d', 'bc7d1ca7-3e5b-5a50-af20-72e23c8d93be', 'C', 'Oral nitrofurantoin', false, 2),
  ('9aa64296-53bc-5753-8ff6-4c588b58bf32', 'bc7d1ca7-3e5b-5a50-af20-72e23c8d93be', 'D', 'Oral ciprofloxacin for 14 days', true, 3),
  ('e310af39-6cd8-5341-9fc4-93165faeb5ea', 'bc7d1ca7-3e5b-5a50-af20-72e23c8d93be', 'E', 'Oral clarithromycin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a7668010-b25b-5b55-98d0-a225adcc0e62', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 34 year old man has episodes of choking awake at night, loud snoring and severe daytime sleepiness. His Epworth score is 17 and his BMI is 36. A sleep study shows an apnoea-hypopnoea index of 35/hour. He is a lorry driver. Which is the SINGLE most appropriate treatment?', 'Severe OSA (AHI 30 or more) with sleepiness is treated with CPAP. A Group 2 (lorry) driver with OSA syndrome causing excessive sleepiness must not drive and must notify the DVLA. Driving can resume once symptoms are controlled and treatment compliance is confirmed. Mandibular advancement devices are used for mild OSA or if CPAP is not tolerated.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2947dafe-8666-54a1-9b16-9cbf5e1985c4', 'a7668010-b25b-5b55-98d0-a225adcc0e62', 'A', 'Oral modafinil alone', false, 0),
  ('b79050c9-ca13-5f74-9845-2d51bfc98d66', 'a7668010-b25b-5b55-98d0-a225adcc0e62', 'B', 'CPAP, plus weight loss advice; he must not drive until symptoms are controlled and must inform the DVLA', true, 1),
  ('c1eb8138-2a11-59af-8129-db981dba4040', 'a7668010-b25b-5b55-98d0-a225adcc0e62', 'C', 'Mandibular advancement device as first-line for severe OSA', false, 2),
  ('3bc2525c-9a26-5cb8-b6d9-1c496921ae59', 'a7668010-b25b-5b55-98d0-a225adcc0e62', 'D', 'Sleeping tablets', false, 3),
  ('06489a6d-1b50-549a-adc9-5489741b1de1', 'a7668010-b25b-5b55-98d0-a225adcc0e62', 'E', 'Uvulopalatopharyngoplasty', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('04a3ee79-d1fa-51f1-8df1-a8f0fd0c4166', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 68 year old woman has tiredness, weight gain, constipation and dry skin. Her TSH is 18 mU/L and free T4 is low. She has ischaemic heart disease. What is the SINGLE most appropriate starting treatment?', 'Primary hypothyroidism is treated with levothyroxine. In older people or those with ischaemic heart disease, start at a low dose (25-50 micrograms daily) and increase slowly, to avoid triggering angina or arrhythmia. Check TSH 6-8 weeks after each dose change, aiming for the reference range. Take levothyroxine on an empty stomach, separate from iron and calcium.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4e2e0bb0-4524-5cd3-8ee7-9f43c880b58e', '04a3ee79-d1fa-51f1-8df1-a8f0fd0c4166', 'A', 'Levothyroxine 1.6 micrograms/kg (full replacement) immediately', false, 0),
  ('36f8133e-9d04-5c70-bc14-885733694076', '04a3ee79-d1fa-51f1-8df1-a8f0fd0c4166', 'B', 'Levothyroxine at a low dose (e.g. 25 micrograms daily), increased gradually', true, 1),
  ('feebc6ac-65ce-55d6-8b7d-01472ec88b74', '04a3ee79-d1fa-51f1-8df1-a8f0fd0c4166', 'C', 'Carbimazole', false, 2),
  ('642bafe3-620e-5d49-9755-b3e67a452afa', '04a3ee79-d1fa-51f1-8df1-a8f0fd0c4166', 'D', 'No treatment, review in 6 months', false, 3),
  ('fcb435bd-2b13-5c7c-85fd-4d779669e6cc', '04a3ee79-d1fa-51f1-8df1-a8f0fd0c4166', 'E', 'Liothyronine (T3)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ce091089-293a-5b79-a194-d6b540fdfd09', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 26 year old woman has palpitations, heat intolerance and weight loss. She has a small diffuse goitre with a bruit, and exophthalmos. TSH is undetectable and free T4 is high. TSH receptor antibodies are positive. What is the SINGLE most appropriate initial treatment?', 'Graves'' disease is first treated with an antithyroid drug (carbimazole by titration, or block-and-replace) for 12-18 months, with propranolol for adrenergic symptoms. Warn about agranulocytosis: she must seek urgent FBC if she gets a sore throat or fever. Radioiodine can worsen thyroid eye disease (steroid cover is needed) and is contraindicated in pregnancy. Propylthiouracil is preferred in the first trimester.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3659c046-f516-5ae0-b671-1a5770f01eca', 'ce091089-293a-5b79-a194-d6b540fdfd09', 'A', 'No treatment', false, 0),
  ('7119827c-a79a-5d9e-a366-20b8bfc32f86', 'ce091089-293a-5b79-a194-d6b540fdfd09', 'B', 'Levothyroxine', false, 1),
  ('e4ccdbcf-e2d4-5e4e-a1bb-a241169dff60', 'ce091089-293a-5b79-a194-d6b540fdfd09', 'C', 'Radioactive iodine immediately in a woman with active eye disease', false, 2),
  ('475badf5-3449-5a4e-82f1-2cb7599e5605', 'ce091089-293a-5b79-a194-d6b540fdfd09', 'D', 'Total thyroidectomy as first-line', false, 3),
  ('7bdd1c92-f4a8-5bcd-9fcc-c4300f83e2d2', 'ce091089-293a-5b79-a194-d6b540fdfd09', 'E', 'Carbimazole with a beta-blocker (propranolol) for symptoms', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('21e231d6-15a0-5863-bb9f-48ecc154a80e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 40 year old woman has episodic headaches, palpitations and sweating, with paroxysmal hypertension up to 220/120 mmHg. Plasma free metanephrines are high. CT shows a 4 cm right adrenal mass. What is the SINGLE most appropriate pre-operative preparation?', 'In phaeochromocytoma, start alpha-blockade (phenoxybenzamine or doxazosin) first, with fluid and salt loading, for 10-14 days before surgery. Beta-blockers are added only after adequate alpha-blockade, to control tachycardia. Giving a beta-blocker first leaves alpha-mediated vasoconstriction unopposed and can cause a hypertensive crisis. Screen for familial syndromes (MEN2, VHL, NF1, SDH mutations).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('67262569-d718-53d5-a241-24d5855fcd09', '21e231d6-15a0-5863-bb9f-48ecc154a80e', 'A', 'Alpha-blockade (phenoxybenzamine) first, then beta-blockade if needed', true, 0),
  ('00012626-c8c1-580a-99c4-87d82cd0f3ee', '21e231d6-15a0-5863-bb9f-48ecc154a80e', 'B', 'Spironolactone', false, 1),
  ('225ad5c1-83e3-5418-9b62-581823074a2c', '21e231d6-15a0-5863-bb9f-48ecc154a80e', 'C', 'Immediate surgery without medical preparation', false, 2),
  ('b3cae1fb-94dc-5955-90ce-bd64e4103162', '21e231d6-15a0-5863-bb9f-48ecc154a80e', 'D', 'Beta-blockade first, then alpha-blockade', false, 3),
  ('5503cecc-3fb1-5724-a244-01625dea566d', '21e231d6-15a0-5863-bb9f-48ecc154a80e', 'E', 'ACE inhibitor alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2a218242-b1ff-5ed9-a719-45fc201422a6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 34 year old woman has fatigue, salt craving, dizziness on standing and darkening of her skin creases and buccal mucosa. Her sodium is 128 mmol/L and potassium is 5.8 mmol/L. A short Synacthen test shows an inadequate cortisol rise. What is the SINGLE most appropriate long-term treatment?', 'Primary adrenal insufficiency (Addison''s, usually autoimmune in the UK) needs glucocorticoid (hydrocortisone 15-25 mg/day in 2-3 doses) and mineralocorticoid (fludrocortisone) replacement. Sick-day rules: double the hydrocortisone dose during fever or illness, and use IM hydrocortisone if vomiting. Carry an NHS steroid emergency card. Hyperpigmentation is caused by high ACTH.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6e2b8499-e7fa-584a-bc41-b61b134f36cb', '2a218242-b1ff-5ed9-a719-45fc201422a6', 'A', 'Prednisolone only, with no mineralocorticoid', false, 0),
  ('bf0c6d25-5596-564a-aec3-831e76b88d2c', '2a218242-b1ff-5ed9-a719-45fc201422a6', 'B', 'Dexamethasone and spironolactone', false, 1),
  ('b199eb93-d6bb-5c55-a5ea-c2628b4f0ab5', '2a218242-b1ff-5ed9-a719-45fc201422a6', 'C', 'Fludrocortisone alone', false, 2),
  ('6bc9e434-8acd-5c50-80c4-c9a6614e0535', '2a218242-b1ff-5ed9-a719-45fc201422a6', 'D', 'Levothyroxine', false, 3),
  ('fd8e42f3-ad5b-5c94-ba9a-3666fcd9eb59', '2a218242-b1ff-5ed9-a719-45fc201422a6', 'E', 'Hydrocortisone in divided doses plus fludrocortisone, with sick-day rules and a steroid emergency card', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('22f94f76-a4d3-5ca6-8b8e-86883b1e1071', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 32 year old woman is 29 weeks pregnant. Her symphysis-fundal height is 25 cm. Ultrasound shows an estimated fetal weight below the 10th centile, with raised umbilical artery Doppler resistance. What is the SINGLE most appropriate next step?', 'An SFH more than 3 cm below gestation (or below the 10th centile on a customised chart) needs an ultrasound scan. A small-for-gestational-age fetus with abnormal umbilical artery Doppler suggests placental insufficiency (fetal growth restriction). RCOG management is serial Doppler surveillance, CTG, and planned delivery based on Doppler findings (absent or reversed end-diastolic flow or abnormal ductus venosus). Corticosteroids are given if birth is expected before 34+6 weeks.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bce1cd0c-565a-57c2-8dc5-73261a867b95', '22f94f76-a4d3-5ca6-8b8e-86883b1e1071', 'A', 'Reassure, as small babies are healthy', false, 0),
  ('4d757e46-adf8-51ce-985f-d2d411467e74', '22f94f76-a4d3-5ca6-8b8e-86883b1e1071', 'B', 'Immediate caesarean section at 29 weeks', false, 1),
  ('11c5f4d9-64b8-5ed9-b567-e75b80789566', '22f94f76-a4d3-5ca6-8b8e-86883b1e1071', 'C', 'Repeat SFH measurement in 6 weeks', false, 2),
  ('a65bbfac-27dc-5ad8-91eb-cd6c1afcbb5e', '22f94f76-a4d3-5ca6-8b8e-86883b1e1071', 'D', 'Start high-dose iron', false, 3),
  ('a1bba488-32ea-552c-9571-35bb7c4021a2', '22f94f76-a4d3-5ca6-8b8e-86883b1e1071', 'E', 'Refer to the fetal medicine/obstetric team for increased surveillance (serial growth scans and Dopplers) and timing of birth', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b9567439-82ab-5a11-b372-39946e69bdf6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 30 year old woman at 39 weeks'' gestation had a normal vaginal delivery. Thirty minutes later, the placenta has not been delivered despite active management with oxytocin and controlled cord traction. She is not bleeding heavily. What is the SINGLE most appropriate management?', 'With active management of the third stage, the placenta is considered retained if it has not delivered within 30 minutes (60 minutes with physiological management). Give IV access, bloods and analgesia, and arrange manual removal in theatre with regional or general anaesthesia and prophylactic antibiotics. Do not use excessive cord traction (risk of uterine inversion or cord snapping). Watch for postpartum haemorrhage.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('94591da8-f8c3-5820-9bc5-7adb3c865c54', 'b9567439-82ab-5a11-b372-39946e69bdf6', 'A', 'Wait a further 24 hours', false, 0),
  ('a2a1726f-7d0d-5574-ac4b-2dbfe4898f86', 'b9567439-82ab-5a11-b372-39946e69bdf6', 'B', 'Pull firmly on the cord', false, 1),
  ('7278bcfe-01e9-5880-a01f-92ad780d7ae2', 'b9567439-82ab-5a11-b372-39946e69bdf6', 'C', 'Diagnose retained placenta; arrange manual removal of the placenta in theatre under anaesthesia', true, 2),
  ('41cc8322-17cd-5580-831c-2cec936ad05a', 'b9567439-82ab-5a11-b372-39946e69bdf6', 'D', 'Give IV methotrexate', false, 3),
  ('c065a80c-29e6-5068-b169-f15f85e1466b', 'b9567439-82ab-5a11-b372-39946e69bdf6', 'E', 'Discharge home with oral antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c019e2fc-f035-5ded-9272-de78f0474bc1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 35 year old woman with polycystic ovary syndrome has a BMI of 34 and has been trying to conceive for 2 years. Her partner''s semen analysis is normal and her tubes are patent. What is the SINGLE most appropriate first-line treatment after weight loss advice?', 'In anovulatory PCOS, weight loss (of 5-10%) improves ovulation. Letrozole is now generally preferred as first-line ovulation induction (higher live birth rate than clomifene, as in ESHRE guidance), with clomifene or metformin as alternatives. Monitor follicles with ultrasound. Second-line options are gonadotrophins or laparoscopic ovarian drilling. IVF is used if these fail.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('39c5b5b4-9115-5f9b-96ce-22c3cbf28cdc', 'c019e2fc-f035-5ded-9272-de78f0474bc1', 'A', 'Bilateral salpingectomy', false, 0),
  ('ad3a6a7c-9420-5843-a3c8-0e6ef22dd46e', 'c019e2fc-f035-5ded-9272-de78f0474bc1', 'B', 'IVF straight away', false, 1),
  ('8e0f9889-5641-5a6a-aed1-ccaadfe59204', 'c019e2fc-f035-5ded-9272-de78f0474bc1', 'C', 'Combined oral contraceptive pill', false, 2),
  ('a17cdb9f-7b5b-5950-b8ec-8c91b9044341', 'c019e2fc-f035-5ded-9272-de78f0474bc1', 'D', 'Metformin alone for all', false, 3),
  ('30c6d4aa-7107-5a35-a185-c83d5bfe3465', 'c019e2fc-f035-5ded-9272-de78f0474bc1', 'E', 'Letrozole (or clomifene) for ovulation induction', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a5ec27b8-26be-5222-87f4-15320ba2f175', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 52 year old woman has hot flushes, night sweats and low mood for 8 months. Her last period was 10 months ago. She has an intact uterus and no contraindications. Which HRT is MOST appropriate?', 'Women with a uterus need a progestogen alongside oestrogen to protect the endometrium. Women who are perimenopausal or have had their last period less than 12 months ago start with cyclical (sequential) combined HRT, which gives a monthly bleed. Continuous combined HRT is used once a woman is postmenopausal (12 months or more without periods, or after 1 year of cyclical HRT). Transdermal oestrogen carries a lower VTE risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5b0e83a7-66f7-5c34-9b2d-c3aa70593a84', 'a5ec27b8-26be-5222-87f4-15320ba2f175', 'A', 'Oestrogen-only HRT', false, 0),
  ('77e4842c-fedb-5e3d-94c1-da2443dcf955', 'a5ec27b8-26be-5222-87f4-15320ba2f175', 'B', 'Continuous combined HRT', false, 1),
  ('f2341d46-e828-5468-b07a-a44578ddc471', 'a5ec27b8-26be-5222-87f4-15320ba2f175', 'C', 'Tibolone as first-line', false, 2),
  ('f3616dd8-ea34-5341-a671-3e0b18a70d13', 'a5ec27b8-26be-5222-87f4-15320ba2f175', 'D', 'Testosterone gel alone', false, 3),
  ('5b2e664f-a4d8-5591-83e5-ee8588a7263a', 'a5ec27b8-26be-5222-87f4-15320ba2f175', 'E', 'Cyclical (sequential) combined HRT (oestrogen plus a progestogen)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('97f9cbb0-103b-5d92-83c7-1eaf1469a328', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 4 month old baby has had episodes of vomiting after feeds since birth. She is gaining weight well along the 50th centile and is otherwise well, with no blood in the vomit. What is the SINGLE most likely diagnosis?', 'Regurgitation is common in infants (affecting up to 40%), usually starts before 8 weeks, and resolves by about 1 year. If the baby is thriving and has no red flags (bile-stained vomit, haematemesis, poor weight gain, projectile vomiting, distress), reassure and review feeding (avoid overfeeding, try smaller more frequent feeds). Thickeners or alginates are used only if regurgitation is frequent and distressing. Bilious vomiting suggests malrotation and is an emergency.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('97e3e8df-f287-526c-b9e0-e6b6b53f8d9f', '97f9cbb0-103b-5d92-83c7-1eaf1469a328', 'A', 'Cow''s milk protein allergy', false, 0),
  ('caf6ef97-de99-53a1-a42b-ee6c64212564', '97f9cbb0-103b-5d92-83c7-1eaf1469a328', 'B', 'Pyloric stenosis', false, 1),
  ('08cc2860-715f-5d01-b4c2-c9a875fba368', '97f9cbb0-103b-5d92-83c7-1eaf1469a328', 'C', 'Intussusception', false, 2),
  ('4de63c31-0cec-50af-94b8-b74bf0fdd3ae', '97f9cbb0-103b-5d92-83c7-1eaf1469a328', 'D', 'Malrotation with volvulus', false, 3),
  ('c501379e-0733-571a-83ee-cf35178c63cf', '97f9cbb0-103b-5d92-83c7-1eaf1469a328', 'E', 'Physiological gastro-oesophageal reflux', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('192b8f30-6295-576e-b264-1b460453d680', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 9 month old boy has had a fever of 39.2°C for 5 days, bilateral non-purulent conjunctivitis, cracked red lips, a polymorphous rash, cervical lymphadenopathy and swollen hands. What is the SINGLE most important treatment to prevent complications?', 'This is Kawasaki disease: fever for 5 days or more plus 4 of 5 features (conjunctivitis, mucosal changes, rash, extremity changes, cervical lymphadenopathy). It is one of the few indications for aspirin in children. IVIg given within 10 days of onset reduces the risk of coronary artery aneurysms. Echocardiography is needed at diagnosis and at follow-up. Steroids may be added for high-risk patients.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8427af43-6311-5061-9841-fac91d83ac06', '192b8f30-6295-576e-b264-1b460453d680', 'A', 'Oral prednisolone alone', false, 0),
  ('cc2d5fec-9891-5e9e-b58c-166a137f18b2', '192b8f30-6295-576e-b264-1b460453d680', 'B', 'IV ceftriaxone', false, 1),
  ('3d91c25d-94f2-53fb-82c3-8fcbe5f8d367', '192b8f30-6295-576e-b264-1b460453d680', 'C', 'IV immunoglobulin plus aspirin', true, 2),
  ('1bd22d0d-653d-57c3-a437-4ef5cf6f6a69', '192b8f30-6295-576e-b264-1b460453d680', 'D', 'Paracetamol only', false, 3),
  ('178a44bb-0248-52e2-8409-80c0722c4424', '192b8f30-6295-576e-b264-1b460453d680', 'E', 'Oral amoxicillin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('854d516f-b077-5a41-b387-2a7cfa9f6190', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 7 year old girl has had polyuria, polydipsia and weight loss for 3 weeks. Today she is vomiting and drowsy with deep sighing breathing. Capillary glucose is 28 mmol/L, ketones 5.2 mmol/L, pH 7.08. She is not shocked. What is the SINGLE most important principle of her initial fluid management?', 'BSPED 2021 paediatric DKA guidance: if not shocked, a 10 mL/kg bolus of 0.9% saline over 60 minutes may be given if needed. Calculate the deficit (5% for pH 7.1 or above, 10% for pH under 7.1), add maintenance, and replace over 48 hours. Start an insulin infusion at 0.05-0.1 units/kg/hour 1-2 hours after IV fluids (no bolus). Watch for cerebral oedema (headache, falling HR, rising BP, irritability), which is treated with mannitol or hypertonic saline.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4922f547-cd5f-59cd-a461-cfe3bfc3f693', '854d516f-b077-5a41-b387-2a7cfa9f6190', 'A', 'Give hypotonic 0.18% saline from the start', false, 0),
  ('af2754d9-804f-52e3-a3a1-9ded66ac8dbb', '854d516f-b077-5a41-b387-2a7cfa9f6190', 'B', 'Rapid correction of the deficit over 4 hours', false, 1),
  ('a4087c23-0ed9-525e-921f-8864a66e64e8', '854d516f-b077-5a41-b387-2a7cfa9f6190', 'C', 'Start IV insulin bolus before any fluids', false, 2),
  ('2ca5dfb0-0f34-547d-8518-6cf12dfc336e', '854d516f-b077-5a41-b387-2a7cfa9f6190', 'D', 'Give IV fluids cautiously (avoiding a routine bolus unless shocked) and correct the deficit over 48 hours to reduce the risk of cerebral oedema', true, 3),
  ('c7128b20-4af1-5948-81a5-b7a260c5474f', '854d516f-b077-5a41-b387-2a7cfa9f6190', 'E', 'Give 20 mL/kg boluses repeatedly regardless of shock status', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c5dca87c-ea94-5c8e-a63e-f8b12c075eb3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A mother of a 6 month old baby asks when the soft spot on the top of her baby''s head will close. Which statement about the anterior fontanelle is CORRECT?', 'The anterior fontanelle usually closes between 12 and 18 months (it can be up to 24 months). The posterior fontanelle closes by about 2 months. A bulging fontanelle in a calm, upright infant suggests raised intracranial pressure (such as meningitis or hydrocephalus). A sunken fontanelle suggests dehydration. Early closure raises the possibility of craniosynostosis, and late closure the possibility of hypothyroidism, rickets or hydrocephalus.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('584739f6-a8db-59f6-9d35-0cd78c8f8211', 'c5dca87c-ea94-5c8e-a63e-f8b12c075eb3', 'A', 'It normally closes at birth', false, 0),
  ('a1748411-cae6-51e8-b07d-9774a69c5008', 'c5dca87c-ea94-5c8e-a63e-f8b12c075eb3', 'B', 'A bulging fontanelle in a crying infant is always pathological', false, 1),
  ('93dcc38c-9335-54ee-bd73-9476ede089aa', 'c5dca87c-ea94-5c8e-a63e-f8b12c075eb3', 'C', 'A sunken fontanelle suggests raised intracranial pressure', false, 2),
  ('d94faa1b-60cc-56bd-9ba2-6b6e215f5da1', 'c5dca87c-ea94-5c8e-a63e-f8b12c075eb3', 'D', 'It normally closes between 12 and 18 months of age', true, 3),
  ('a9fcc80c-e39a-50ff-90b1-2a0f12a2cbee', 'c5dca87c-ea94-5c8e-a63e-f8b12c075eb3', 'E', 'It normally closes at 4 years', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a3932ff8-8fd8-5db1-8bd2-5ebe95b86023', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 30 year old woman has had low mood, poor sleep and loss of interest for 2 months. PHQ-9 is 18. She has not responded to guided self-help. What is the MOST appropriate next step according to NICE?', 'NICE NG222 (2022) for more severe depression recommends a shared decision between treatments including combined individual CBT and an antidepressant, individual CBT, behavioural activation, or an antidepressant (usually an SSRI). Review within 2 weeks of starting an antidepressant (1 week if under 25 or there is suicide risk, as there may be an increased risk of suicidal thoughts early on). Continue antidepressants for at least 6 months after remission.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8429bb9c-adaf-53ea-9c18-803d9a24f796', 'a3932ff8-8fd8-5db1-8bd2-5ebe95b86023', 'A', 'Electroconvulsive therapy', false, 0),
  ('2f2a5cd3-7d0e-51a2-84bf-668b518f570f', 'a3932ff8-8fd8-5db1-8bd2-5ebe95b86023', 'B', 'Lithium as first-line', false, 1),
  ('97373446-e24d-5c27-8bf0-7e3688b1cfb3', 'a3932ff8-8fd8-5db1-8bd2-5ebe95b86023', 'C', 'Long-term benzodiazepines', false, 2),
  ('e713b658-b272-5e1d-b937-6b11283a4197', 'a3932ff8-8fd8-5db1-8bd2-5ebe95b86023', 'D', 'Admit under Section 2', false, 3),
  ('428e5ae7-e566-54ae-9261-8b8451a6f961', 'a3932ff8-8fd8-5db1-8bd2-5ebe95b86023', 'E', 'Offer a choice that includes CBT, behavioural activation or an SSRI (or a combination), based on her preference', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6c9599a4-fc20-5d44-bbe3-604e35cd8541', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 25 year old man with schizophrenia has had two adequate trials of different antipsychotics (including one second-generation) without response. What is the SINGLE most appropriate next drug?', 'Treatment-resistant schizophrenia (failure of 2 or more antipsychotics at adequate dose and duration, at least one being a second-generation drug) is an indication for clozapine. It needs registration with a monitoring service and regular FBC monitoring because of the risk of agranulocytosis (weekly for 18 weeks, then less often). Other side effects include myocarditis, constipation (which can be fatal through ileus), hypersalivation, seizures and weight gain. Smoking changes clozapine levels.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('60edf082-3262-5bf5-ad62-d48196572982', '6c9599a4-fc20-5d44-bbe3-604e35cd8541', 'A', 'Diazepam', false, 0),
  ('fb33a7ec-6b84-55db-8c1e-2e431ea7105f', '6c9599a4-fc20-5d44-bbe3-604e35cd8541', 'B', 'Haloperidol depot', false, 1),
  ('cd49033d-197b-5b15-96d9-cf1a7a84ebf3', '6c9599a4-fc20-5d44-bbe3-604e35cd8541', 'C', 'Sertraline', false, 2),
  ('95187c69-b67a-5d66-ad60-b4a8ab5378ed', '6c9599a4-fc20-5d44-bbe3-604e35cd8541', 'D', 'Clozapine', true, 3),
  ('c403ef1f-5354-5a03-9402-f44b42a7909c', '6c9599a4-fc20-5d44-bbe3-604e35cd8541', 'E', 'Lithium', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bc762538-d852-5321-a8b7-7eaa51ada096', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 35 year old woman with bipolar disorder takes lithium. She has developed a coarse tremor, vomiting, diarrhoea, ataxia and confusion after starting a new medication for hypertension. Which drug MOST likely caused this?', 'Lithium toxicity (coarse tremor, GI upset, ataxia, confusion, seizures) is made more likely by drugs that reduce renal lithium clearance: thiazides, ACE inhibitors and ARBs, and NSAIDs. Dehydration also increases the risk. Check lithium levels urgently, stop lithium, and give IV fluids. Haemodialysis is used for severe toxicity. A fine tremor is a common side effect at therapeutic levels.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b7f9d940-4917-5d1b-a361-25524337ee4a', 'bc762538-d852-5321-a8b7-7eaa51ada096', 'A', 'Atenolol', false, 0),
  ('e58c540c-4675-5ccd-bf68-81315ac02a9f', 'bc762538-d852-5321-a8b7-7eaa51ada096', 'B', 'Doxazosin', false, 1),
  ('6ba16bb9-4caf-5166-b6dc-e71cb6dc01fb', 'bc762538-d852-5321-a8b7-7eaa51ada096', 'C', 'Bendroflumethiazide', true, 2),
  ('b6911db7-9c00-509d-853e-0876d6c7564b', 'bc762538-d852-5321-a8b7-7eaa51ada096', 'D', 'Amlodipine', false, 3),
  ('74340e92-cb7f-5b1b-ac37-b6c18adf5b85', 'bc762538-d852-5321-a8b7-7eaa51ada096', 'E', 'Hydralazine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('959ce1b6-ad65-5633-bab1-65eef245a82f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 3 year old boy swallowed a coin-sized button battery 1 hour ago. He is drooling and refusing food. X-ray shows a round radio-opaque object with a ''halo'' (double-ring) sign in the oesophagus. What is the SINGLE most appropriate management?', 'A button battery lodged in the oesophagus can cause liquefactive necrosis, perforation, tracheo-oesophageal fistula and fatal aorto-oesophageal fistula within hours. Removal by emergency endoscopy is needed. Honey (in children over 1 year, before arrival) or sucralfate may reduce injury while awaiting removal. The double-ring (halo) sign distinguishes it from a coin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6ad2073e-69bf-5528-a277-4430fb3c7ab0', '959ce1b6-ad65-5633-bab1-65eef245a82f', 'A', 'Wait for it to pass and check the stools', false, 0),
  ('0e336f0e-e2c7-5830-84d6-a100145d7f46', '959ce1b6-ad65-5633-bab1-65eef245a82f', 'B', 'Give a laxative', false, 1),
  ('602ce329-0b90-52a2-9796-f04a480951c1', '959ce1b6-ad65-5633-bab1-65eef245a82f', 'C', 'Repeat X-ray in 1 week', false, 2),
  ('a950ab95-0d2c-59d4-81ed-eb4578a12e4f', '959ce1b6-ad65-5633-bab1-65eef245a82f', 'D', 'Induce vomiting', false, 3),
  ('0e062d76-933c-5a91-a51b-e0c8357683cd', '959ce1b6-ad65-5633-bab1-65eef245a82f', 'E', 'Emergency endoscopic removal (ideally within 2 hours)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a729e2ee-ab4a-5a64-8489-8264d0083f31', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 40 year old man was rescued from a cold river and is now in the Emergency Department. His core temperature is 27°C and he is in ventricular fibrillation. After 3 shocks VF persists. What is the SINGLE most appropriate approach?', 'Resuscitation Council UK: in hypothermic cardiac arrest, if VF persists after 3 shocks, delay further shocks until the core temperature is above 30°C. Withhold adrenaline below 30°C, and give it at double intervals (6-10 minutes) between 30 and 35°C. Active internal rewarming with extracorporeal life support is ideal. ''Nobody is dead until warm and dead.''', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('01bfa1c3-876e-55a6-a382-54e416c6b49d', 'a729e2ee-ab4a-5a64-8489-8264d0083f31', 'A', 'Give IV amiodarone 300 mg every 2 minutes', false, 0),
  ('de25d446-0d87-5d67-865d-1324accc8641', 'a729e2ee-ab4a-5a64-8489-8264d0083f31', 'B', 'Continue shocks every 2 minutes indefinitely', false, 1),
  ('f9cac6d6-bc12-5027-98bb-f1b1ad630f6b', 'a729e2ee-ab4a-5a64-8489-8264d0083f31', 'C', 'Give adrenaline every 3-5 minutes as normal', false, 2),
  ('5e10c7d9-1440-58e9-9e9c-14a2a679a396', 'a729e2ee-ab4a-5a64-8489-8264d0083f31', 'D', 'Stop resuscitation, as he is dead', false, 3),
  ('a93d455e-bcf4-5a05-a3a8-f0458fdac3a8', 'a729e2ee-ab4a-5a64-8489-8264d0083f31', 'E', 'Continue CPR, withhold further shocks and adrenaline until core temperature is above 30°C, and actively rewarm (ideally with ECMO/ECLS)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7babd9b9-2963-529d-aa53-6714b04431c1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 25 year old man presents 3 hours after a staggered paracetamol overdose over 24 hours. What is the SINGLE most appropriate management?', 'For a staggered overdose (taken over more than 1 hour), the treatment nomogram cannot be used. MHRA/TOXBASE guidance is to start IV acetylcysteine immediately, then check paracetamol level, INR, LFTs and creatinine, and continue treatment based on results. The SNAP regimen (12-hour) has fewer adverse reactions.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('08fd50d3-227b-5df8-bab0-2173a85c8d3a', '7babd9b9-2963-529d-aa53-6714b04431c1', 'A', 'Measure the level at 4 hours and plot on the nomogram before deciding', false, 0),
  ('b5e947b4-9019-5342-a3f3-898b936c4750', '7babd9b9-2963-529d-aa53-6714b04431c1', 'B', 'Start IV acetylcysteine immediately without waiting for the paracetamol level', true, 1),
  ('bfb44c00-9539-533f-b53e-1349924a37e5', '7babd9b9-2963-529d-aa53-6714b04431c1', 'C', 'Give oral methionine only', false, 2),
  ('e9b685ac-8b37-5c37-89a6-542bde3a5580', '7babd9b9-2963-529d-aa53-6714b04431c1', 'D', 'Observe only if he is asymptomatic', false, 3),
  ('661e7da5-c29d-5b36-9411-980f1319306e', '7babd9b9-2963-529d-aa53-6714b04431c1', 'E', 'Give activated charcoal and discharge', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('55a1daac-a8d5-572d-8db0-163ba54e6ff8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 15 year old girl asks her GP for the combined pill. She has a 16 year old boyfriend and says she will have sex anyway. She refuses to involve her parents. She understands the advice, and the GP considers her competent. What is the SINGLE most appropriate action?', 'Under 16s can consent to contraception if Fraser criteria are met: she understands the advice, cannot be persuaded to tell her parents, is likely to have sex anyway, her health would suffer without contraception, and it is in her best interests. Assess for exploitation or abuse. A child under 13 cannot legally consent to sex, and any such case requires safeguarding referral.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f2bca8b0-c25e-5bad-b4cb-6d0fedb25509', '55a1daac-a8d5-572d-8db0-163ba54e6ff8', 'A', 'Refuse until she is 16', false, 0),
  ('77804a89-94d4-59a6-9da9-f03f1ddcf1a6', '55a1daac-a8d5-572d-8db0-163ba54e6ff8', 'B', 'Inform the police', false, 1),
  ('d2c97ec8-945d-542e-b641-2c688394feab', '55a1daac-a8d5-572d-8db0-163ba54e6ff8', 'C', 'Prescribe only if her mother signs consent', false, 2),
  ('bc7a1206-7e37-5056-abad-75ca04217afa', '55a1daac-a8d5-572d-8db0-163ba54e6ff8', 'D', 'Prescribe contraception if the Fraser criteria are met, encouraging her to tell her parents, and assess for safeguarding concerns', true, 3),
  ('88112ca2-904b-554f-879e-8c315c4f8233', '55a1daac-a8d5-572d-8db0-163ba54e6ff8', 'E', 'Inform her parents without her consent', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('205d05f6-1bad-590e-8d5c-5a5672f1aa3c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 79 year old man with dementia has lost capacity to make decisions about his care. He made a valid and applicable Lasting Power of Attorney for Health and Welfare, registered with the Office of the Public Guardian. A decision about moving to a care home is needed. Who should make this decision?', 'A registered Health and Welfare LPA, used once the person lacks capacity, allows the attorney to make decisions about care and treatment in the person''s best interests (life-sustaining treatment only if this is expressly stated). Clinicians must follow the Mental Capacity Act best interests process. An IMCA is needed only if there is nobody appropriate to consult.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('31b71b25-efa5-571c-8676-cffdac45d8c7', '205d05f6-1bad-590e-8d5c-5a5672f1aa3c', 'A', 'The attorney under the Health and Welfare LPA, acting in his best interests', true, 0),
  ('4eb9ffa2-c03e-5bc1-be4a-4e4fa231b73d', '205d05f6-1bad-590e-8d5c-5a5672f1aa3c', 'B', 'His neighbour who visits often', false, 1),
  ('b957294a-c867-58bd-b5d0-28bb2143b424', '205d05f6-1bad-590e-8d5c-5a5672f1aa3c', 'C', 'The hospital consultant alone', false, 2),
  ('9bc8b1f0-7a84-5417-bf8a-5c74bc24c26e', '205d05f6-1bad-590e-8d5c-5a5672f1aa3c', 'D', 'His GP alone', false, 3),
  ('365c6ca6-37a6-53b2-a517-e881b4fb9f7d', '205d05f6-1bad-590e-8d5c-5a5672f1aa3c', 'E', 'The Court of Protection in every case', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('03f6fd31-cfe0-5a0e-abef-d952c87289b8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A junior doctor realises she gave a patient the wrong dose of a drug. The patient has not been harmed. What is the SINGLE most appropriate action according to the duty of candour?', 'GMC/NMC guidance on the professional duty of candour: be open and honest with patients when something goes wrong with their care that causes, or has the potential to cause, harm or distress. Apologise, explain, put things right where possible, and report incidents and near misses so that lessons can be learned. Never alter records.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e092cdec-d39b-5fc8-b855-3720f866981b', '03f6fd31-cfe0-5a0e-abef-d952c87289b8', 'A', 'Wait to see if harm develops before saying anything', false, 0),
  ('de4b5051-2a06-55f6-9578-8b66242f7e40', '03f6fd31-cfe0-5a0e-abef-d952c87289b8', 'B', 'Do not tell the patient, as no harm occurred', false, 1),
  ('d7eddc0d-360d-58e1-8f57-bbc29b513ace', '03f6fd31-cfe0-5a0e-abef-d952c87289b8', 'C', 'Amend the notes to show the correct dose', false, 2),
  ('5e1571ad-0893-54f4-9e75-a649282eeb48', '03f6fd31-cfe0-5a0e-abef-d952c87289b8', 'D', 'Tell the patient, apologise, explain what happened and what will be done, and report it via the incident reporting system', true, 3),
  ('29815137-8268-563c-88d5-1d4eb566423b', '03f6fd31-cfe0-5a0e-abef-d952c87289b8', 'E', 'Tell only the consultant and keep it confidential', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('004d4a4c-06fb-54f5-be8b-302b5ce37821', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 30 year old Jehovah''s Witness who has capacity is bleeding heavily after a road traffic collision. She has a valid advance decision refusing blood transfusion in any circumstances, even if her life is at risk. She is now unconscious. What is the SINGLE most appropriate action?', 'A valid and applicable advance decision refusing life-sustaining treatment (in writing, signed, witnessed and stating that it applies even if life is at risk) is legally binding under the Mental Capacity Act 2005. Use all other acceptable treatments. If there is real doubt about whether it is valid, treatment can be given while this is clarified (seek urgent legal advice).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('41c02ec1-75a0-59cc-9cbe-778423399031', '004d4a4c-06fb-54f5-be8b-302b5ce37821', 'A', 'Ask her husband to override her decision', false, 0),
  ('ada82965-acd8-5b05-a74d-1c5f63a3ebf4', '004d4a4c-06fb-54f5-be8b-302b5ce37821', 'B', 'Seek a court order before every decision', false, 1),
  ('9f448798-3b30-5688-80e5-d07f15b151f9', '004d4a4c-06fb-54f5-be8b-302b5ce37821', 'C', 'Transfuse half the usual volume', false, 2),
  ('c53df959-df9b-5f26-b3fc-97d3482affd0', '004d4a4c-06fb-54f5-be8b-302b5ce37821', 'D', 'Transfuse because she is unconscious', false, 3),
  ('c8b9d469-5809-5a1a-8d69-0e445c28385b', '004d4a4c-06fb-54f5-be8b-302b5ce37821', 'E', 'Respect her advance decision and use all other measures (e.g. cell salvage if acceptable, tranexamic acid, haemostatic surgery)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('78309bfd-fe79-5416-ad2e-0af9d37ed4d9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 62 year old man with diabetes has noticed blurring and distortion of his central vision. Retinal screening shows hard exudates and thickening at the macula. What is the SINGLE most likely diagnosis?', 'Diabetic maculopathy (exudates or thickening within 1 disc diameter of the fovea) is the most common cause of visual loss in diabetes. It is treated with intravitreal anti-VEGF injections (such as ranibizumab or aflibercept) for centre-involving oedema, or laser. Proliferative retinopathy (new vessels) is treated with panretinal photocoagulation. Optimise glucose, BP and lipids.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('849ca28d-c065-5b1a-ada3-777a2603d1bc', '78309bfd-fe79-5416-ad2e-0af9d37ed4d9', 'A', 'Retinal detachment', false, 0),
  ('0eac57e6-f476-5695-adb3-55fc5c97484f', '78309bfd-fe79-5416-ad2e-0af9d37ed4d9', 'B', 'Cataract', false, 1),
  ('68fae374-1b75-5b1d-89d2-9b9a6aa74ef2', '78309bfd-fe79-5416-ad2e-0af9d37ed4d9', 'C', 'Proliferative diabetic retinopathy', false, 2),
  ('3cdf1756-1ba3-5b8b-8c6f-27a788988cc8', '78309bfd-fe79-5416-ad2e-0af9d37ed4d9', 'D', 'Central retinal artery occlusion', false, 3),
  ('26e3b0b5-1819-5865-95e0-96296e4e50e1', '78309bfd-fe79-5416-ad2e-0af9d37ed4d9', 'E', 'Diabetic maculopathy (diabetic macular oedema)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bdeb7d6a-1acc-5903-bfc5-c3ead231a9b4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 65 year old man has had flashes of light and many new floaters in his left eye for a day, followed by a shadow spreading from his peripheral vision. What is the SINGLE most likely diagnosis?', 'Flashes (photopsia) and floaters followed by a curtain or shadow in the visual field suggest retinal detachment. It needs same-day ophthalmology referral, especially if the macula is still ''on'', to preserve central vision. Risk factors include myopia, previous cataract surgery and trauma. A PVD without a tear causes flashes and floaters without a field defect, but must still be examined to exclude a tear.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('46ed443b-22c0-568f-b220-a5e87b8804ea', 'bdeb7d6a-1acc-5903-bfc5-c3ead231a9b4', 'A', 'Migraine with aura', false, 0),
  ('8518a9cc-32b4-5c9f-92ee-9d40231e4958', 'bdeb7d6a-1acc-5903-bfc5-c3ead231a9b4', 'B', 'Vitreous haemorrhage from diabetes', false, 1),
  ('412f358e-c3ce-595c-bbbb-0e8a0056077c', 'bdeb7d6a-1acc-5903-bfc5-c3ead231a9b4', 'C', 'Posterior vitreous detachment without a tear', false, 2),
  ('b45aa185-8a95-5d31-aae9-0ec8a0bf8cde', 'bdeb7d6a-1acc-5903-bfc5-c3ead231a9b4', 'D', 'Central retinal vein occlusion', false, 3),
  ('cb53fef5-f714-59ea-9906-58b01f36a857', 'bdeb7d6a-1acc-5903-bfc5-c3ead231a9b4', 'E', 'Rhegmatogenous retinal detachment', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('51cbccc1-9cea-5eae-b53d-9df9ee886a1d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 65 year old man has a pulsatile abdominal mass. Ultrasound shows an abdominal aortic aneurysm of 5.8 cm diameter. He is asymptomatic and fit for surgery. What is the SINGLE most appropriate management?', 'NHS AAA screening thresholds: 3.0-4.4 cm, annual surveillance; 4.5-5.4 cm, 3-monthly surveillance; 5.5 cm or more (or growing over 1 cm per year, or symptomatic), refer to a vascular surgeon to be seen within 2 weeks and treated within 8 weeks if suitable. Treatment can be open or endovascular (EVAR) repair. Control cardiovascular risk factors and give statin and antiplatelet therapy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1a3ad307-655a-52e9-8d5c-1b1e8cf6047a', '51cbccc1-9cea-5eae-b53d-9df9ee886a1d', 'A', 'Ultrasound surveillance every 3 months', false, 0),
  ('9d27c017-1080-5f37-9ebe-611923938729', '51cbccc1-9cea-5eae-b53d-9df9ee886a1d', 'B', 'No further action', false, 1),
  ('84d20d69-a290-5c89-aad6-9c2c26fb92ef', '51cbccc1-9cea-5eae-b53d-9df9ee886a1d', 'C', 'Emergency laparotomy today', false, 2),
  ('b96bf162-6723-5a65-b7f6-c76e0c9bee8e', '51cbccc1-9cea-5eae-b53d-9df9ee886a1d', 'D', 'Annual surveillance', false, 3),
  ('09b9c17d-2daf-5902-bed0-19d0a21eb2dc', '51cbccc1-9cea-5eae-b53d-9df9ee886a1d', 'E', 'Refer to vascular surgery for elective repair (within 8 weeks of diagnosis)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('39e8507d-1c0d-50ff-93ff-f1667d0637bc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 55 year old man has severe central chest pain radiating to his back after an episode of forceful vomiting following heavy alcohol intake. He has subcutaneous emphysema in his neck. What is the SINGLE most likely diagnosis?', 'Boerhaave syndrome is a full-thickness tear of the oesophagus (usually the left posterolateral lower third) after forceful vomiting. It causes chest pain, subcutaneous emphysema and mediastinitis (Mackler''s triad: vomiting, chest pain, subcutaneous emphysema). Diagnosis is by CT with oral contrast. It needs nil by mouth, IV antibiotics and antifungals, and often surgery. A Mallory-Weiss tear is a mucosal tear causing haematemesis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('98f44e4c-e32d-549f-99c5-e682c893b28f', '39e8507d-1c0d-50ff-93ff-f1667d0637bc', 'A', 'Acute pancreatitis', false, 0),
  ('262dd197-7ff4-5494-99d7-ad13ba18350b', '39e8507d-1c0d-50ff-93ff-f1667d0637bc', 'B', 'Mallory-Weiss tear', false, 1),
  ('ff4662fe-3702-582f-b12d-4e34ed0bcfb8', '39e8507d-1c0d-50ff-93ff-f1667d0637bc', 'C', 'Boerhaave syndrome (oesophageal rupture)', true, 2),
  ('2017f6cd-de98-5713-97df-02ea84fd1c75', '39e8507d-1c0d-50ff-93ff-f1667d0637bc', 'D', 'Perforated duodenal ulcer', false, 3),
  ('86f06166-4d88-59ab-aacc-de807532411e', '39e8507d-1c0d-50ff-93ff-f1667d0637bc', 'E', 'Myocardial infarction', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('64525fa7-094d-5f63-9a16-4ac48f2e9f94', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 40 year old woman has a firm, 2 cm nodule in the right lobe of her thyroid. She is euthyroid. Ultrasound shows a solid hypoechoic nodule with microcalcifications (U4). Fine needle aspiration shows Thy5 cytology with psammoma bodies and ''Orphan Annie'' nuclei. What is the SINGLE most likely diagnosis?', 'Papillary carcinoma is the most common thyroid cancer (about 80%). It is linked to radiation exposure, spreads through the lymphatics, and has an excellent prognosis. Cytology shows ground-glass (Orphan Annie eye) nuclei and psammoma bodies. Follicular carcinoma spreads through the blood (to bone and lung) and needs histology to show capsular or vascular invasion. Medullary carcinoma comes from C cells (calcitonin, MEN2). Anaplastic carcinoma occurs in older people and grows rapidly.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4cfa2dc2-3e50-5c8b-910f-22d787858bfa', '64525fa7-094d-5f63-9a16-4ac48f2e9f94', 'A', 'Thyroid lymphoma', false, 0),
  ('87613dab-62bb-5870-af4d-45fa054a5e0c', '64525fa7-094d-5f63-9a16-4ac48f2e9f94', 'B', 'Medullary thyroid carcinoma', false, 1),
  ('91724a5a-8b67-5314-85e2-0c1df6fccf51', '64525fa7-094d-5f63-9a16-4ac48f2e9f94', 'C', 'Papillary thyroid carcinoma', true, 2),
  ('3e38ef39-ded4-5e92-91bc-051428aab482', '64525fa7-094d-5f63-9a16-4ac48f2e9f94', 'D', 'Anaplastic thyroid carcinoma', false, 3),
  ('1ead6995-4b1e-5eaa-a073-28cff721276a', '64525fa7-094d-5f63-9a16-4ac48f2e9f94', 'E', 'Follicular thyroid carcinoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('947a629c-0ab5-5026-8f2a-dea24648fe7c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 45 year old woman has severe right upper quadrant pain, fever (39°C), rigors and jaundice. Her bilirubin is 98 µmol/L, ALP 560 U/L and WCC 19 x10^9/L. Ultrasound shows a dilated common bile duct. What is the SINGLE most likely diagnosis?', 'Charcot''s triad (fever with rigors, RUQ pain, jaundice) indicates ascending cholangitis from biliary obstruction, usually a CBD stone. Reynolds'' pentad adds confusion and shock. Management: resuscitation, blood cultures, IV antibiotics, and biliary drainage by ERCP (urgent if severe or not responding). Acute cholecystitis gives RUQ pain and fever with a positive Murphy''s sign, but jaundice is uncommon.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9491b6bc-b24e-5654-82b0-f3c8e1d6e508', '947a629c-0ab5-5026-8f2a-dea24648fe7c', 'A', 'Acute hepatitis A', false, 0),
  ('208e85fc-6667-5921-8358-fb2feee7bda3', '947a629c-0ab5-5026-8f2a-dea24648fe7c', 'B', 'Pancreatic carcinoma', false, 1),
  ('17c9bade-ef13-5b0b-b266-da9315deda61', '947a629c-0ab5-5026-8f2a-dea24648fe7c', 'C', 'Ascending cholangitis', true, 2),
  ('e6b48283-079c-5bb3-b0cc-3cc62ad8e98c', '947a629c-0ab5-5026-8f2a-dea24648fe7c', 'D', 'Biliary colic', false, 3),
  ('d7340680-23fd-5b67-9f14-2b4482e4dd14', '947a629c-0ab5-5026-8f2a-dea24648fe7c', 'E', 'Acute cholecystitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d06f0da7-7cfd-5805-a3c5-18ed96342801', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 32 year old man has had a painful perianal lump for 2 days. It is a 1 cm tense, bluish, very tender swelling at the anal margin. What is the SINGLE most appropriate management within 72 hours of onset?', 'A thrombosed external haemorrhoid (perianal haematoma) is acutely painful. If it presents within 72 hours, surgical excision or evacuation under local anaesthetic gives fast relief. After 72 hours, conservative management (analgesia, stool softeners, ice, sitz baths) is preferred, as the pain is already improving. Banding is used for internal haemorrhoids only (above the dentate line).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a2465f1a-c249-5510-81fb-933981f693db', 'd06f0da7-7cfd-5805-a3c5-18ed96342801', 'A', 'Rubber band ligation', false, 0),
  ('fcc80c2d-a672-5d96-99a3-24a1a160819d', 'd06f0da7-7cfd-5805-a3c5-18ed96342801', 'B', 'Botulinum toxin injection', false, 1),
  ('ea71eea7-766a-5b0e-8d7d-cac9bb9966d0', 'd06f0da7-7cfd-5805-a3c5-18ed96342801', 'C', 'Oral antibiotics only', false, 2),
  ('df988d19-f6e8-5adc-bec7-1a97c1f1cfc1', 'd06f0da7-7cfd-5805-a3c5-18ed96342801', 'D', 'Haemorrhoidectomy under general anaesthetic for all', false, 3),
  ('6c18cd02-f111-5b12-a586-ec20e6795d18', 'd06f0da7-7cfd-5805-a3c5-18ed96342801', 'E', 'Consider excision (or incision) of the thrombosed external haemorrhoid under local anaesthetic, or conservative treatment', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4dc2246b-7adb-5775-86c9-4b4f9d84d662', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 14 year old obese boy has a limp and pain in his left knee for 3 weeks. On examination, there is loss of internal rotation of the left hip, and the hip externally rotates when flexed. What is the SINGLE most appropriate next investigation?', 'This is slipped capital (upper) femoral epiphysis (SUFE): an obese adolescent with hip, thigh or knee pain (referred pain from the hip through the obturator nerve) and loss of internal rotation. Frog-leg lateral views are most sensitive (Klein''s line). It is bilateral in about 20% of cases. Treatment is urgent surgical fixation in situ. Always examine the hip in a child with knee pain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1a092f46-9983-5bb1-aa2e-c89ab2170ea7', '4dc2246b-7adb-5775-86c9-4b4f9d84d662', 'A', 'Ultrasound of the left knee', false, 0),
  ('0527204a-194c-55b1-9657-5cc95ce460e3', '4dc2246b-7adb-5775-86c9-4b4f9d84d662', 'B', 'X-ray of the left knee only', false, 1),
  ('65099183-765c-5830-8630-dadc91b446ed', '4dc2246b-7adb-5775-86c9-4b4f9d84d662', 'C', 'Blood cultures', false, 2),
  ('303b34c2-a923-52ea-9385-b86dc1e552ca', '4dc2246b-7adb-5775-86c9-4b4f9d84d662', 'D', 'MRI of the lumbar spine', false, 3),
  ('70f340eb-6440-5b87-acf9-026720d6a598', '4dc2246b-7adb-5775-86c9-4b4f9d84d662', 'E', 'AP and frog-leg lateral X-rays of both hips', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d1e41d9f-8d06-58a5-b69f-0ffb4cd3deca', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 55 year old manual worker has pain on the lateral side of his elbow for 2 months, made worse by gripping and resisted wrist extension. There is tenderness over the lateral epicondyle. What is the SINGLE most appropriate first-line management?', 'Lateral epicondylitis (tennis elbow) is a degenerative condition of the common extensor origin (ECRB). It is self-limiting over 6-24 months. First-line treatment is activity modification, analgesia, an epicondylitis brace and eccentric loading physiotherapy. Steroid injection gives short-term relief but can worsen long-term outcomes. Medial epicondylitis is golfer''s elbow.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('19d2114b-63b9-5c5d-a4ad-6503ddac9005', 'd1e41d9f-8d06-58a5-b69f-0ffb4cd3deca', 'A', 'Surgical release', false, 0),
  ('2cdea909-29b2-5705-a4a8-33d385e59227', 'd1e41d9f-8d06-58a5-b69f-0ffb4cd3deca', 'B', 'Oral prednisolone', false, 1),
  ('992ef362-9a27-521d-9437-61e91a3925cc', 'd1e41d9f-8d06-58a5-b69f-0ffb4cd3deca', 'C', 'Above-elbow plaster cast', false, 2),
  ('f318699b-efe8-5a18-9795-a7e3a0b3bf86', 'd1e41d9f-8d06-58a5-b69f-0ffb4cd3deca', 'D', 'Activity modification, analgesia (including topical NSAID) and physiotherapy/exercise; most settle within 1 year', true, 3),
  ('d83a9669-232b-537f-a98b-eccc500881ad', 'd1e41d9f-8d06-58a5-b69f-0ffb4cd3deca', 'E', 'Corticosteroid injection as first-line', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6391a541-68fe-51d5-baad-147d5e952ec6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 26 year old man has had lower back pain and stiffness for 1 year. It is worst in the morning, lasts over 1 hour, and improves with exercise but not rest. He has reduced lumbar flexion (Schober''s test 2 cm) and had an episode of anterior uveitis last year. What is the SINGLE most appropriate investigation?', 'Inflammatory back pain in a young man, with reduced spinal movement and uveitis, suggests axial spondyloarthritis (ankylosing spondylitis). MRI can detect sacroiliitis (bone marrow oedema) before X-ray changes appear. HLA-B27 supports the diagnosis. First-line treatment is NSAIDs and physiotherapy, with anti-TNF or IL-17 inhibitors if this fails. Refer to rheumatology.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b66437c0-a160-52a0-8ab9-a85e9587e42a', '6391a541-68fe-51d5-baad-147d5e952ec6', 'A', 'Nerve conduction studies', false, 0),
  ('55a80775-4306-536c-8b56-4ae4570cb030', '6391a541-68fe-51d5-baad-147d5e952ec6', 'B', 'Serum uric acid', false, 1),
  ('5e41bcc3-19ea-5829-af32-9c4d232ac943', '6391a541-68fe-51d5-baad-147d5e952ec6', 'C', 'CT of the abdomen', false, 2),
  ('5ee80c8d-fc62-531f-b923-0f6db98bbefb', '6391a541-68fe-51d5-baad-147d5e952ec6', 'D', 'DEXA scan', false, 3),
  ('9e57b242-ae51-578b-840c-8e3d9da6ee40', '6391a541-68fe-51d5-baad-147d5e952ec6', 'E', 'MRI of the sacroiliac joints (with referral to rheumatology)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ea8418a4-87a0-5f0d-a0ec-a05b9970518a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 76 year old man has exertional chest pain and syncope. He has an ejection systolic murmur radiating to the carotids, a slow-rising pulse and a soft second heart sound. Echo shows a mean aortic valve gradient of 52 mmHg. What is the SINGLE most appropriate management?', 'Severe aortic stenosis (mean gradient over 40 mmHg, valve area under 1 cm², peak velocity over 4 m/s) with symptoms (angina, syncope, heart failure) needs valve intervention, as prognosis without it is poor. TAVI is preferred in older or high-surgical-risk patients, and surgical AVR in younger, lower-risk patients (decided by the heart team). Avoid vasodilators (nitrates, ACE inhibitors at high doses), as they can cause hypotension.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('97ebf858-f94c-5105-bf9f-d78cc4f2a149', 'ea8418a4-87a0-5f0d-a0ec-a05b9970518a', 'A', 'Start a beta-blocker and discharge', false, 0),
  ('f2230288-e3bc-5b1a-9995-30968768be40', 'ea8418a4-87a0-5f0d-a0ec-a05b9970518a', 'B', 'Refer for aortic valve replacement (surgical AVR or TAVI)', true, 1),
  ('641fef50-fb04-5132-8741-01aa01136cbd', 'ea8418a4-87a0-5f0d-a0ec-a05b9970518a', 'C', 'Balloon valvuloplasty as definitive treatment for all', false, 2),
  ('9a54639b-244a-5873-9777-4ffc0eba7918', 'ea8418a4-87a0-5f0d-a0ec-a05b9970518a', 'D', 'Start a high-dose vasodilator', false, 3),
  ('78ac1ae2-3aae-56b5-9a43-d49a8da5518f', 'ea8418a4-87a0-5f0d-a0ec-a05b9970518a', 'E', 'Watchful waiting with echo in 2 years', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6a49de4c-bad4-5cf8-b406-3750588a2afb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 35 year old woman has a BP of 150/95 mmHg on ambulatory monitoring. She is planning a pregnancy next year. She is of African-Caribbean origin. Which antihypertensive is MOST appropriate?', 'ACE inhibitors and ARBs are teratogenic (fetal renal damage and oligohydramnios), particularly in the second and third trimesters, and should be avoided in women planning pregnancy where possible, or switched before conception. Labetalol and nifedipine (and methyldopa) are safe in pregnancy. For African-Caribbean patients not planning pregnancy, a calcium channel blocker would be first-line under NICE.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8a006b9a-3563-5db8-ab04-b967b13debcd', '6a49de4c-bad4-5cf8-b406-3750588a2afb', 'A', 'Labetalol (or nifedipine), avoiding ACE inhibitors and ARBs if she may conceive', true, 0),
  ('f33a94cc-97d8-5de0-9dc8-41b20b8f818e', '6a49de4c-bad4-5cf8-b406-3750588a2afb', 'B', 'Ramipril', false, 1),
  ('22e52f80-76f0-5db2-9fb1-8174e3345225', '6a49de4c-bad4-5cf8-b406-3750588a2afb', 'C', 'Spironolactone', false, 2),
  ('6c344d15-5a33-54f3-8ff3-5301ed8bb9e1', '6a49de4c-bad4-5cf8-b406-3750588a2afb', 'D', 'Losartan', false, 3),
  ('11aacd9e-e47d-5695-b39e-6fe99830e406', '6a49de4c-bad4-5cf8-b406-3750588a2afb', 'E', 'Bendroflumethiazide', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0e95773c-6566-56e3-a6ff-ba9506b37503', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 55 year old man has had stable angina for 6 months. Despite optimal doses of a beta-blocker and a calcium channel blocker, he still has angina on mild exertion. What is the SINGLE most appropriate next step?', 'NICE CG126: if symptoms are not controlled on two antianginal drugs, consider revascularisation (PCI or CABG), guided by angiography and the heart team. A third antianginal (such as ivabradine, nicorandil or ranolazine) is used only while awaiting revascularisation or if revascularisation is not suitable. All patients should have aspirin, a statin and sublingual GTN.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1ca3023d-3c11-55bc-b7b2-d470a42f92df', '0e95773c-6566-56e3-a6ff-ba9506b37503', 'A', 'Add a third antianginal routinely without review', false, 0),
  ('5dc2c95a-dee4-5275-8ee0-ce36e963058c', '0e95773c-6566-56e3-a6ff-ba9506b37503', 'B', 'Stop the beta-blocker', false, 1),
  ('87aefd29-cca9-56dd-baaf-2ab81d1f4164', '0e95773c-6566-56e3-a6ff-ba9506b37503', 'C', 'Increase aspirin to 300 mg daily', false, 2),
  ('f84d5250-c5ac-5fa0-a0b3-125684e685b1', '0e95773c-6566-56e3-a6ff-ba9506b37503', 'D', 'Start warfarin', false, 3),
  ('7f25b476-40d1-5d56-809e-bb27a94af4ea', '0e95773c-6566-56e3-a6ff-ba9506b37503', 'E', 'Refer for consideration of revascularisation (coronary angiography with PCI or CABG)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f9adc731-5cd1-5678-b42f-2a528493c521', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 72 year old woman with AF has a CHA2DS2-VASc score of 4. She also has a history of a GI bleed 3 years ago and an ORBIT bleeding score of 3. What is the SINGLE most appropriate stroke prevention?', 'NICE NG196 recommends anticoagulation with a DOAC for AF with a CHA2DS2-VASc of 2 or more (consider for men with 1). Bleeding risk scores (ORBIT) are used to identify and modify risk factors (BP, alcohol, NSAIDs, anaemia), not to withhold anticoagulation. Aspirin alone is not recommended for stroke prevention in AF. Left atrial appendage occlusion is an option if anticoagulation is contraindicated.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f770b799-e189-5c10-b9b2-2af836a6b094', 'f9adc731-5cd1-5678-b42f-2a528493c521', 'A', 'Offer a DOAC (e.g. apixaban), addressing modifiable bleeding risk factors', true, 0),
  ('43252e6c-2405-58b2-a328-f918c2f3db07', 'f9adc731-5cd1-5678-b42f-2a528493c521', 'B', 'No anticoagulation because of past bleeding', false, 1),
  ('065b2ff3-7c0c-5877-8311-09c5584d88ff', 'f9adc731-5cd1-5678-b42f-2a528493c521', 'C', 'Aspirin 75 mg alone', false, 2),
  ('5221d8aa-1ffd-54f6-a4b7-9ca703c3026e', 'f9adc731-5cd1-5678-b42f-2a528493c521', 'D', 'Warfarin with a target INR of 4', false, 3),
  ('467e21c1-187f-5c00-aef1-e51ecc9158fc', 'f9adc731-5cd1-5678-b42f-2a528493c521', 'E', 'Dual antiplatelet therapy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1e8652da-ebf2-5226-96d0-1026f15acdde', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 64 year old woman on long-term warfarin (target INR 2.5) for a metallic mitral valve has an INR of 7.2. She has no bleeding. What is the SINGLE most appropriate management?', 'BNF guidance: INR over 8 with no bleeding: stop warfarin and give oral vitamin K 1-5 mg. INR 5-8 with no bleeding: withhold 1-2 doses and reduce the maintenance dose. Major bleeding: stop warfarin, give IV vitamin K 5 mg and prothrombin complex concentrate. Be cautious with large vitamin K doses in patients with metallic valves, as it makes re-anticoagulation difficult. Find the cause (interactions, alcohol, illness).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6d3a1a1c-0a44-5f63-b4ad-04dd6cde7439', '1e8652da-ebf2-5226-96d0-1026f15acdde', 'A', 'Continue warfarin at the same dose', false, 0),
  ('dba2182b-7052-5028-a46b-bb09269d84d4', '1e8652da-ebf2-5226-96d0-1026f15acdde', 'B', 'Withhold warfarin, give oral vitamin K (phytomenadione) 1-5 mg, recheck INR next day, and restart when INR is below 5', true, 1),
  ('d59afd99-9efa-5713-8b97-8d3dc183546b', '1e8652da-ebf2-5226-96d0-1026f15acdde', 'C', 'Give IV vitamin K 10 mg and prothrombin complex concentrate', false, 2),
  ('e3754def-94f2-5a84-a180-41095cb92705', '1e8652da-ebf2-5226-96d0-1026f15acdde', 'D', 'Give fresh frozen plasma', false, 3),
  ('958d5563-0bf6-59eb-a0c6-8dc1b3c09486', '1e8652da-ebf2-5226-96d0-1026f15acdde', 'E', 'Stop warfarin permanently', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('501497c7-b117-5fbf-9f5a-8cd26fdc6702', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 30 year old woman with epilepsy takes sodium valproate. She is planning a pregnancy. What is the SINGLE most important advice?', 'Valproate is highly teratogenic (about 10% risk of major malformations, including neural tube defects, and 30-40% risk of neurodevelopmental disorders). Under the MHRA Pregnancy Prevention Programme, women of childbearing potential should not take it unless there is no alternative, and they must use highly effective contraception. Review with a specialist to switch (such as to lamotrigine or levetiracetam) before conception. Stopping suddenly risks status epilepticus.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1d32b45f-f636-56c5-a58a-c6e00c9ed6e4', '501497c7-b117-5fbf-9f5a-8cd26fdc6702', 'A', 'Stop valproate today without review', false, 0),
  ('2e8ebbc3-d256-507b-b087-d1d626203fda', '501497c7-b117-5fbf-9f5a-8cd26fdc6702', 'B', 'Double the dose of valproate', false, 1),
  ('37dcaf42-0ef6-54fa-bb20-115c3982f0b0', '501497c7-b117-5fbf-9f5a-8cd26fdc6702', 'C', 'Do not stop valproate suddenly; seek specialist review to switch to a safer drug before conception, and take high-dose folic acid (5 mg)', true, 2),
  ('7e76ab87-639d-553e-9401-9924ccc58027', '501497c7-b117-5fbf-9f5a-8cd26fdc6702', 'D', 'Switch to phenytoin without specialist input', false, 3),
  ('d99bd6f4-f675-5228-9231-a6b327cb264b', '501497c7-b117-5fbf-9f5a-8cd26fdc6702', 'E', 'Continue valproate as it is safe in pregnancy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('17d00414-50af-5ebf-84b2-6cd965a60a15', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 70 year old man on amiodarone for AF has an INR rise from 2.5 to 4.8 after it was started. Which mechanism is MOST likely?', 'Amiodarone is a potent inhibitor of CYP2C9 (and other enzymes), increasing warfarin levels. Warfarin doses often need to be reduced by 30-50%. The effect can last weeks to months because amiodarone has a very long half-life. Other enzyme inhibitors include clarithromycin, fluconazole, metronidazole and ciprofloxacin. Enzyme inducers (carbamazepine, rifampicin, phenytoin, St John''s wort) reduce the INR.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ed39ea02-51e6-5223-a179-c9c89869f34e', '17d00414-50af-5ebf-84b2-6cd965a60a15', 'A', 'Amiodarone increases vitamin K intake', false, 0),
  ('b6efffbb-2d21-5097-aaea-a7021eb64680', '17d00414-50af-5ebf-84b2-6cd965a60a15', 'B', 'Amiodarone inhibits CYP2C9 and so reduces warfarin metabolism', true, 1),
  ('5179025a-ce1e-5fbc-8a27-b858619a166e', '17d00414-50af-5ebf-84b2-6cd965a60a15', 'C', 'Amiodarone displaces warfarin from albumin only', false, 2),
  ('96f3e708-ca74-5923-bf0b-dcc6dda77f39', '17d00414-50af-5ebf-84b2-6cd965a60a15', 'D', 'Amiodarone increases warfarin renal excretion', false, 3),
  ('db382bf5-c155-5e56-93d1-340301f3a2e6', '17d00414-50af-5ebf-84b2-6cd965a60a15', 'E', 'Amiodarone induces CYP450 enzymes', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f1fb3904-0ecd-56d6-b696-bc3589d9270f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 68 year old man has been taking omeprazole for 10 years. Which complication is he at increased risk of?', 'Long-term PPI use is associated with hypomagnesaemia (check Mg if on long-term PPIs with diuretics or digoxin), C. difficile and other enteric infections, B12 deficiency, osteoporotic fractures and microscopic colitis (lansoprazole). Review the indication regularly and step down to the lowest effective dose or stop if appropriate.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8bb34438-c43c-5acd-804d-3039b3d1ff20', 'f1fb3904-0ecd-56d6-b696-bc3589d9270f', 'A', 'Pulmonary fibrosis', false, 0),
  ('6a4efe30-a10b-5319-910b-3a5126c66d14', 'f1fb3904-0ecd-56d6-b696-bc3589d9270f', 'B', 'Gingival hyperplasia', false, 1),
  ('894641f1-a2d2-57e9-b65b-0ede99b1a851', 'f1fb3904-0ecd-56d6-b696-bc3589d9270f', 'C', 'Hypomagnesaemia, C. difficile infection and fractures', true, 2),
  ('413315f2-775a-5d54-8796-e9dbd358b565', 'f1fb3904-0ecd-56d6-b696-bc3589d9270f', 'D', 'Hypothyroidism', false, 3),
  ('060a62fa-d036-52c0-a3e7-877c18abc914', 'f1fb3904-0ecd-56d6-b696-bc3589d9270f', 'E', 'Hyperkalaemia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f55cd006-848b-5bf9-b1f6-bb0778cfe3e7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 35 year old man has sudden severe left loin-to-groin pain with nausea and microscopic haematuria. Non-contrast CT KUB shows a 4 mm stone at the left vesicoureteric junction. He is afebrile with normal renal function. What is the SINGLE most appropriate management?', 'Most ureteric stones under 5 mm pass spontaneously. NICE NG118 recommends NSAIDs as first-line analgesia (IV paracetamol if NSAIDs are contraindicated), with alpha-blockers (tamsulosin) considered for distal stones under 10 mm to help passage. Urgent decompression (nephrostomy or stent) is needed for an obstructed infected kidney (fever, sepsis), a solitary kidney, or AKI. Larger stones may need shockwave lithotripsy or ureteroscopy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9515aa7e-c030-54db-ac15-14112fbd52ab', 'f55cd006-848b-5bf9-b1f6-bb0778cfe3e7', 'A', 'Analgesia (NSAID first-line) and watchful waiting, with an alpha-blocker considered for distal stones', true, 0),
  ('48cd03a0-b902-536f-8466-299f51b3d371', 'f55cd006-848b-5bf9-b1f6-bb0778cfe3e7', 'B', 'Open surgery', false, 1),
  ('fa762dfb-e6c0-5145-ab1c-db69e5e00519', 'f55cd006-848b-5bf9-b1f6-bb0778cfe3e7', 'C', 'Emergency nephrostomy', false, 2),
  ('a4317633-55f7-5ba6-9e7b-b10171a15daa', 'f55cd006-848b-5bf9-b1f6-bb0778cfe3e7', 'D', 'Percutaneous nephrolithotomy', false, 3),
  ('eb028f5e-bbeb-57b7-af08-770593e721f4', 'f55cd006-848b-5bf9-b1f6-bb0778cfe3e7', 'E', 'IV antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d82b456f-15a8-5e48-bbfc-455f4dcb41cf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 72 year old woman has acute abdominal pain much worse than examination findings suggest. She has AF and is not anticoagulated. Her lactate is 6.2 mmol/L. What is the SINGLE most appropriate investigation?', 'Acute mesenteric ischaemia (often an embolus to the superior mesenteric artery from AF) presents with severe pain out of proportion to the signs, and a raised lactate (a late sign). CT angiography is the investigation of choice. Treatment is resuscitation, heparin, and urgent revascularisation and/or laparotomy with resection of non-viable bowel. Mortality is high, especially if diagnosis is delayed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cf956bad-6a52-5b05-a650-a91d07d12ffb', 'd82b456f-15a8-5e48-bbfc-455f4dcb41cf', 'A', 'CT angiography of the abdomen', true, 0),
  ('b923a16e-0f9c-5404-b2a0-4461c5811b5a', 'd82b456f-15a8-5e48-bbfc-455f4dcb41cf', 'B', 'Abdominal ultrasound only', false, 1),
  ('8002934a-af2d-5edb-8a17-607a13b50c2e', 'd82b456f-15a8-5e48-bbfc-455f4dcb41cf', 'C', 'Colonoscopy', false, 2),
  ('f692c714-1ff8-5609-9f96-10079e678800', 'd82b456f-15a8-5e48-bbfc-455f4dcb41cf', 'D', 'Barium enema', false, 3),
  ('73be1c69-6f13-5dbc-ba05-a1337a0c5e98', 'd82b456f-15a8-5e48-bbfc-455f4dcb41cf', 'E', 'Plain abdominal X-ray only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7f1b4980-751c-5d6d-b223-76259ab98610', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 50 year old man has a duodenal ulcer bleed. After resuscitation, upper GI endoscopy is planned. His Glasgow-Blatchford score is high. Which drug should be given AFTER endoscopic haemostasis?', 'NICE CG141: do not give PPIs before endoscopy in suspected non-variceal upper GI bleeding. After endoscopy, give PPIs to patients with stigmata of recent haemorrhage. Endoscopy should be immediate after resuscitation for unstable patients, and within 24 hours for others. Test for and eradicate H. pylori. The HALT-IT trial showed no benefit from high-dose tranexamic acid. Terlipressin is for variceal bleeding.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8b22c1b0-daeb-596a-98db-aba64c742340', '7f1b4980-751c-5d6d-b223-76259ab98610', 'A', 'PPI before endoscopy routinely for all', false, 0),
  ('655ee496-a7b8-54c1-9619-ced8d8cdaf42', '7f1b4980-751c-5d6d-b223-76259ab98610', 'B', 'Tranexamic acid high dose', false, 1),
  ('8f20c0c2-fdb3-5e2d-b709-bd2f62ca4c66', '7f1b4980-751c-5d6d-b223-76259ab98610', 'C', 'Octreotide', false, 2),
  ('cd299311-2eaf-5c04-9059-0351c7a7b1ee', '7f1b4980-751c-5d6d-b223-76259ab98610', 'D', 'A proton pump inhibitor (e.g. high-dose IV omeprazole/pantoprazole)', true, 3),
  ('7a510509-f141-5391-a679-6895879146f0', '7f1b4980-751c-5d6d-b223-76259ab98610', 'E', 'Terlipressin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('075203a9-2cad-53a5-958e-d8cb0f599df3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 31 year old woman had a massive postpartum haemorrhage needing a 10-unit transfusion 4 months ago. Since then she has been unable to breastfeed, has had no periods, and feels tired and cold. What is the SINGLE most likely diagnosis?', 'The pituitary enlarges in pregnancy and is vulnerable to ischaemia. Severe postpartum haemorrhage with hypotension can cause pituitary infarction (Sheehan''s syndrome). The first sign is often failure of lactation (low prolactin), followed by amenorrhoea, hypothyroidism and adrenal insufficiency. Test pituitary function, and replace cortisol BEFORE thyroxine to avoid an adrenal crisis. Asherman''s (intrauterine adhesions after curettage) causes amenorrhoea but normal lactation and hormones.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('85e9cf11-f27a-5293-a352-18578f3c648c', '075203a9-2cad-53a5-958e-d8cb0f599df3', 'A', 'Postnatal depression', false, 0),
  ('17278d46-ba5a-59db-b720-c2fdd0375b5c', '075203a9-2cad-53a5-958e-d8cb0f599df3', 'B', 'Sheehan''s syndrome (postpartum pituitary necrosis)', true, 1),
  ('451e1dfd-61fc-5a4a-85f4-5a2ed6e6ec29', '075203a9-2cad-53a5-958e-d8cb0f599df3', 'C', 'Asherman''s syndrome', false, 2),
  ('fccf6ee5-fde5-53fc-b3b7-5f533863a0a9', '075203a9-2cad-53a5-958e-d8cb0f599df3', 'D', 'Prolactinoma', false, 3),
  ('b63c6ccd-a5bf-50ef-bbff-772b3728e598', '075203a9-2cad-53a5-958e-d8cb0f599df3', 'E', 'Premature ovarian insufficiency', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('de20597c-bd4c-599d-8707-d25ee511abe3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 3 year old girl has had a low-grade fever and sore mouth for 2 days. She has small painful ulcers on her tongue and buccal mucosa, and small grey vesicles on her palms and soles. She is drinking adequately. What is the SINGLE most appropriate advice?', 'Hand, foot and mouth disease is caused by coxsackievirus A16 or enterovirus 71. It mainly affects children under 10 and causes oral ulcers and vesicles on the hands and feet. It resolves in 7-10 days. Management is supportive (fluids and analgesia). Children do not need to be excluded from school or nursery if they are well enough. Look out for dehydration. It is unrelated to foot-and-mouth disease in animals.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('daf78234-2086-5d0a-8a58-cb720f489b4e', 'de20597c-bd4c-599d-8707-d25ee511abe3', 'A', 'Oral aciclovir', false, 0),
  ('d56c0bd8-4240-5dcc-8d92-e13ae1dbfe89', 'de20597c-bd4c-599d-8707-d25ee511abe3', 'B', 'Oral penicillin V for 10 days', false, 1),
  ('e7c0c52c-a0e7-5009-823b-1a85da5706f8', 'de20597c-bd4c-599d-8707-d25ee511abe3', 'C', 'Self-limiting viral illness (hand, foot and mouth disease): give fluids and analgesia; no need to exclude from nursery if well', true, 2),
  ('dc5dca76-2012-560b-bc8f-b2c978f436dd', 'de20597c-bd4c-599d-8707-d25ee511abe3', 'D', 'Keep off nursery until all blisters have gone', false, 3),
  ('7d638565-7144-532d-a4dd-7e9924dc27ea', 'de20597c-bd4c-599d-8707-d25ee511abe3', 'E', 'Same-day referral to dermatology', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0308a734-50d7-5a06-99b2-36b23e4501cc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A newborn boy is examined before discharge. The urethral opening is on the ventral surface of the penis near the glans, and the foreskin is incomplete ventrally (hooded). Both testes are descended. What is the SINGLE most important advice to the parents?', 'Hypospadias (the urethral meatus lies on the ventral surface) is often associated with a hooded foreskin and chordee (ventral curvature). Refer to paediatric urology. Repair is usually done at 6-18 months, and the foreskin is often used in the repair, so circumcision must be avoided. If hypospadias occurs with undescended testes, investigate for a disorder of sex development.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('67848169-da43-552e-8211-febddbf0b2a9', '0308a734-50d7-5a06-99b2-36b23e4501cc', 'A', 'No referral is needed', false, 0),
  ('c0398790-d89f-5afb-b4d2-63828d5a2700', '0308a734-50d7-5a06-99b2-36b23e4501cc', 'B', 'Arrange urgent karyotype in all cases', false, 1),
  ('0830d927-6342-5a61-9ce0-902ed3c5d48a', '0308a734-50d7-5a06-99b2-36b23e4501cc', 'C', 'Do not have him circumcised, as the foreskin may be needed for surgical repair; refer to paediatric urology', true, 2),
  ('55b3bede-c47b-59bb-85b8-05e50480bbb0', '0308a734-50d7-5a06-99b2-36b23e4501cc', 'D', 'Surgery should be done at 10 years', false, 3),
  ('6736cf08-1e32-562d-b280-313afdf10d7e', '0308a734-50d7-5a06-99b2-36b23e4501cc', 'E', 'Circumcise as soon as possible', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9daf7bb7-d532-5a87-881a-aac09f38ef2b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'An 84 year old woman with advanced macular degeneration is seeing vivid, detailed images of people and flowers that she knows are not real. She is not distressed and has no cognitive impairment or other psychiatric symptoms. What is the SINGLE most likely diagnosis?', 'Charles Bonnet syndrome is complex visual hallucinations in people with significant visual loss, with intact insight and no other psychiatric or cognitive cause. Reassurance and explanation are key, as many patients fear they are developing dementia. Optimise vision and lighting. Dementia with Lewy bodies also causes visual hallucinations, but with fluctuating cognition, parkinsonism and REM sleep behaviour disorder.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('86f784fe-b516-5670-b2e4-e64022c89b5c', '9daf7bb7-d532-5a87-881a-aac09f38ef2b', 'A', 'Late-onset schizophrenia', false, 0),
  ('0c9b23c7-680d-5498-88f9-c88656dbcfcd', '9daf7bb7-d532-5a87-881a-aac09f38ef2b', 'B', 'Temporal lobe epilepsy', false, 1),
  ('28b98f24-006c-5d2e-b866-46a14292b9e4', '9daf7bb7-d532-5a87-881a-aac09f38ef2b', 'C', 'Dementia with Lewy bodies', false, 2),
  ('4cfa10c6-b96b-5f84-a612-13c6fda2a516', '9daf7bb7-d532-5a87-881a-aac09f38ef2b', 'D', 'Delirium', false, 3),
  ('04e13dcb-57cf-55d3-8d2f-e23c0dd3c3a6', '9daf7bb7-d532-5a87-881a-aac09f38ef2b', 'E', 'Charles Bonnet syndrome', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2303406a-5b1b-529e-a45b-e090d5d01650', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 38 year old non-smoker has emphysema, mainly in the lower lobes. He also has mildly abnormal liver function tests. What is the SINGLE most appropriate test?', 'Alpha-1 antitrypsin deficiency (autosomal co-dominant, PiZZ phenotype) causes early-onset, lower-lobe (panacinar) emphysema, worsened by smoking. Liver disease (cirrhosis, hepatocellular carcinoma) comes from misfolded protein building up in hepatocytes. Liver biopsy shows PAS-positive, diastase-resistant globules. Management: stop smoking, standard COPD treatment, and assess for augmentation therapy or transplant.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('134a53ce-6d5d-5f4a-8ca5-3d285990ac67', '2303406a-5b1b-529e-a45b-e090d5d01650', 'A', 'Anti-mitochondrial antibodies', false, 0),
  ('2c17d67e-f141-55ef-b801-edb1a291f3b2', '2303406a-5b1b-529e-a45b-e090d5d01650', 'B', 'Serum alpha-1 antitrypsin level (and phenotype)', true, 1),
  ('325e3b9e-a2b4-552c-96e3-fd6acecce71a', '2303406a-5b1b-529e-a45b-e090d5d01650', 'C', 'Sweat chloride test', false, 2),
  ('1b2d9b40-5a65-59b5-8716-6bcdacb99b2f', '2303406a-5b1b-529e-a45b-e090d5d01650', 'D', 'Serum ferritin', false, 3),
  ('a195c948-cd6e-5734-8448-08009d2c2b4b', '2303406a-5b1b-529e-a45b-e090d5d01650', 'E', 'Serum ACE', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('668e527b-9766-5bf0-b6c9-3c90f1206585', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 60 year old man who served in Burma decades ago is started on high-dose prednisolone. Two weeks later he develops widespread pneumonitis, abdominal pain and Gram-negative sepsis. Which infection MOST likely became overwhelming?', 'Strongyloides can persist for decades through autoinfection. Immunosuppression (especially steroids) can trigger hyperinfection, where larvae migrate through the gut wall, carrying Gram-negative bacteria, and cause pneumonitis and sepsis, with high mortality. Screen with serology, and give empirical ivermectin, before starting steroids in people from endemic areas. Ex-Far East prisoners of war are a classic UK group.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8530c5c0-813c-5f9c-8793-5265dd3521f3', '668e527b-9766-5bf0-b6c9-3c90f1206585', 'A', 'Giardia lamblia', false, 0),
  ('b9aef92f-4b67-5ba7-a366-757083b91d01', '668e527b-9766-5bf0-b6c9-3c90f1206585', 'B', 'Enterobius vermicularis', false, 1),
  ('47b74bb3-4666-5ad0-80cc-99ce9cd5d3d2', '668e527b-9766-5bf0-b6c9-3c90f1206585', 'C', 'Ascaris lumbricoides', false, 2),
  ('2c91e009-a795-54e9-a0e0-e05e95853097', '668e527b-9766-5bf0-b6c9-3c90f1206585', 'D', 'Strongyloides stercoralis (hyperinfection syndrome)', true, 3),
  ('10269766-b97a-568c-b8ca-3d33283266a1', '668e527b-9766-5bf0-b6c9-3c90f1206585', 'E', 'Toxoplasma gondii', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1fc22ab2-9c90-5b26-af9b-a543aee7dace', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 7 year old girl has an itchy scalp. Her mother saw live lice when combing her hair. What is the SINGLE most appropriate advice?', 'Head lice (Pediculus humanus capitis) are treated only if live lice are found. Options are wet combing (''bug busting'', every 4 days for at least 2 weeks) or dimeticone 4% applied twice, 7 days apart. Check household contacts and treat only those with live lice. Exclusion from school is not needed. Nits (empty egg cases) alone do not mean active infestation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b760d2f5-0c1f-5ca0-a692-8c018c87fdad', '1fc22ab2-9c90-5b26-af9b-a543aee7dace', 'A', 'Keep her off school until there are no nits', false, 0),
  ('b43cb951-5c1b-549d-b370-8124fe746a68', '1fc22ab2-9c90-5b26-af9b-a543aee7dace', 'B', 'Treat only if live lice are confirmed: wet combing with a detection comb, or a physical insecticide (e.g. dimeticone 4%) repeated after 7 days; no school exclusion', true, 1),
  ('58db63b0-1c58-5f75-9a88-eee8e8f56407', '1fc22ab2-9c90-5b26-af9b-a543aee7dace', 'C', 'Treat all household members routinely even without lice', false, 2),
  ('d51200e8-cc8e-5057-b1a6-95e93be21d40', '1fc22ab2-9c90-5b26-af9b-a543aee7dace', 'D', 'Shave the head', false, 3),
  ('a81746cf-f986-517f-a107-cd564b1c6235', '1fc22ab2-9c90-5b26-af9b-a543aee7dace', 'E', 'Oral ivermectin for the whole school', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('264294dc-a2c8-503c-ada7-3585923c26fd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 24 year old man has a well-defined, smooth, round bald patch on his scalp for 1 month. The skin looks normal, with short broken ''exclamation mark'' hairs at the margin. He is otherwise well. What is the SINGLE most likely diagnosis?', 'Alopecia areata is autoimmune, non-scarring hair loss with smooth patches and exclamation mark hairs (they taper towards the scalp). It is associated with other autoimmune conditions (thyroid disease, vitiligo). Many patches regrow within 12 months without treatment. Potent topical or intralesional steroids may be used. Tinea capitis causes scaly patches with inflammation, and sometimes a kerion. Trichotillomania gives irregular patches with hairs of differing lengths.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a00c2343-cf1e-5e62-9c6c-d371635fcd79', '264294dc-a2c8-503c-ada7-3585923c26fd', 'A', 'Androgenetic alopecia', false, 0),
  ('3a487f98-df60-555d-a71e-b5cca02a32f3', '264294dc-a2c8-503c-ada7-3585923c26fd', 'B', 'Alopecia areata', true, 1),
  ('9c0d5721-0ad1-5ea4-98f0-750bc473261e', '264294dc-a2c8-503c-ada7-3585923c26fd', 'C', 'Discoid lupus erythematosus', false, 2),
  ('37b7dacf-02c0-5230-9f93-0ff6636a17ab', '264294dc-a2c8-503c-ada7-3585923c26fd', 'D', 'Trichotillomania', false, 3),
  ('d3b184f8-24f6-57da-86b7-0dbd4bfbdcaa', '264294dc-a2c8-503c-ada7-3585923c26fd', 'E', 'Tinea capitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e4c786b3-325e-585f-b8fa-a99d4e350368', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 34 year old woman with type 1 diabetes has shiny, yellow-brown, atrophic plaques with telangiectasia on both shins. What is the SINGLE most likely diagnosis?', 'Necrobiosis lipoidica is associated with diabetes and appears as shiny, yellowish, atrophic plaques with telangiectasia on the shins. It may ulcerate after minor trauma. Treatment is difficult: potent topical steroids for active edges, and protecting from trauma. Pretibial myxoedema (Graves'' disease) causes raised, orange-peel plaques. Erythema nodosum causes tender red nodules.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('95d70666-127c-55f9-827f-c69f7cea9746', 'e4c786b3-325e-585f-b8fa-a99d4e350368', 'A', 'Pretibial myxoedema', false, 0),
  ('32ada5b8-d37f-5397-bc36-17e25ec92afa', 'e4c786b3-325e-585f-b8fa-a99d4e350368', 'B', 'Necrobiosis lipoidica', true, 1),
  ('531c7a17-8b99-5976-b12d-11b774aeef74', 'e4c786b3-325e-585f-b8fa-a99d4e350368', 'C', 'Venous eczema', false, 2),
  ('400b28c7-12bd-5b96-927c-f6def238b135', 'e4c786b3-325e-585f-b8fa-a99d4e350368', 'D', 'Diabetic dermopathy', false, 3),
  ('36fa9105-001b-57c8-b132-f24c17731e2b', 'e4c786b3-325e-585f-b8fa-a99d4e350368', 'E', 'Erythema nodosum', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('91705c83-a1b3-5b8a-b178-59404de40689', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 45 year old obese man has velvety, hyperpigmented skin thickening in his axillae and on the back of his neck. Which condition MOST commonly underlies this?', 'Acanthosis nigricans is velvety, hyperpigmented thickening in skin folds. It is most commonly linked to insulin resistance (obesity, type 2 diabetes, PCOS) and some drugs. Sudden, extensive acanthosis nigricans, especially affecting the mucosae or palms (''tripe palms''), can be paraneoplastic (usually gastric adenocarcinoma) and needs investigation. Treat the underlying cause (weight loss).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d7219aaf-b806-5497-91a1-91549aba58f5', '91705c83-a1b3-5b8a-b178-59404de40689', 'A', 'Addison''s disease', false, 0),
  ('3fd6a8a6-2ecd-57ff-b093-a076c5aebd1d', '91705c83-a1b3-5b8a-b178-59404de40689', 'B', 'Vitamin B12 deficiency', false, 1),
  ('cf08be3c-2b76-56e8-a8ca-5e943ddd7363', '91705c83-a1b3-5b8a-b178-59404de40689', 'C', 'Psoriasis', false, 2),
  ('c9e68840-f905-5e65-8431-6e8e74b92640', '91705c83-a1b3-5b8a-b178-59404de40689', 'D', 'Insulin resistance (e.g. obesity, type 2 diabetes, PCOS)', true, 3),
  ('89907194-3cbe-55d0-9499-15641a1b15ce', '91705c83-a1b3-5b8a-b178-59404de40689', 'E', 'Haemochromatosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a2272738-d37a-5202-b404-54c1deb59205', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 22 year old woman has a firm, raised, shiny, itchy scar on her earlobe that has grown beyond the borders of the original piercing over a year. What is the SINGLE most likely diagnosis?', 'Keloids extend beyond the original wound margins and do not regress. They are more common in people with darker skin and at certain sites (earlobes, chest, shoulders). Hypertrophic scars stay within the wound boundary and often improve over time. Treatment options include intralesional triamcinolone, silicone gel sheets, pressure earrings, cryotherapy and careful excision with adjuvant therapy (simple excision alone has a high recurrence rate).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cc6b334d-f2fc-5345-be1a-cc02891b56fb', 'a2272738-d37a-5202-b404-54c1deb59205', 'A', 'Keloid scar', true, 0),
  ('3632171a-88a2-5625-91a3-241edbbe62b2', 'a2272738-d37a-5202-b404-54c1deb59205', 'B', 'Basal cell carcinoma', false, 1),
  ('52d9c556-f8ca-522c-adc6-a851a5020a8b', 'a2272738-d37a-5202-b404-54c1deb59205', 'C', 'Dermatofibroma', false, 2),
  ('705343c0-e87e-50f7-a865-2835ec38ca6c', 'a2272738-d37a-5202-b404-54c1deb59205', 'D', 'Hypertrophic scar', false, 3),
  ('4dcecd5c-cf1c-5acb-a4c6-f3c35b0c259f', 'a2272738-d37a-5202-b404-54c1deb59205', 'E', 'Epidermoid cyst', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('be610631-7bda-5265-a4e7-946297c39c41', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'An adult has full-thickness and partial-thickness burns involving the entire front of the trunk and the whole of the left arm. Using the Wallace rule of nines, what percentage of total body surface area is burned?', 'Rule of nines in adults: head 9%, each arm 9%, front of trunk 18%, back of trunk 18%, each leg 18%, perineum 1%. Here front of trunk (18%) + one arm (9%) = 27%. Simple erythema is excluded. The Parkland formula (4 mL x kg x %TBSA) estimates the crystalloid needed over the first 24 hours, half in the first 8 hours from the time of the burn. Adults with burns over 15% (10% in children) need formal fluid resuscitation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('49762dc3-55bc-5191-846a-ab281a4e855d', 'be610631-7bda-5265-a4e7-946297c39c41', 'A', '9%', false, 0),
  ('43a215cb-dad4-5b99-9b47-b75f887a733a', 'be610631-7bda-5265-a4e7-946297c39c41', 'B', '18%', false, 1),
  ('33520672-7d19-5a4d-a90a-bbb8e161ad81', 'be610631-7bda-5265-a4e7-946297c39c41', 'C', '27%', true, 2),
  ('e61f8167-ed32-5024-b7cc-2e0e2976b371', 'be610631-7bda-5265-a4e7-946297c39c41', 'D', '36%', false, 3),
  ('52cffdc0-ea9c-54ce-88fd-3033229faa7e', 'be610631-7bda-5265-a4e7-946297c39c41', 'E', '45%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b2a65560-54a0-5530-b6a1-0e160a19ecb2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 55 year old woman with osteoarthritis of the knee has a smooth, fluctuant swelling at the back of her knee. It is more prominent when standing. She then gets sudden calf pain and swelling. Which condition MUST be excluded?', 'A popliteal (Baker''s) cyst comes with knee pathology such as OA and RA. Rupture can cause sudden calf pain and swelling that mimics DVT (pseudothrombophlebitis), and may cause a crescent-shaped bruise at the ankle. DVT must be excluded with duplex ultrasound, which also shows the cyst. Treat the underlying knee pathology.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fcaf3ff9-6b8f-59bf-ade1-d36d4ce77c8f', 'b2a65560-54a0-5530-b6a1-0e160a19ecb2', 'A', 'Septic arthritis of the ankle', false, 0),
  ('eaf0f7bc-c161-51e7-a641-dd2deaa63953', 'b2a65560-54a0-5530-b6a1-0e160a19ecb2', 'B', 'Achilles tendon rupture', false, 1),
  ('1e0ad49f-93b9-52bc-8f1f-ad862bad2846', 'b2a65560-54a0-5530-b6a1-0e160a19ecb2', 'C', 'Peripheral arterial disease', false, 2),
  ('2e28dc8c-4cc8-5999-ad48-fd41758d7233', 'b2a65560-54a0-5530-b6a1-0e160a19ecb2', 'D', 'Deep vein thrombosis (with a ruptured Baker''s cyst as the alternative)', true, 3),
  ('9f8f7088-984c-5490-80f7-06b0b6033c36', 'b2a65560-54a0-5530-b6a1-0e160a19ecb2', 'E', 'Gout', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a50e4c1f-1882-57b7-b7f6-7bda1e99651c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 40 year old man jammed the tip of his middle finger while catching a ball. He now cannot actively extend the distal interphalangeal (DIP) joint, which droops in flexion, although it can be passively straightened. What is the SINGLE most appropriate management?', 'Mallet finger is a disruption of the terminal extensor tendon at the DIP joint (sometimes with an avulsion fracture). Most cases are treated with a mallet splint, keeping the DIP joint continuously extended for 6-8 weeks (any flexion restarts the clock), then night splinting. Large fracture fragments with joint subluxation may need surgery. An untreated mallet can lead to a swan-neck deformity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ce88c83e-a5d4-50ac-ade1-3d4394e5324d', 'a50e4c1f-1882-57b7-b7f6-7bda1e99651c', 'A', 'No treatment', false, 0),
  ('7990492e-f847-59b8-9b45-4b3e0ac9c38c', 'a50e4c1f-1882-57b7-b7f6-7bda1e99651c', 'B', 'Splint the DIP joint in extension (mallet splint) continuously for 6-8 weeks, with X-ray to check for a bony fragment', true, 1),
  ('efcaaa78-0759-5146-b3f7-2156458c16b7', 'a50e4c1f-1882-57b7-b7f6-7bda1e99651c', 'C', 'Immediate surgical repair in all cases', false, 2),
  ('09883284-7451-5477-b64c-cee4600b4d73', 'a50e4c1f-1882-57b7-b7f6-7bda1e99651c', 'D', 'Buddy strapping for 1 week', false, 3),
  ('34587f33-21b6-53b3-ab9a-c0b8277d0556', 'a50e4c1f-1882-57b7-b7f6-7bda1e99651c', 'E', 'Splint in flexion', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('92df0836-1c72-5789-9048-8208a8cf7c3c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 9 year old boy fell onto his outstretched arm. X-ray shows a fracture of the proximal third of the ulna. What associated injury MUST be looked for?', 'A Monteggia injury is a proximal ulnar fracture with radial head dislocation. A Galeazzi injury is a distal radial shaft fracture with distal radioulnar joint dislocation (''MUGR'': Monteggia = Ulna fracture; Galeazzi = Radius fracture). Always X-ray the joints above and below a forearm fracture. A radiocapitellar line that does not pass through the capitellum shows radial head dislocation. The posterior interosseous nerve may be injured.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6e0e99a2-0520-5cdb-9f0b-960dec338a77', '92df0836-1c72-5789-9048-8208a8cf7c3c', 'A', 'Scaphoid fracture', false, 0),
  ('b57b106e-a555-59d7-bf21-f34e0eda097b', '92df0836-1c72-5789-9048-8208a8cf7c3c', 'B', 'Perilunate dislocation', false, 1),
  ('9fd57bff-7095-5b1d-997e-3eb40bf6822c', '92df0836-1c72-5789-9048-8208a8cf7c3c', 'C', 'Distal radioulnar joint dislocation', false, 2),
  ('abe868f0-5cad-5b5e-990f-7eca7cf0fd0d', '92df0836-1c72-5789-9048-8208a8cf7c3c', 'D', 'Dislocation of the radial head (Monteggia fracture-dislocation)', true, 3),
  ('74cfd402-ef13-5097-b0b8-18161b944a08', '92df0836-1c72-5789-9048-8208a8cf7c3c', 'E', 'Supracondylar fracture of the humerus', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('40840b49-13cf-5a21-aa3f-bac5bd05bb9e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 28 year old woman twisted her ankle playing netball. She can bear weight for 4 steps. There is tenderness over the anterior talofibular ligament, but no bony tenderness at the posterior edge or tip of either malleolus, base of the fifth metatarsal or navicular. What is the SINGLE most appropriate management?', 'The Ottawa ankle rules recommend an ankle X-ray only if there is malleolar zone pain plus either bony tenderness at the posterior edge or tip of the lateral or medial malleolus, or inability to bear weight for 4 steps both immediately and in the Emergency Department. A foot X-ray is indicated for midfoot pain with tenderness at the base of the fifth metatarsal or the navicular, or inability to bear weight. Otherwise, manage as a sprain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2974f952-7a59-5cd3-9e59-61838ac373eb', '40840b49-13cf-5a21-aa3f-bac5bd05bb9e', 'A', 'X-ray of the ankle and foot', false, 0),
  ('6b4d4dc8-b0a5-5fa1-9262-af42c3b588df', '40840b49-13cf-5a21-aa3f-bac5bd05bb9e', 'B', 'Orthopaedic referral', false, 1),
  ('175ce3f8-7885-5144-9bac-f92a5eac0f33', '40840b49-13cf-5a21-aa3f-bac5bd05bb9e', 'C', 'MRI of the ankle', false, 2),
  ('a74ec00d-f7c0-59c6-a4fb-e3eaf17a4b52', '40840b49-13cf-5a21-aa3f-bac5bd05bb9e', 'D', 'No X-ray needed; manage as an ankle sprain with rest, ice, compression, elevation and early mobilisation', true, 3),
  ('5e682082-a78d-50ae-869f-cec7d4d38bd1', '40840b49-13cf-5a21-aa3f-bac5bd05bb9e', 'E', 'Below-knee cast for 6 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f33deaf3-9754-5a66-8369-0bc42cd773b4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 15 year old gymnast has had low back pain for 3 months, worse on extension. Lateral lumbar X-ray shows anterior slippage of L5 on S1 with a defect in the pars interarticularis. What is the SINGLE most likely diagnosis?', 'Spondylolysis is a stress fracture of the pars interarticularis, common in adolescents in hyperextension sports (gymnastics, cricket fast bowling). Bilateral defects allow forward slippage (isthmic spondylolisthesis), usually L5 on S1. Oblique views show the ''Scottie dog collar''. Most cases are managed conservatively (rest, physiotherapy). High-grade or progressive slips, or neurological symptoms, need surgery. Degenerative spondylolisthesis affects older adults at L4/5.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('15f58652-0131-5cf9-a3e5-b9b88b2d87f9', 'f33deaf3-9754-5a66-8369-0bc42cd773b4', 'A', 'Ankylosing spondylitis', false, 0),
  ('54241ed3-1434-5c22-bbcf-27baf0899192', 'f33deaf3-9754-5a66-8369-0bc42cd773b4', 'B', 'Isthmic spondylolisthesis (from spondylolysis)', true, 1),
  ('e2ac7ea4-9a27-5805-babb-199035d537e7', 'f33deaf3-9754-5a66-8369-0bc42cd773b4', 'C', 'Degenerative spondylolisthesis', false, 2),
  ('42e31da3-f288-5ebe-b7d9-b8a044354ede', 'f33deaf3-9754-5a66-8369-0bc42cd773b4', 'D', 'Scheuermann''s disease', false, 3),
  ('ac39b3f4-c32d-5327-856e-6421b572c459', 'f33deaf3-9754-5a66-8369-0bc42cd773b4', 'E', 'Lumbar disc prolapse', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9e657c5c-6655-5da5-a521-17dc272f5cc9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'The parents of a newborn ask how to reduce the risk of sudden infant death syndrome (SIDS). Which advice is CORRECT?', 'Safe sleep advice from the Lullaby Trust and NHS: back to sleep, feet-to-foot, no pillows, duvets or bumpers, avoid overheating, a smoke-free environment, room-sharing (in a separate cot) for the first 6 months, and breastfeeding if possible. Never sleep with a baby on a sofa or armchair, and avoid bed-sharing after alcohol, drugs, smoking, or with a premature or low birthweight baby. A dummy at sleep time may reduce risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('94abc356-382e-5641-b11f-f1b3ddacb753', '9e657c5c-6655-5da5-a521-17dc272f5cc9', 'A', 'Put the baby to sleep on their front', false, 0),
  ('cf3b628c-b380-5a4f-aa50-bf9b1e125e96', '9e657c5c-6655-5da5-a521-17dc272f5cc9', 'B', 'Put the baby to sleep on their back, in their own cot in the parents'' room for the first 6 months, in a smoke-free home, with feet to the foot of the cot', true, 1),
  ('e12ab69b-0e73-5f16-bdf4-288dfe3ab6ef', '9e657c5c-6655-5da5-a521-17dc272f5cc9', 'C', 'Use pillows and duvets to keep the baby warm', false, 2),
  ('74ef8c2c-36b7-5055-a6ba-8ef215702ed5', '9e657c5c-6655-5da5-a521-17dc272f5cc9', 'D', 'Bed-share after drinking alcohol is safe if careful', false, 3),
  ('8ab8a6f1-64ac-5f81-85c2-eca185b8ba21', '9e657c5c-6655-5da5-a521-17dc272f5cc9', 'E', 'Sleep on a sofa with the baby to settle them', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e74ff479-779b-5616-aaac-e48026429b3e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 40 year old farm worker is brought in after spraying pesticides. He has pinpoint pupils, profuse salivation, lacrimation, sweating, diarrhoea, bradycardia, wheeze and muscle fasciculations. What is the SINGLE most appropriate treatment?', 'Organophosphate poisoning inhibits acetylcholinesterase and causes a cholinergic crisis. Muscarinic features are summarised by DUMBELS (diarrhoea, urination, miosis, bradycardia/bronchorrhoea/bronchospasm, emesis, lacrimation, salivation/sweating). Nicotinic features are fasciculations and weakness. Staff should wear PPE and decontaminate the patient. Give IV atropine in doubling doses until the chest is clear of secretions. Pralidoxime (an oxime) may reactivate the enzyme. Watch for respiratory failure.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('045ae8ef-6cf1-593f-87d9-5798494a77d3', 'e74ff479-779b-5616-aaac-e48026429b3e', 'A', 'IV physostigmine', false, 0),
  ('d3a2fd2e-1938-5e1e-ab4a-e08762c2d74b', 'e74ff479-779b-5616-aaac-e48026429b3e', 'B', 'IV atropine, titrated to dry chest secretions (with pralidoxime considered), after decontamination', true, 1),
  ('b7f46860-cde4-527d-b77a-ff0a581aa4dd', 'e74ff479-779b-5616-aaac-e48026429b3e', 'C', 'IV naloxone', false, 2),
  ('f1e22456-aeaf-58dc-b818-76e22a2ac5a3', 'e74ff479-779b-5616-aaac-e48026429b3e', 'D', 'IV flumazenil', false, 3),
  ('725d3c7d-7984-5575-87b5-d9d61d878fd9', 'e74ff479-779b-5616-aaac-e48026429b3e', 'E', 'IV adrenaline', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0c9c7a1b-a850-56c7-9b73-346d3ba36cc3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 52 year old woman took a large overdose of propranolol 2 hours ago. Her HR is 38 bpm and BP is 70/40 mmHg despite IV atropine and fluids. What is the SINGLE most appropriate specific treatment?', 'Beta-blocker overdose causes bradycardia, hypotension, hypoglycaemia and (with propranolol) seizures and QRS widening. After atropine, glucagon raises cardiac output by stimulating adenylate cyclase independently of beta-receptors. High-dose insulin euglycaemic therapy, inotropes or vasopressors, and pacing are also used. Lipid emulsion is considered for propranolol (which is lipophilic). Seek TOXBASE or NPIS advice.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('24e1dadf-d028-55b0-9c24-20a24b49518f', '0c9c7a1b-a850-56c7-9b73-346d3ba36cc3', 'A', 'IV flumazenil', false, 0),
  ('cec9e946-a480-5972-a358-ffc455c7210c', '0c9c7a1b-a850-56c7-9b73-346d3ba36cc3', 'B', 'IV acetylcysteine', false, 1),
  ('be6b9f24-2a35-568c-928e-b451bd91f389', '0c9c7a1b-a850-56c7-9b73-346d3ba36cc3', 'C', 'IV naloxone', false, 2),
  ('bac05eeb-941c-51b8-9e58-da0c807d448b', '0c9c7a1b-a850-56c7-9b73-346d3ba36cc3', 'D', 'IV glucagon (and high-dose insulin euglycaemic therapy, with expert advice)', true, 3),
  ('fe54e239-6c87-53f6-9b0b-5c45b0d4f5c6', '0c9c7a1b-a850-56c7-9b73-346d3ba36cc3', 'E', 'IV digoxin-specific antibody fragments', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('126c7a82-314d-5841-97cb-d7e3a9213d5b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 35 year old man was bitten on his ankle by a snake while walking on heathland in southern England 1 hour ago. He now has spreading swelling up to his knee, vomiting and a BP of 85/50 mmHg. What is the SINGLE most appropriate specific treatment?', 'The adder (Vipera berus) is the UK''s only native venomous snake. Most bites cause only local swelling. Antivenom (ViperaTAb) is indicated for systemic envenoming (hypotension, vomiting, ECG changes, leucocytosis, coagulopathy) or significant spreading swelling (beyond the wrist after a hand bite, or the ankle after a foot bite, within 4 hours). Immobilise the limb. Do not use tourniquets, incision or suction. Observe all bites for at least 24 hours if there are any signs, and check tetanus status.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('521609b4-7c21-541c-8a16-418b614f5f3f', '126c7a82-314d-5841-97cb-d7e3a9213d5b', 'A', 'European viper antivenom (adder) given IV, with supportive care', true, 0),
  ('aa4933e9-1b05-591e-a081-924a782d11bb', '126c7a82-314d-5841-97cb-d7e3a9213d5b', 'B', 'Apply a tourniquet above the bite', false, 1),
  ('15166ac5-1226-5590-aa96-a71bdd25b8dd', '126c7a82-314d-5841-97cb-d7e3a9213d5b', 'C', 'Observe for 2 hours and discharge', false, 2),
  ('32705c06-6862-57dc-882c-71efeb9400e8', '126c7a82-314d-5841-97cb-d7e3a9213d5b', 'D', 'IV antibiotics only', false, 3),
  ('070dec94-0d4f-5ba9-97a9-c08f336b6da1', '126c7a82-314d-5841-97cb-d7e3a9213d5b', 'E', 'Incise and suck the wound', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e9a736ff-ad9a-5d18-8778-1312e46e8980', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 28 year old woman who is 30 weeks pregnant returned from South Asia 5 weeks ago. She has jaundice, malaise and a very high ALT. Hepatitis A, B and C serology is negative. Which virus is MOST likely, and why is it important?', 'Hepatitis E is spread by the faecal-oral route (genotypes 1/2 in Asia and Africa through water; genotype 3 in the UK through undercooked pork). It is usually self-limiting, but genotypes 1/2 in pregnancy cause fulminant hepatitis with high maternal mortality. In immunosuppressed people, genotype 3 can become chronic. Diagnosis is by HEV IgM or PCR. Hepatitis D needs hepatitis B co-infection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('87896040-51b2-55f6-a13c-ddab8d3b5e5c', 'e9a736ff-ad9a-5d18-8778-1312e46e8980', 'A', 'Hepatitis E — it can cause fulminant hepatic failure in pregnancy (especially the third trimester)', true, 0),
  ('fe391b50-ec4c-5d09-8bd2-c34a532c3910', 'e9a736ff-ad9a-5d18-8778-1312e46e8980', 'B', 'Hepatitis D — only infects people with hepatitis C', false, 1),
  ('293ddad8-a1d0-5f6c-8326-0ad13cbabb86', 'e9a736ff-ad9a-5d18-8778-1312e46e8980', 'C', 'CMV — always causes fatal hepatitis', false, 2),
  ('66d132f6-602c-556f-aebe-610e2e33eec7', 'e9a736ff-ad9a-5d18-8778-1312e46e8980', 'D', 'Hepatitis A — it is never self-limiting', false, 3),
  ('56720628-ecc8-5ff6-9b69-6427754c2bd7', 'e9a736ff-ad9a-5d18-8778-1312e46e8980', 'E', 'Hepatitis G — common cause of liver failure', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6cc5dd08-9fbc-52bb-8e65-8404f0f82cbe', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 50 year old man is crushed by a car. His right chest wall moves inward on inspiration and outward on expiration. He is in severe pain and his SpO2 is 89% on high-flow oxygen. What is the SINGLE most likely diagnosis?', 'Flail chest happens when 2 or more adjacent ribs are each fractured in 2 or more places, creating a free segment that moves paradoxically. Hypoxia is mainly caused by the underlying pulmonary contusion. Management: oxygen, excellent analgesia (epidural or regional blocks), physiotherapy, careful fluid management, and ventilation if respiratory failure develops. Surgical rib fixation is increasingly used.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4c6f4b3c-84d4-57ef-99d7-5848f7b8e2e2', '6cc5dd08-9fbc-52bb-8e65-8404f0f82cbe', 'A', 'Massive haemothorax', false, 0),
  ('20eb9956-9998-5dfe-b863-91e597554497', '6cc5dd08-9fbc-52bb-8e65-8404f0f82cbe', 'B', 'Diaphragmatic rupture', false, 1),
  ('4ec2ec36-0bd2-5d51-ba9d-14a1bb3de031', '6cc5dd08-9fbc-52bb-8e65-8404f0f82cbe', 'C', 'Simple rib fracture', false, 2),
  ('9f573783-1d50-5494-b2ca-425d01c66aee', '6cc5dd08-9fbc-52bb-8e65-8404f0f82cbe', 'D', 'Flail chest', true, 3),
  ('736e842a-3544-58fc-9cff-f95ef31c644f', '6cc5dd08-9fbc-52bb-8e65-8404f0f82cbe', 'E', 'Cardiac tamponade', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a29f8b0a-c761-5c60-9623-8a2d68105ccd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 30 year old woman has fatigue and breathlessness. On auscultation there is an ejection systolic murmur in the pulmonary area with fixed splitting of the second heart sound that does not vary with respiration. ECG shows right bundle branch block with right axis deviation. What is the SINGLE most likely diagnosis?', 'An ASD causes a left-to-right shunt and increased flow across the pulmonary valve (the flow murmur). Fixed splitting of S2 is characteristic. Secundum ASD gives RBBB with right axis deviation, and primum ASD gives left axis deviation. Complications include atrial arrhythmias, paradoxical emboli, pulmonary hypertension and Eisenmenger syndrome. Significant defects are closed (often percutaneously).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fa9b0973-5487-547d-afe3-1d964e411447', 'a29f8b0a-c761-5c60-9623-8a2d68105ccd', 'A', 'Ventricular septal defect', false, 0),
  ('13e8d752-ea24-5cca-abaa-acffa9e34caf', 'a29f8b0a-c761-5c60-9623-8a2d68105ccd', 'B', 'Ostium secundum atrial septal defect', true, 1),
  ('216c920c-2680-552e-bb22-b029b6707cfe', 'a29f8b0a-c761-5c60-9623-8a2d68105ccd', 'C', 'Mitral stenosis', false, 2),
  ('aa548f9e-a626-5c5a-9308-e4601831dccb', 'a29f8b0a-c761-5c60-9623-8a2d68105ccd', 'D', 'Patent ductus arteriosus', false, 3),
  ('f29b98ab-1a99-525e-aa06-bf2f62613fa2', 'a29f8b0a-c761-5c60-9623-8a2d68105ccd', 'E', 'Coarctation of the aorta', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d1040e3a-0c96-58bc-a748-3f9a39acecb0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 35 year old man who smokes 30 cigarettes a day has painful ulcers on his fingertips, rest pain in his toes and migratory superficial thrombophlebitis. He has no diabetes or hyperlipidaemia. What is the SINGLE most likely diagnosis?', 'Buerger''s disease is a non-atherosclerotic inflammatory vasculitis of small and medium arteries and veins in young male heavy smokers. It causes distal ischaemia (digital ulcers and gangrene), claudication of the feet, Raynaud''s and superficial thrombophlebitis. Complete smoking cessation is the only effective treatment, and amputation is common if smoking continues. Angiography shows ''corkscrew'' collaterals.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c5ad2c58-8fb1-5bf2-a1f8-fd16d641e037', 'd1040e3a-0c96-58bc-a748-3f9a39acecb0', 'A', 'Systemic sclerosis', false, 0),
  ('7ac45192-76a5-5ea5-83b8-9ed02028909a', 'd1040e3a-0c96-58bc-a748-3f9a39acecb0', 'B', 'Raynaud''s disease', false, 1),
  ('5e686eaa-405c-542b-af97-fe906b7b94b5', 'd1040e3a-0c96-58bc-a748-3f9a39acecb0', 'C', 'Takayasu arteritis', false, 2),
  ('cdfef5da-aec8-51d2-8d0b-ef5e542ea2cd', 'd1040e3a-0c96-58bc-a748-3f9a39acecb0', 'D', 'Atherosclerotic peripheral arterial disease', false, 3),
  ('50e71b35-d233-5f37-90fe-ba5d97ca588e', 'd1040e3a-0c96-58bc-a748-3f9a39acecb0', 'E', 'Thromboangiitis obliterans (Buerger''s disease)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cf9dad6b-c708-5e27-a8e2-74d8637e94f8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 62 year old woman has a platelet count of 980 x10^9/L on two occasions. Iron studies, CRP and the blood film are otherwise unremarkable apart from large platelets. She has had burning pain and redness in her fingers. Which mutation is MOST likely to be found?', 'Essential thrombocythaemia is a myeloproliferative neoplasm with persistent thrombocytosis. JAK2 is mutated in about 55%, CALR in about 25% and MPL in about 5%. Exclude reactive causes (iron deficiency, infection, malignancy, splenectomy) and CML (BCR-ABL1). Erythromelalgia (burning red extremities) responds to aspirin. High-risk patients (over 60, previous thrombosis) need cytoreduction (hydroxycarbamide).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0feba7c9-29e5-5c47-9a53-8594c450cf4e', 'cf9dad6b-c708-5e27-a8e2-74d8637e94f8', 'A', 'BCR-ABL1', false, 0),
  ('19e439c8-b592-5cd9-8a5f-a13e7575a723', 'cf9dad6b-c708-5e27-a8e2-74d8637e94f8', 'B', 'JAK2 V617F (or CALR/MPL)', true, 1),
  ('43b8f130-90fc-5c48-9993-aa7617bd259d', 'cf9dad6b-c708-5e27-a8e2-74d8637e94f8', 'C', 'FLT3', false, 2),
  ('39615613-e749-5f64-be89-42ab6b0dee12', 'cf9dad6b-c708-5e27-a8e2-74d8637e94f8', 'D', 'PML-RARA', false, 3),
  ('3ab596c8-a947-52f8-a7b3-b26bde1c93f7', 'cf9dad6b-c708-5e27-a8e2-74d8637e94f8', 'E', 'BRAF V600E', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('70b056f9-7c1d-573e-b62d-31f6327a3318', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 9 year old boy from Malawi has a rapidly growing jaw mass. Biopsy shows sheets of medium-sized lymphocytes with a ''starry sky'' appearance. Which genetic abnormality is MOST characteristic?', 'Burkitt lymphoma is a highly aggressive B-cell NHL with MYC translocation, usually t(8;14). The endemic form (Africa, associated with EBV and malaria) affects the jaw. The sporadic form often presents with an abdominal mass, and it is also associated with HIV. Histology shows a ''starry sky'' (macrophages among sheets of tumour cells). It responds well to intensive chemotherapy but has a high risk of tumour lysis syndrome. t(14;18) is follicular lymphoma and t(11;14) is mantle cell lymphoma.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2e6918fe-e1cb-5f12-bf25-1bf3fe865c71', '70b056f9-7c1d-573e-b62d-31f6327a3318', 'A', 't(15;17) PML-RARA', false, 0),
  ('04cff8e9-9706-581c-9df9-de3a6fc8ea4b', '70b056f9-7c1d-573e-b62d-31f6327a3318', 'B', 't(14;18) BCL2', false, 1),
  ('0bd31762-b93f-52aa-9b04-5a4a2fe9d8bc', '70b056f9-7c1d-573e-b62d-31f6327a3318', 'C', 't(9;22) BCR-ABL1', false, 2),
  ('7aa37ecc-aa19-5884-92d6-e3a4e5c0fca8', '70b056f9-7c1d-573e-b62d-31f6327a3318', 'D', 't(11;14) cyclin D1', false, 3),
  ('77844cfd-b038-5bc3-b632-08ebb1da0ee0', '70b056f9-7c1d-573e-b62d-31f6327a3318', 'E', 't(8;14) translocation involving MYC', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('14e0d2a3-b49e-56ee-bef2-9b6443e1e963', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 70 year old man has fatigue, blurred vision, headaches and nosebleeds. He has lymphadenopathy and hepatosplenomegaly. Serum protein electrophoresis shows a large IgM paraprotein, and fundoscopy shows dilated retinal veins and haemorrhages. What is the SINGLE most likely diagnosis?', 'Waldenström''s macroglobulinaemia (lymphoplasmacytic lymphoma, with MYD88 L265P mutation in about 90%) produces IgM paraprotein, causing hyperviscosity syndrome (visual disturbance, headache, bleeding, retinal ''sausage'' veins). There is lymphadenopathy and organomegaly, but usually no lytic bone lesions (unlike myeloma). Symptomatic hyperviscosity needs urgent plasma exchange, then chemoimmunotherapy (such as rituximab-based) or BTK inhibitors.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cbfaed6d-e5e5-5f63-a8bc-9c74aa9d4dbb', '14e0d2a3-b49e-56ee-bef2-9b6443e1e963', 'A', 'MGUS', false, 0),
  ('12186a2b-8fb1-5c5e-b765-721eb07fb559', '14e0d2a3-b49e-56ee-bef2-9b6443e1e963', 'B', 'Chronic lymphocytic leukaemia', false, 1),
  ('0a350e82-003b-59a8-bd65-097acaba6333', '14e0d2a3-b49e-56ee-bef2-9b6443e1e963', 'C', 'Hodgkin lymphoma', false, 2),
  ('c2f66dac-99c7-515f-af27-ef816a013c8e', '14e0d2a3-b49e-56ee-bef2-9b6443e1e963', 'D', 'Multiple myeloma', false, 3),
  ('a81cb426-c630-5978-87f9-c1f0ac00fe02', '14e0d2a3-b49e-56ee-bef2-9b6443e1e963', 'E', 'Waldenström''s macroglobulinaemia', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a0425657-34b7-5a90-8172-268e0f4dbe82', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 55 year old man with diabetes has a crush injury to his leg. Twenty-four hours later the wound is extremely painful, with brown discharge, crepitus in the tissues and rapidly spreading discolouration. He is hypotensive. What is the SINGLE most likely causative organism?', 'Gas gangrene (clostridial myonecrosis) follows contaminated traumatic wounds. It causes severe pain out of proportion to the signs, crepitus (gas), ''dishwater'' discharge, rapid spread and toxic shock. X-ray or CT shows gas in the tissues. Treatment is emergency surgical debridement (possibly amputation), high-dose IV benzylpenicillin plus clindamycin, and supportive care. Hyperbaric oxygen is sometimes used.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9d402501-3f2b-5875-941b-7cf1ed134e7e', 'a0425657-34b7-5a90-8172-268e0f4dbe82', 'A', 'Clostridium perfringens (gas gangrene)', true, 0),
  ('9f3ff76a-3364-5437-9f07-1d04e08b311e', 'a0425657-34b7-5a90-8172-268e0f4dbe82', 'B', 'Streptococcus pneumoniae', false, 1),
  ('246c0a91-30aa-5331-9dc0-915c037ddd24', 'a0425657-34b7-5a90-8172-268e0f4dbe82', 'C', 'Pseudomonas aeruginosa', false, 2),
  ('80ede628-a2f6-5b9c-9d2c-8f525204b94a', 'a0425657-34b7-5a90-8172-268e0f4dbe82', 'D', 'Escherichia coli', false, 3),
  ('db3f80b7-4139-5cf7-b68c-3d27abc3ad3e', 'a0425657-34b7-5a90-8172-268e0f4dbe82', 'E', 'Staphylococcus aureus', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0c6b2d9d-16bd-5fdf-b8f9-5eb147ce5545', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 26 year old man has had intense itching in his pubic hair for 2 weeks. On examination there are small grey-brown ''specks'' attached to the hairs and tiny blue macules on the lower abdomen. What is the SINGLE most appropriate management?', 'Pubic lice (Phthirus pubis, ''crabs'') are mainly sexually transmitted. Lice and eggs attach to pubic, axillary, chest hair and even eyelashes. Maculae caeruleae are blue-grey macules from bites. Treat with permethrin or malathion applied to all hairy areas and repeated after 7 days. Treat sexual partners from the past 3 months. Wash bedding at 50°C or above. Screen for other STIs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a5fc7ea6-dc03-58f6-a5ed-3479a9a2db05', '0c6b2d9d-16bd-5fdf-b8f9-5eb147ce5545', 'A', 'Topical permethrin 5% or malathion 0.5% (repeat after 7 days), treat partners, and screen for other STIs', true, 0),
  ('1ab606fa-74fe-5885-bbb9-d9685d24d64b', '0c6b2d9d-16bd-5fdf-b8f9-5eb147ce5545', 'B', 'Oral aciclovir', false, 1),
  ('265f52f2-5a55-5597-b772-984130cbcca2', '0c6b2d9d-16bd-5fdf-b8f9-5eb147ce5545', 'C', 'Topical hydrocortisone', false, 2),
  ('5a7787d9-4538-586c-b5fc-f1a949b8c310', '0c6b2d9d-16bd-5fdf-b8f9-5eb147ce5545', 'D', 'Shave the area as the only treatment', false, 3),
  ('bd5a028c-68bd-579e-b41b-35adec9d9872', '0c6b2d9d-16bd-5fdf-b8f9-5eb147ce5545', 'E', 'Oral fluconazole', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5cd21e55-7b6a-5e81-a4f4-4c5d8a80dfda', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 68 year old man with severe COPD has worsening ankle oedema, a raised JVP and a loud P2. His SpO2 at rest is 86% on air. ECG shows right axis deviation and P pulmonale. What is the SINGLE most likely diagnosis?', 'Cor pulmonale is right ventricular failure caused by pulmonary hypertension from chronic lung disease (COPD, ILD, OSA) through hypoxic pulmonary vasoconstriction. Signs include a raised JVP, peripheral oedema, a loud P2, a parasternal heave and tricuspid regurgitation. Treatment is a loop diuretic for oedema, long-term oxygen therapy if criteria are met (PaO2 under 7.3 kPa, or under 8 with cor pulmonale), and treating the underlying lung disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('dedd6176-302b-5b45-8b01-467b9e4aa995', '5cd21e55-7b6a-5e81-a4f4-4c5d8a80dfda', 'A', 'Constrictive pericarditis', false, 0),
  ('525928fe-878d-53d5-abbf-c05766b46290', '5cd21e55-7b6a-5e81-a4f4-4c5d8a80dfda', 'B', 'Nephrotic syndrome', false, 1),
  ('8dead404-2ae4-5af6-9d3f-fc721e9fe86f', '5cd21e55-7b6a-5e81-a4f4-4c5d8a80dfda', 'C', 'Left ventricular failure', false, 2),
  ('7714c2e3-fa75-53f2-8f16-2b429d08d657', '5cd21e55-7b6a-5e81-a4f4-4c5d8a80dfda', 'D', 'Cor pulmonale (right heart failure secondary to lung disease)', true, 3),
  ('9f354112-c58c-5be9-bfe4-e19282609747', '5cd21e55-7b6a-5e81-a4f4-4c5d8a80dfda', 'E', 'Cirrhosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b0617719-e263-5d6a-8503-978ba55b2e15', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 60 year old man has severe pain in his right ear, followed by vesicles in his ear canal and on his pinna, and a right-sided facial weakness involving his forehead. He also has vertigo and hearing loss on the same side. What is the SINGLE most likely diagnosis?', 'Ramsay Hunt syndrome is reactivation of varicella-zoster virus in the geniculate ganglion. It causes ear pain, a vesicular rash in the ear canal or pinna (or palate), lower motor neurone facial palsy, and sometimes vertigo and sensorineural hearing loss (VIII involvement). Treat with oral aciclovir/valaciclovir and prednisolone, ideally within 72 hours. Protect the eye. Recovery is less complete than in Bell''s palsy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('050b64f2-3d4d-5a0c-b7c4-b58d15ca5f57', 'b0617719-e263-5d6a-8503-978ba55b2e15', 'A', 'Acoustic neuroma', false, 0),
  ('04070aee-bd7b-5e10-92bc-87a1236c2c4a', 'b0617719-e263-5d6a-8503-978ba55b2e15', 'B', 'Ramsay Hunt syndrome (herpes zoster oticus)', true, 1),
  ('2ebc06cf-3691-5e73-bac1-de6606cbc525', 'b0617719-e263-5d6a-8503-978ba55b2e15', 'C', 'Cholesteatoma', false, 2),
  ('00c677e4-ab52-563e-aaf8-dd1e0cf5a1db', 'b0617719-e263-5d6a-8503-978ba55b2e15', 'D', 'Bell''s palsy', false, 3),
  ('421d63f6-f0dc-5a98-b26d-40c7d8edfe85', 'b0617719-e263-5d6a-8503-978ba55b2e15', 'E', 'Acute otitis externa', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c5f56015-2906-5f12-8073-759b95090d52', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 4 month old baby has had a cough and coryza for 3 days. He now has a respiratory rate of 62/min, subcostal recession, widespread fine crackles and wheeze, and is taking 40% of his usual feeds. His SpO2 is 90% on air. What is the SINGLE most appropriate management?', 'This is bronchiolitis (most often RSV) in an infant. NICE NG9 advises admission for apnoea, persistent SpO2 under 92% on air, oral intake under 50-75% of normal, or severe respiratory distress (grunting, marked recession, RR over 70). Treatment is supportive: oxygen, NG or IV fluids, and nasal suction if needed. Bronchodilators, steroids, antibiotics and physiotherapy are not recommended. A long-acting RSV monoclonal antibody (nirsevimab) and maternal RSV vaccination are now used for prevention.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6ed8fdd0-658f-5038-9fe5-22c21914c2cb', 'c5f56015-2906-5f12-8073-759b95090d52', 'A', 'Admit for supportive care: supplemental oxygen and nasogastric or IV fluids', true, 0),
  ('265dc41a-f095-5734-9294-9d0c34aebc2a', 'c5f56015-2906-5f12-8073-759b95090d52', 'B', 'Chest physiotherapy at home', false, 1),
  ('3dcb81ad-7ef6-5bc1-93cd-1688eee732f1', 'c5f56015-2906-5f12-8073-759b95090d52', 'C', 'Oral prednisolone', false, 2),
  ('18a9327a-a81f-55a9-89df-b6e727fe0d31', 'c5f56015-2906-5f12-8073-759b95090d52', 'D', 'Nebulised salbutamol and discharge', false, 3),
  ('d963a2a0-270e-5870-a5e4-78c0717fb51e', 'c5f56015-2906-5f12-8073-759b95090d52', 'E', 'Oral amoxicillin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e3707155-f791-5065-b4a8-c44b061136e4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 28 year old woman gave birth 8 days ago. She has rapidly developed confusion, insomnia, agitation, fluctuating mood and a belief that her baby has been swapped. She has a history of bipolar disorder. What is the SINGLE most appropriate management?', 'Postpartum (puerperal) psychosis is a psychiatric emergency, usually starting in the first 2 weeks after birth. It is strongly linked to bipolar disorder and causes rapid onset of mania, psychosis, confusion and a risk to mother and baby. Arrange urgent assessment and admission to a mother and baby unit, and treat with antipsychotics, mood stabilisers or ECT. ''Baby blues'' peaks at days 3-5, is mild, and resolves within 2 weeks.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6dc91f38-3adf-5e0b-8686-35446bd4d666', 'e3707155-f791-5065-b4a8-c44b061136e4', 'A', 'Advise her to stop breastfeeding only', false, 0),
  ('8da91129-c8b2-5e8b-a7b6-972e20afe706', 'e3707155-f791-5065-b4a8-c44b061136e4', 'B', 'Reassure that this is ''baby blues'' and review in 2 weeks', false, 1),
  ('c1482594-ee1b-50dd-9dca-3ab1e962752a', 'e3707155-f791-5065-b4a8-c44b061136e4', 'C', 'Start an SSRI in primary care and review in 4 weeks', false, 2),
  ('2b486913-28b0-5962-b28c-5b1455f5ce66', 'e3707155-f791-5065-b4a8-c44b061136e4', 'D', 'Refer for routine counselling', false, 3),
  ('371d8ac7-68ea-5c84-b1ed-b30a04980dd6', 'e3707155-f791-5065-b4a8-c44b061136e4', 'E', 'Urgent psychiatric assessment and admission, ideally to a mother and baby unit', true, 4);
